-- קטעי קריאה: מנת שבת 2026-09-05 (80 קטעים / 400 שאלות, מנות A,B,C,D,F,G,H,I). אידמפוטנטי לפי title. תיעוד: claude/READING_batch_shabbat_2026-09-05.md
do $$ declare v_pid uuid; begin

  if not exists (select 1 from reading_passages where title = $q$The Dancing Language of Honeybees$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Dancing Language of Honeybees$q$, $q$In the 1940s, the Austrian scientist Karl von Frisch made a surprising discovery about the way honeybees share information. He noticed that a bee returning from a rich source of food performed a special movement on the honeycomb. Other bees gathered closely around the dancer, and soon afterward they flew out of the hive and found the same flowers. Von Frisch called this movement the waggle dance, and he spent many years of patient observation working out what it meant. In 1973 he shared the Nobel Prize with two other scientists for his research on animal behavior.

The dance is shaped like a figure eight, with a straight run through the middle of the pattern. During the straight run, the bee shakes its body from side to side, which is where the name comes from. The angle of this run tells the other bees the direction of the food in relation to the sun. The length of the run tells them how far away the food is, with longer runs meaning greater distances. In this way, a single dance can describe a location that may be several kilometers from the hive.

At first, many scientists doubted that an insect could communicate such detailed information. However, later experiments confirmed that bees really do use the information in the dance to find food. Researchers even built small robotic bees that could perform the dance, and real bees followed their instructions to the food. Today the waggle dance is considered one of the most remarkable forms of communication in the animal world. It shows that complex messages do not always require a large brain or a spoken language.$q$, $q$science / biology$q$, 3, 274, true, $q$reading_shabbat_2026-09-05_A$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["A scientist discovered that honeybees use a special dance to communicate the location of food to their hive mates.", "Karl von Frisch received the Nobel Prize in 1973 for his lifelong research on animal behavior.", "Robotic bees built by researchers were able to direct real bees to sources of food.", "Insects with small brains are unable to communicate detailed information to one another."]$q$::jsonb, 0, $q$["נכון. הקטע כולו עוסק בגילוי של פון פריש שדבורים משתמשות בריקוד הנענוע כדי למסור לחברותיהן את מיקום המזון.", "לא נכון. פרס הנובל מוזכר בפסקה הראשונה כפרט אחד בלבד, ולא כרעיון המרכזי של הקטע.", "לא נכון. הדבורים הרובוטיות מוזכרות בפסקה השלישית כדוגמה לניסוי, ולא כנושא הקטע.", "לא נכון. הפסקה האחרונה טוענת את ההפך — מסרים מורכבים אינם דורשים בהכרח מוח גדול."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch A, passage=honeybee_dance, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the third paragraph, the word "doubted" is closest in meaning to —$q$, $q$["confirmed through careful experiments", "did not believe", "discussed at length in public", "were excited to hear about"]$q$::jsonb, 1, $q$["לא נכון. האישור בניסויים הגיע רק מאוחר יותר, כפי שמציין המשפט הבא — 'doubted' מתאר את היחס הקודם לכך.", "נכון. 'doubted' פירושו לא האמינו — המדענים לא האמינו בתחילה שחרק מסוגל למסור מידע כה מפורט.", "לא נכון. המילה אינה מתארת דיון פומבי אלא חוסר אמון.", "לא נכון. המילה מבטאת ספק, לא התלהבות."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["many scientists doubted that an insect could communicate such detailed information"]$q$::jsonb, $q$shabbat batch A, passage=honeybee_dance, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, what does the angle of the straight run tell the other bees?$q$, $q$["How much food is available at the source.", "How far the food is from the hive.", "The direction of the food relative to the sun's position.", "The type of flowers that the dancer has found."]$q$::jsonb, 2, $q$["לא נכון. הפסקה השנייה אינה מזכירה שהריקוד מוסר מידע על כמות המזון.", "לא נכון. על פי הפסקה, המרחק נמסר באמצעות אורך הריצה הישרה, לא באמצעות הזווית.", "נכון. הפסקה כותבת שזווית הריצה הישרה מוסרת לדבורים את כיוון המזון ביחס לשמש.", "לא נכון. הפסקה אינה מזכירה מידע על סוג הפרחים."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["The angle of this run tells the other bees the direction of the food in relation to the sun"]$q$::jsonb, $q$shabbat batch A, passage=honeybee_dance, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["explain how the angle and length of the dance encode direction and distance.", "describe how von Frisch first noticed the dance on the honeycomb in the 1940s.", "argue that insects have larger brains than scientists previously assumed.", "show that the dance, once doubted, was confirmed and is now highly regarded."]$q$::jsonb, 3, $q$["לא נכון. זהו תוכן הפסקה השנייה — הסבר על הזווית והאורך — ולא הפסקה האחרונה.", "לא נכון. זהו תוכן הפסקה הראשונה — הגילוי הראשוני של פון פריש — ולא הפסקה האחרונה.", "לא נכון. הפסקה אינה טוענת שלחרקים מוח גדול; היא אומרת שמסרים מורכבים אינם דורשים מוח גדול.", "נכון. הפסקה האחרונה מתארת את הספק הראשוני, את האישור בניסויים ואת ההערכה הרבה שהריקוד זוכה לה כיום."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch A, passage=honeybee_dance, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the first paragraph that —$q$, $q$["von Frisch did not immediately understand the meaning of the dance.", "the bees that watched the dance rarely managed to find the flowers.", "von Frisch won the Nobel Prize in the same year he discovered the dance.", "honeybees perform the dance only when food is very close to the hive."]$q$::jsonb, 0, $q$["נכון. הפסקה מציינת שפון פריש הקדיש שנים לפענוח משמעות הריקוד, ומכאן שלא הבין אותה מיד.", "לא נכון. הפסקה כותבת שהדבורים הצופות עפו ומצאו את אותם פרחים.", "לא נכון. הגילוי היה בשנות הארבעים ופרס הנובל הוענק ב-1973 — שנים רבות לאחר מכן.", "לא נכון. הפסקה הראשונה אינה מגבילה את הריקוד למזון קרוב; הפסקה השנייה אף מזכירה מרחקים של כמה קילומטרים."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch A, passage=honeybee_dance, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$The Placebo Effect and Why It Works$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Placebo Effect and Why It Works$q$, $q$A placebo is a treatment that contains no active medicine, such as a sugar pill or an injection of plain salt water. Surprisingly, patients who receive a placebo often report that their symptoms improve. This phenomenon, known as the placebo effect, has been observed in conditions ranging from pain and nausea to depression. The effect is strong enough that new drugs must prove themselves against a placebo before they are approved. If a medicine performs no better than a sugar pill, it is generally judged to be ineffective.

For many years, doctors assumed that the placebo effect was simply a matter of imagination. However, modern research suggests that expectation produces real changes in the body. When a patient believes that relief is coming, the brain can release natural chemicals, including endorphins, that reduce pain. Brain-imaging studies have shown that placebo treatments activate some of the same regions that respond to genuine painkillers. The effect also depends on context: an injection tends to work better than a pill, and a confident doctor tends to produce stronger results than a hesitant one.

Nevertheless, the placebo effect has clear limits that patients and doctors should understand. It can ease symptoms such as pain and fatigue, but it cannot shrink a tumor or cure an infection. Researchers also debate how much of the effect reflects genuine healing rather than a patient's desire to please the doctor. Despite these questions, the placebo effect remains a powerful reminder that the mind and the body are closely connected. Understanding it may help doctors improve the experience of every treatment they offer.$q$, $q$psychology / medicine$q$, 5, 264, true, $q$reading_shabbat_2026-09-05_A$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["New drugs are approved only if they perform better than a sugar pill in clinical trials.", "The placebo effect produces real but limited changes through expectation.", "Doctors have long assumed that the placebo effect is merely a product of the patient's imagination.", "An injection produces a stronger placebo response than a pill taken by mouth."]$q$::jsonb, 1, $q$["לא נכון. זהו פרט מהפסקה הראשונה על אישור תרופות, ולא הרעיון המרכזי של הקטע כולו.", "נכון. הקטע מציג את אפקט הפלצבו כתופעה אמיתית הנובעת מציפייה, ובה בעת מדגיש את גבולותיה.", "לא נכון. זו ההנחה הישנה שהפסקה השנייה דוחה; היא אינה מסכמת את הקטע.", "לא נכון. זהו פרט אחד מהפסקה השנייה, ולא הרעיון המרכזי."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch A, passage=placebo_effect, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the second paragraph, the word "hesitant" most nearly means —$q$, $q$["experienced and highly respected", "friendly and warm toward patients", "uncertain and lacking confidence", "strict in following medical rules"]$q$::jsonb, 2, $q$["לא נכון. המשפט מנגיד 'hesitant' ל-'confident' (בטוח בעצמו), ולכן אין מדובר בניסיון או במעמד.", "לא נכון. המילה אינה עוסקת בחמימות כלפי מטופלים.", "נכון. 'hesitant' פירושו מהסס וחסר ביטחון — ההפך מרופא בטוח בעצמו, כפי שהמשפט מנגיד ביניהם.", "לא נכון. המילה אינה קשורה להקפדה על כללים."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["a confident doctor tends to produce stronger results than a hesitant one"]$q$::jsonb, $q$shabbat batch A, passage=placebo_effect, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the third paragraph, all of the following are true EXCEPT —$q$, $q$["The placebo effect can relieve symptoms such as pain and fatigue.", "Researchers disagree about how much of the effect represents genuine healing.", "The placebo effect cannot cure an infection or shrink a tumor.", "The placebo effect can be used to replace most conventional treatments."]$q$::jsonb, 3, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — הפסקה כותבת שהאפקט יכול להקל על כאב ועייפות.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — החוקרים אכן חלוקים בשאלה כמה מהאפקט הוא ריפוי אמיתי.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — הפסקה מציינת במפורש שהאפקט אינו יכול לרפא זיהום או להקטין גידול.", "נכון. זו הקביעה השגויה — הפסקה מדגישה את גבולות האפקט ואינה טוענת שהוא יכול להחליף טיפולים מקובלים."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["It can ease symptoms such as pain and fatigue, but it cannot shrink a tumor or cure an infection"]$q$::jsonb, $q$shabbat batch A, passage=placebo_effect, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["explain the biological mechanisms by which expectation can produce real changes in the body.", "describe how new medicines are tested against placebos before approval.", "warn that the placebo effect cannot cure serious diseases such as cancer.", "argue that doctors should give patients injections rather than pills."]$q$::jsonb, 0, $q$["נכון. הפסקה השנייה מסבירה כיצד ציפייה מובילה לשחרור חומרים טבעיים במוח ולהפעלת אזורים המגיבים למשככי כאבים אמיתיים.", "לא נכון. זהו תוכן הפסקה הראשונה — בדיקת תרופות מול פלצבו — ולא הפסקה השנייה.", "לא נכון. זהו תוכן הפסקה השלישית — גבולות האפקט — ולא הפסקה השנייה.", "לא נכון. הפסקה מציינת שזריקה נוטה לעבוד טוב יותר, אך אינה טוענת שרופאים צריכים להעדיף זריקות."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch A, passage=placebo_effect, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the statement that "new drugs must prove themselves against a placebo before they are approved," what can be inferred?$q$, $q$["Most new drugs fail to outperform a placebo and are therefore rejected.", "Some of the improvement seen in patients taking a real drug is due to expectation.", "Placebos are generally more effective than approved drugs at relieving pain.", "Drug companies are not permitted to use sugar pills in their trials."]$q$::jsonb, 1, $q$["לא נכון. הקטע אינו מוסר כמה תרופות נכשלות; הוא רק מציין את הדרישה להשוואה.", "נכון. אם תרופה חייבת להוכיח יתרון על פני פלצבו, משתמע שחלק מהשיפור אצל מטופלים נובע מהציפייה עצמה ולא מהתרופה.", "לא נכון. הקטע כותב שתרופה שאינה עולה על פלצבו נחשבת ללא יעילה — לא שפלצבו יעיל יותר מתרופות מאושרות.", "לא נכון. הקטע מתאר את ההפך — הניסויים מבוססים דווקא על השוואה לגלולת סוכר."]$q$::jsonb, $q$inference$q$, $q$anchor$q$, $q$["new drugs must prove themselves against a placebo before they are approved"]$q$::jsonb, $q$shabbat batch A, passage=placebo_effect, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$Why Leaves Change Color in Autumn$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Why Leaves Change Color in Autumn$q$, $q$Every autumn, the leaves of many trees in cooler climates turn from green to brilliant shades of yellow, orange, and red. This change is one of the most familiar sights of the season, yet the process behind it is not widely understood. The green color of a leaf comes from chlorophyll, a pigment that captures sunlight and uses it to produce food for the tree. During spring and summer, the tree makes fresh chlorophyll constantly to replace what is used up, so the leaves stay green. As the days grow shorter and cooler in autumn, however, the tree slowly stops producing it.

When the chlorophyll breaks down and disappears, other pigments that were present all along finally become visible. Yellow and orange colors come from carotenoids, the same substances that give carrots their color, and these pigments were hidden beneath the green throughout the summer. Red and purple shades, by contrast, come from a different group of pigments called anthocyanins. Unlike carotenoids, they are produced fresh in autumn, when sugars become trapped in the leaf. Bright, sunny days followed by cool nights tend to produce the most vivid red colors.

The color change is only one visible part of the tree's careful preparation for winter. A layer of special cells forms at the base of each leaf, gradually cutting it off from the branch. Eventually the leaf falls to the ground, and the tree enters a resting period that lasts until spring. By shedding its leaves, the tree avoids losing precious water through them during the cold, dry months. The bright colors that people admire each autumn are, in a sense, a sign of the tree protecting itself.$q$, $q$science / biology$q$, 3, 278, true, $q$reading_shabbat_2026-09-05_A$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["How Carrots and Autumn Leaves Share the Same Pigments", "Why Trees Lose Water During the Cold Winter Months", "How and Why the Leaves of Trees Change Color in Autumn", "The Role of Chlorophyll in Producing Food for Trees"]$q$::jsonb, 2, $q$["לא נכון. הדמיון לגזר הוא פרט אחד בפסקה השנייה, ולא נושא הקטע.", "לא נכון. איבוד המים מוזכר בפסקה השלישית כסיבה להשרת העלים, אך אינו הנושא המרכזי.", "נכון. הקטע כולו מסביר כיצד ומדוע העלים משנים את צבעם בסתיו — מהתפרקות הכלורופיל ועד להכנת העץ לחורף.", "לא נכון. תפקיד הכלורופיל מוסבר בפסקה הראשונה בלבד, כרקע לשינוי הצבע."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch A, passage=autumn_leaves, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the sentence "Unlike carotenoids, they are produced fresh in autumn, when sugars become trapped in the leaf," the word "they" refers to —$q$, $q$["the green pigments that break down at the end of summer.", "the carrots whose color comes from the same substances.", "the days that grow shorter and cooler in autumn.", "the anthocyanins that give leaves red and purple shades."]$q$::jsonb, 3, $q$["לא נכון. הכלורופיל מתפרק בסתיו ואינו מיוצר בו מחדש.", "לא נכון. הגזר מוזכר רק כדוגמה לצבע הקרוטנואידים, ואינו נושא המשפט.", "לא נכון. הימים אינם 'מיוצרים', והמשפט עוסק בפיגמנטים.", "נכון. המשפט הקודם מציג את האנתוציאנינים, ו-'they' מתייחס אליהם — הפיגמנטים שמייצרים גוונים אדומים וסגולים."]$q$::jsonb, $q$reference_word$q$, $q$anchor$q$, $q$["Unlike carotenoids, they are produced fresh in autumn, when sugars become trapped in the leaf"]$q$::jsonb, $q$shabbat batch A, passage=autumn_leaves, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, what weather conditions produce the most vivid red leaves?$q$, $q$["Sunny days followed by cool nights.", "Long periods of heavy rain in early autumn.", "Warm nights and cloudy, overcast days.", "An early frost that damages the leaves."]$q$::jsonb, 0, $q$["נכון. הפסקה מציינת שימים בהירים ושמשיים שאחריהם לילות קרירים מפיקים את הגוונים האדומים העזים ביותר.", "לא נכון. הפסקה אינה מזכירה גשם כלל.", "לא נכון. זהו ההפך מהתנאים המתוארים בפסקה — ימים שמשיים ולילות קרירים.", "לא נכון. הפסקה אינה מזכירה כפור או נזק לעלים."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Bright, sunny days followed by cool nights tend to produce the most vivid red colors"]$q$::jsonb, $q$shabbat batch A, passage=autumn_leaves, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["explain why chlorophyll gives leaves their green color during summer.", "describe how the tree separates from its leaves as part of preparing for winter.", "compare the pigments that produce yellow leaves with those that produce red ones.", "explain why some autumns produce more colorful leaves than others."]$q$::jsonb, 1, $q$["לא נכון. זהו תוכן הפסקה הראשונה — תפקיד הכלורופיל — ולא הפסקה האחרונה.", "נכון. הפסקה האחרונה מתארת את שכבת התאים שמנתקת את העלה מהענף, את נשירתו ואת הסיבה לכך — הכנת העץ לחורף.", "לא נכון. ההשוואה בין הקרוטנואידים לאנתוציאנינים מופיעה בפסקה השנייה.", "לא נכון. השפעת מזג האוויר על עוצמת הצבעים מוזכרת בפסקה השנייה, ולא בפסקה האחרונה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch A, passage=autumn_leaves, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, why do the leaves "stay green" during spring and summer?$q$, $q$["Because carotenoids are not present in the leaf until autumn.", "Because the leaves absorb the green part of sunlight.", "Because the tree keeps producing chlorophyll throughout those seasons.", "Because the layer of cells at the base of the leaf has not yet formed."]$q$::jsonb, 2, $q$["לא נכון. הפסקה השנייה כותבת שהקרוטנואידים נמצאים בעלה כל הזמן, רק מוסתרים מתחת לירוק.", "לא נכון. הפסקה כותבת שהכלורופיל קולט אור שמש ומייצר מזון, אך אינה מסבירה את הצבע הירוק בספיגת אור ירוק.", "נכון. הפסקה הראשונה כותבת שבאביב ובקיץ העץ מייצר כלורופיל ללא הרף, ולכן העלים נשארים ירוקים.", "לא נכון. שכבת התאים מוזכרת בפסקה השלישית בהקשר לנשירה, ולא כהסבר לצבע הירוק."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["the leaves stay green"]$q$::jsonb, $q$shabbat batch A, passage=autumn_leaves, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$Alfred Wegener and the Idea of Drifting Continents$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Alfred Wegener and the Idea of Drifting Continents$q$, $q$In 1912, the German meteorologist Alfred Wegener proposed an idea that most geologists of his day found absurd. He argued that the continents had once been joined in a single landmass, which he called Pangaea, and had slowly drifted apart. Wegener was not the first to notice that the coastlines of South America and Africa seem to fit together like puzzle pieces. He was, however, the first to gather evidence from several fields in support of a single explanation.

Wegener's evidence was varied and, in hindsight, remarkably impressive for its time. Identical fossils of land plants and animals appeared on continents now separated by wide oceans. Rock formations on the coast of Brazil matched those in West Africa in age and structure. Traces of ancient glaciers were found in places that are now tropical, suggesting that these lands had once lain near the poles. To Wegener, these facts made sense only if the continents had moved.

Despite this evidence, his theory was rejected by most of the scientific community for decades. The main problem was that Wegener could not explain what force could push continents across the globe, and physicists calculated that the mechanisms he suggested were far too weak. Some critics also dismissed him as an outsider, since his training was in meteorology rather than geology. Wegener died in 1930 during an expedition to Greenland, with his idea still widely mocked.

The turning point came in the 1950s and 1960s, when scientists mapped the ocean floor in detail. They discovered long underwater mountain ranges where new crust was constantly forming and spreading outward, a process known as seafloor spreading that provided the missing mechanism. Wegener's basic idea was absorbed into the theory of plate tectonics, which today forms the foundation of modern geology.$q$, $q$science / earth science$q$, 5, 292, true, $q$reading_shabbat_2026-09-05_A$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Alfred Wegener died in Greenland in 1930 before his theory could be accepted.", "The discovery of seafloor spreading in the 1950s and 1960s transformed geology.", "Matching fossils on different continents prove that the continents were once joined.", "Wegener's theory of drifting continents was mocked for decades until new evidence finally confirmed it."]$q$::jsonb, 3, $q$["לא נכון. מותו של וגנר הוא פרט מהפסקה השלישית, ולא הרעיון המרכזי של הקטע.", "לא נכון. גילוי התפשטות קרקעית הים מופיע בפסקה האחרונה כשלב אחד בסיפור, ולא כנושא הקטע כולו.", "לא נכון. המאובנים הם סוג אחד של ראיות מהפסקה השנייה, ולא הרעיון המרכזי.", "נכון. הקטע עוקב אחר התיאוריה של וגנר — הצגתה, הראיות, הדחייה הממושכת והאישור המאוחר — וזה הרעיון המרכזי."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch A, passage=wegener_continents, q1$q$, 1, true);
