    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, which of the following is NOT mentioned as evidence for Wegener's theory?$q$, $q$["Matching rock formations on the coasts of Brazil and West Africa.", "Measurements showing that continents move a few centimeters each year.", "Identical fossils found on continents now separated by oceans.", "Signs of ancient glaciers in regions that are now tropical."]$q$::jsonb, 1, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — תצורות הסלע בברזיל ובמערב אפריקה אכן תואמות.", "נכון. זו הקביעה שאינה מופיעה — הפסקה אינה מזכירה מדידות של תנועת היבשות; להפך, הפסקה השלישית מציינת שוגנר לא יכול היה להסביר כיצד הן זזות.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — מאובנים זהים נמצאו ביבשות המופרדות באוקיינוסים.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — עקבות קרחונים עתיקים נמצאו באזורים טרופיים."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch A, passage=wegener_continents, q3$q$, 3, true);
