  if not exists (select 1 from reading_passages where title = $q$Sleep and the Consolidation of Memory$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Sleep and the Consolidation of Memory$q$, $q$For much of the twentieth century, sleep was regarded as a passive state in which the brain simply rested. Research over the past few decades has overturned this view. Scientists now believe that sleep plays an active role in consolidation, the process by which fragile new memories become stable and lasting. Information acquired during the day appears to be reactivated and reorganized while we sleep. Without this nightly processing, much of what we learn would fade within hours.

Sleep is not uniform; it cycles through several distinct stages, each of which seems to serve memory differently. Deep, slow-wave sleep, which dominates the early part of the night, is associated with strengthening factual memories such as names, dates, and vocabulary. During this stage, the hippocampus, a structure involved in forming new memories, replays patterns of activity that occurred during learning. Later in the night, rapid eye movement sleep, the stage in which dreaming is most vivid, becomes more frequent. This stage has been linked to procedural skills and to the emotional processing of experiences.

Evidence for these claims comes from studies in which participants learn a task and are then tested after either sleep or an equal period of wakefulness. Those who sleep typically retain more and sometimes discover solutions they had missed before. Nevertheless, the scientific picture is still far from complete. Researchers still debate whether sleep merely protects memories from interference or actively transforms them. What is clear is that a night of poor sleep does more than cause tiredness; it can quietly undo the work of learning.$q$, $q$psychology / neuroscience$q$, 6, 259, true, $q$reading_shabbat_2026-09-05_A$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Sleep plays an active role in stabilizing and reorganizing new memories, although many details remain unclear.", "Slow-wave sleep strengthens factual memories such as names, dates, and vocabulary.", "Scientists in the twentieth century believed that the brain simply rested during sleep.", "People who sleep after learning a task sometimes discover solutions they had missed."]$q$::jsonb, 0, $q$["נכון. הקטע מציג את השינה כתהליך פעיל של ייצוב וארגון זיכרונות, ומסיים בהדגשת השאלות שעדיין פתוחות.", "לא נכון. זהו פרט אחד מהפסקה השנייה על שלב אחד של השינה, ולא הרעיון המרכזי.", "לא נכון. זו ההשקפה הישנה שהפסקה הראשונה מציגה רק כדי לדחות אותה.", "לא נכון. זהו ממצא אחד מהפסקה השלישית, ולא הרעיון המרכזי של הקטע."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch A, passage=sleep_memory, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the first paragraph, the word "overturned" most nearly means —$q$, $q$["strongly supported", "reversed", "slightly modified", "first proposed"]$q$::jsonb, 1, $q$["לא נכון. המשפט הבא מציג השקפה הפוכה — שינה פעילה ולא פסיבית — ולכן אין מדובר בתמיכה.", "נכון. 'overturned' פירושו הפך או ביטל — המחקר הפך את ההשקפה הישנה שהשינה היא מצב פסיבי.", "לא נכון. השינוי המתואר הוא מהותי, לא קל.", "לא נכון. ההשקפה הפסיבית הייתה קיימת במשך רוב המאה העשרים; המחקר לא הציע אותה אלא דחה אותה."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["Research over the past few decades has overturned this view"]$q$::jsonb, $q$shabbat batch A, passage=sleep_memory, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, what happens in the hippocampus during slow-wave sleep?$q$, $q$["It produces the rapid eye movements that characterize later stages of sleep.", "It gradually shuts down so that the rest of the brain can rest.", "It replays activity patterns that occurred while new information was being learned.", "It processes the emotional content of the day's experiences."]$q$::jsonb, 2, $q$["לא נכון. תנועות העיניים המהירות שייכות לשלב מאוחר יותר, והפסקה אינה מייחסת אותן להיפוקמפוס.", "לא נכון. הפסקה מתארת פעילות של ההיפוקמפוס, לא כיבוי שלו.", "נכון. הפסקה כותבת שההיפוקמפוס משחזר במהלך שלב זה דפוסי פעילות שהתרחשו בזמן הלמידה.", "לא נכון. העיבוד הרגשי מקושר בפסקה לשלב שנת החלום (REM), לא לשנת הגלים האיטיים."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["the hippocampus, a structure involved in forming new memories, replays patterns of activity that occurred during learning"]$q$::jsonb, $q$shabbat batch A, passage=sleep_memory, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["explain the differences between slow-wave sleep and rapid eye movement sleep.", "describe how sleep was viewed by scientists in the twentieth century.", "argue that the hippocampus is the most important structure for memory.", "present the experimental evidence for sleep's role in memory while noting open questions."]$q$::jsonb, 3, $q$["לא נכון. ההבדלים בין שלבי השינה מתוארים בפסקה השנייה.", "לא נכון. ההשקפה הישנה על השינה מוצגת בפסקה הראשונה.", "לא נכון. ההיפוקמפוס מוזכר בפסקה השנייה, והקטע אינו טוען שהוא המבנה החשוב ביותר.", "נכון. הפסקה האחרונה מציגה את הניסויים התומכים בטענות ומציינת שהתמונה עדיין אינה שלמה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch A, passage=sleep_memory, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the statement that poor sleep "can quietly undo the work of learning," what can be inferred?$q$, $q$["A student who studies but sleeps badly may remember less than expected.", "Learning that takes place at night is more effective than learning during the day.", "Tiredness is the most serious consequence of a night without sleep.", "Memories lost through poor sleep can be easily recovered the following night."]$q$::jsonb, 0, $q$["נכון. אם שינה גרועה מבטלת את עבודת הלמידה, משתמע שתלמיד שלמד אך ישן רע עלול לזכור פחות ממה שציפה.", "לא נכון. הקטע עוסק בשינה לאחר הלמידה, ואינו משווה בין למידה בלילה לבין למידה ביום.", "לא נכון. המשפט אומר במפורש שהנזק הוא 'יותר מאשר עייפות'.", "לא נכון. הקטע אינו מזכיר שחזור של זיכרונות שאבדו."]$q$::jsonb, $q$inference$q$, $q$anchor$q$, $q$["it can quietly undo the work of learning"]$q$::jsonb, $q$shabbat batch A, passage=sleep_memory, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$The Coelacanth: A Fish Thought Extinct for Millions of Years$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Coelacanth: A Fish Thought Extinct for Millions of Years$q$, $q$In December 1938, a museum curator in South Africa named Marjorie Courtenay-Latimer visited the docks to inspect a fisherman's catch. Among the ordinary fish, she noticed a strange blue creature with thick, fleshy fins unlike any she had seen. She could not identify it, so she sent a sketch to James Smith, a chemistry lecturer with a passion for fish. Smith recognized it at once as a coelacanth, a fish known only from fossils.

The discovery caused an immediate sensation in the scientific world. Coelacanths appear in the fossil record from roughly 400 million years ago, and scientists had believed that they died out around the time of the dinosaurs. Finding a living specimen was compared to stumbling upon a living dinosaur. Because the first fish had been preserved poorly, Smith spent fourteen years searching for a second one. In 1952 a fisherman in the Comoro Islands finally caught another, and Smith flew there to collect it personally.

Coelacanths are of special interest to biologists because of their unusual anatomy. Their fins are attached to the body by fleshy stalks that move in an alternating pattern, somewhat like the limbs of a walking animal. For this reason, they were once thought to be close relatives of the first fish that crawled onto land. Modern genetic studies suggest that lungfish are actually closer to land animals, yet the coelacanth remains a valuable window into early vertebrate evolution.

Today two species are known, one in the western Indian Ocean and another discovered near Indonesia in 1997. Both live in deep water along steep rocky slopes and are rarely seen alive. Their numbers are small, and they are considered to be at serious risk of extinction. The fish that surprised the world in 1938 is now carefully protected by international agreements.$q$, $q$science / biology$q$, 4, 293, true, $q$reading_shabbat_2026-09-05_A$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["Marjorie Courtenay-Latimer: A Curator Who Changed Science", "The Coelacanth: A Living Fossil Rediscovered", "How Fleshy Fins Helped the First Fish Crawl onto Land", "The Fourteen-Year Search for a Second Specimen"]$q$::jsonb, 1, $q$["לא נכון. האוצרת מופיעה רק בפסקה הראשונה; הקטע עוסק בדג עצמו.", "נכון. הקטע כולו עוסק בקואלקנת' — דג שנחשב לנכחד ונתגלה חי — מגילויו ועד למעמדו כיום.", "לא נכון. הפסקה השלישית אף מציינת שהקואלקנת' כנראה אינו הקרוב ביותר לחיות היבשה הראשונות.", "לא נכון. החיפוש בן ארבע עשרה השנים הוא פרט מהפסקה השנייה, ולא נושא הקטע."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch A, passage=coelacanth, q1$q$, 1, true);
