    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, why did Smith search for a second coelacanth for fourteen years?$q$, $q$["Because the first fish had been caught in the Comoro Islands, far from South Africa.", "Because scientists refused to believe him until he could show them a second one.", "Because he wanted to compare the anatomy of two different species.", "Because the first specimen had been poorly preserved."]$q$::jsonb, 3, $q$["לא נכון. הדג הראשון נתפס בדרום אפריקה; איי קומורו הם המקום שבו נתפס הדג השני.", "לא נכון. הפסקה מתארת סנסציה מדעית, לא סירוב להאמין לסמית.", "לא נכון. הפסקה אינה מזכירה השוואה בין מינים; המין השני התגלה רק ב-1997.", "נכון. הפסקה כותבת שהדג הראשון נשמר באופן גרוע, ולכן סמית חיפש דגימה נוספת."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Because the first fish had been preserved poorly, Smith spent fourteen years searching for a second one"]$q$::jsonb, $q$shabbat batch A, passage=coelacanth, q3$q$, 3, true);
