do $$ declare v_pid uuid; begin

  if not exists (select 1 from reading_passages where title = $q$The Bystander Effect$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Bystander Effect$q$, $q$In March 1964, a young woman named Kitty Genovese was attacked and killed outside her apartment building in Queens, New York. Two weeks later, the New York Times reported that thirty-eight neighbors had watched the attack without calling the police. The story provoked national outrage and was widely taken as proof that city life had made people indifferent. Social psychologists John Darley and Bibb Latané, however, suspected that something more complicated than indifference was involved.

In a series of experiments published in 1968, they tested how the presence of other people affects the willingness to help. In one study, participants sat alone in a room that slowly filled with smoke. Those who were alone usually reported the smoke quickly, whereas those seated with calm strangers often stayed in their seats. In another experiment, participants heard a fellow student apparently suffer a seizure over an intercom. The more people a participant believed were listening, the less likely he or she was to seek help. Darley and Latané explained this pattern through diffusion of responsibility: when many people could act, each individual feels less obliged to do so.

Ironically, the case that inspired this research turned out to be far less clear than the newspaper had claimed. A 2007 review of the court records and interviews found that few neighbors had actually seen the attack. Several people did call the police, and one neighbor went outside to help the dying woman. Yet the bystander effect itself has been confirmed in many later studies and remains one of the best-known findings in social psychology. The lesson, it seems, is that a flawed story can still lead researchers toward a genuine truth.$q$, $q$psychology$q$, 5, 275, true, $q$reading_shabbat_2026-09-05_B$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Research inspired by a famous crime showed that the presence of others reduces the willingness to help, even though the crime story itself was later found to be exaggerated.", "Thirty-eight neighbors ignored the murder of Kitty Genovese in 1964.", "Participants in a smoke-filled room reacted more slowly when strangers were present.", "A 2007 review proved that newspapers should never be trusted as sources."]$q$::jsonb, 0, $q$["נכון. הקטע כולו מתאר כיצד סיפור הרצח הוביל למחקר שהוכיח את אפקט הצופה מהצד, ובסופו מראה שהסיפור עצמו הוגזם אך הממצא נשאר תקף.", "לא נכון. זו הטענה המקורית של העיתון מהפסקה הראשונה, והפסקה השלישית מראה שהיא הוגזמה; היא בוודאי אינה הרעיון המרכזי.", "לא נכון. זהו פרט אחד מהפסקה השנייה, ולא הרעיון המרכזי של הקטע כולו.", "לא נכון. הקטע אינו טוען שאין לסמוך על עיתונים; הוא רק מציין שסיפור אחד הוגזם."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch B, passage=bystander, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
