  if not exists (select 1 from reading_passages where title = $q$The Marshmallow Test and Its Reexamination$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Marshmallow Test and Its Reexamination$q$, $q$In the late 1960s, psychologist Walter Mischel began a series of studies at a nursery school on the Stanford University campus. A child was seated at a table with a single marshmallow or similar treat. The researcher explained that the child could eat the treat immediately or wait alone for a while and receive two. Some children ate the treat within seconds, while others covered their eyes, sang songs, or turned away to resist the temptation.

The experiment might have remained a minor study of self-control if not for what came later. In the late 1980s, Mischel and his colleagues followed up with some of the original children, who were now teenagers. The ones who had waited longer as preschoolers tended to have higher test scores and were described by their parents as more competent. These findings were widely reported and soon became a popular symbol of the idea that willpower in childhood predicts success in life.

However, the original sample was small and consisted mostly of children of Stanford faculty and staff. In 2018, a team led by Tyler Watts repeated the study with more than nine hundred children from far more varied backgrounds. The link between waiting time and later achievement was much weaker, and it shrank further once family income and home environment were taken into account. A child's ability to wait, the researchers suggested, may partly reflect whether the child has learned that promised rewards actually arrive.

The marshmallow test is therefore a useful reminder of how science corrects itself. A striking result can capture the public imagination long before it has been thoroughly tested. Self-control still matters, but it appears to be shaped by circumstances rather than fixed at birth.$q$, $q$psychology$q$, 5, 284, true, $q$reading_shabbat_2026-09-05_B$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["How Children Resist a Tempting Treat", "Why Family Income Determines Success in School", "A Famous Study of Self-Control and What Later Research Revealed", "Walter Mischel's Career at Stanford University"]$q$::jsonb, 2, $q$["לא נכון. דרכי ההתמודדות של הילדים הן פרט מהפסקה הראשונה בלבד.", "לא נכון. הקטע מזכיר הכנסה משפחתית כגורם אחד, אך אינו טוען שהיא קובעת הצלחה.", "נכון. הכותרת מקיפה את הניסוי המקורי, את התהילה שזכה לה ואת המחקר החוזר שסייג את מסקנותיו — כל חלקי הקטע.", "לא נכון. הקטע עוסק בניסוי אחד ובמה שקרה לו, לא בקריירה של מישל."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch B, passage=marshmallow, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, what were the children told?$q$, $q$["That they would receive a second treat only if they sang a song.", "That they could choose between a marshmallow and a different treat.", "That the researcher would return only after they had eaten the treat.", "That waiting would earn them two treats instead of one."]$q$::jsonb, 3, $q$["לא נכון. שירה מוזכרת כדרך שבה ילדים התמודדו עם הפיתוי, לא כתנאי לקבלת הפרס.", "לא נכון. הפסקה מתארת ממתק אחד מסוג מרשמלו או דומה לו, לא בחירה בין שני סוגים.", "לא נכון. הפסקה אינה אומרת שהחוקר יחזור רק אחרי האכילה.", "נכון. הפסקה כותבת שהילד יכול לאכול מיד או להמתין ולקבל שניים."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["the child could eat the treat immediately or wait alone for a while and receive two"]$q$::jsonb, $q$shabbat batch B, passage=marshmallow, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the third paragraph, how did the 2018 study differ from the original?$q$, $q$["It involved many more children from a wider range of backgrounds.", "It used a different treat and a longer waiting period.", "It followed the children for a much longer period of time than Mischel had.", "It was conducted at a different university's nursery school."]$q$::jsonb, 0, $q$["נכון. הפסקה מציינת יותר מתשע מאות ילדים מרקעים מגוונים הרבה יותר, לעומת המדגם הקטן והאחיד של המקור.", "לא נכון. הפסקה אינה מזכירה ממתק אחר או זמן המתנה ארוך יותר.", "לא נכון. הפסקה אינה משווה את משך המעקב בין שני המחקרים.", "לא נכון. הפסקה אינה מציינת היכן נערך המחקר החוזר."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["more than nine hundred children from far more varied backgrounds"]$q$::jsonb, $q$shabbat batch B, passage=marshmallow, q3$q$, 3, true);
