    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the fourth paragraph, the word "striking" most nearly means —$q$, $q$["Physically violent", "Highly doubtful", "Remarkable", "Temporary in nature"]$q$::jsonb, 2, $q$["לא נכון. אין כאן משמעות של אלימות פיזית; מדובר בתוצאה מדעית.", "לא נכון. תוצאה מפוקפקת לא הייתה כובשת את הדמיון הציבורי.", "נכון. 'striking' פירושו מרשים, בולט — תוצאה מרשימה כובשת את דמיון הציבור.", "לא נכון. המילה אינה עוסקת במשך הזמן שהתוצאה מחזיקה מעמד."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["A striking result can capture the public imagination"]$q$::jsonb, $q$shabbat batch B, passage=marshmallow, q5$q$, 5, true);
