  if not exists (select 1 from reading_passages where title = $q$Ebbinghaus and the Forgetting Curve$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Ebbinghaus and the Forgetting Curve$q$, $q$Hermann Ebbinghaus was a German psychologist who wanted to study memory with the same precision that physicists applied to matter. In the 1880s, no laboratory methods for measuring memory existed, so he invented his own. He created more than two thousand nonsense syllables, such as zok or baf, which had no meaning that could aid recall. Using himself as the only subject, he memorized lists of these syllables and then tested how much he remembered after various delays.

The results, published in 1885, revealed a pattern that is now known as the forgetting curve. Memory for new material declined sharply within the first hours after learning and then leveled off. A large share of what he had learned disappeared within a day, but the material that survived faded much more slowly. Ebbinghaus also measured memory indirectly through what he called savings: the time saved when relearning a list compared with learning it the first time. Even when he could not recall a single syllable, relearning was faster, which showed that some trace of the list remained.

His work also pointed to a practical remedy. Lists that were reviewed at spaced intervals were retained far better than lists studied in a single long session. This spacing effect has since been confirmed in hundreds of experiments and forms the basis of many modern learning apps. Although a single subject would not satisfy today's standards, a careful replication in 2015 produced a curve very similar to the original. Ebbinghaus thus demonstrated that memory, once thought too private to measure, could be studied experimentally.$q$, $q$psychology$q$, 4, 258, true, $q$reading_shabbat_2026-09-05_B$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Nonsense syllables are the best way to test memory.", "A 2015 replication confirmed the forgetting curve.", "Ebbinghaus's research was flawed because he used only himself as a subject.", "By inventing his own methods, Ebbinghaus showed that memory could be measured and discovered lasting patterns of forgetting."]$q$::jsonb, 3, $q$["לא נכון. ההברות חסרות המשמעות הן כלי שתואר בפסקה הראשונה, לא הרעיון המרכזי.", "לא נכון. השחזור מ-2015 הוא פרט אחד מהפסקה השלישית.", "לא נכון. הקטע מציין את מגבלת הנבדק היחיד, אך מדגיש שהממצאים אושרו, ולכן אינו מציג את המחקר כפגום.", "נכון. הקטע מתאר את השיטות שהמציא אבינגהאוס ואת עקומת השכחה ואפקט הריווח שגילה — זהו הרעיון המרכזי."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch B, passage=ebbinghaus, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, why did Ebbinghaus use "nonsense syllables"?$q$, $q$["So that meaning could not help him remember.", "Because real words were too difficult to memorize in large numbers.", "Because no physicist had ever used them before in an experiment.", "So that other subjects could easily learn them in later studies."]$q$::jsonb, 0, $q$["נכון. הפסקה הראשונה מסבירה שלהברות לא הייתה משמעות שיכולה לסייע בזכירה.", "לא נכון. הפסקה אינה טוענת שמילים אמיתיות קשות מדי לזכירה.", "לא נכון. הפיזיקאים מוזכרים רק כדוגמה לדיוק מדעי, לא בקשר להברות.", "לא נכון. אבינגהאוס היה הנבדק היחיד; הפסקה אינה מזכירה נבדקים אחרים."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["nonsense syllables"]$q$::jsonb, $q$shabbat batch B, passage=ebbinghaus, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the third paragraph is to —$q$, $q$["describe the nonsense syllables that Ebbinghaus created.", "explain the concept of savings in relearning a list.", "present a practical lesson from the research and its later confirmation.", "argue that the use of a single subject makes the research worthless by modern standards."]$q$::jsonb, 2, $q$["לא נכון. ההברות חסרות המשמעות מתוארות בפסקה הראשונה.", "לא נכון. מושג החיסכון בלמידה מחדש מוסבר בפסקה השנייה.", "נכון. הפסקה מציגה את אפקט הריווח כתועלת מעשית ומציינת שהממצאים אושרו בשחזור מ-2015.", "לא נכון. הפסקה מזכירה את מגבלת הנבדק היחיד אך מדגישה שהתוצאות שוחזרו, ולכן אינה פוסלת את המחקר."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch B, passage=ebbinghaus, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the second paragraph that —$q$, $q$["Ebbinghaus forgot everything he learned within a single day.", "material that survives the first day after learning is likely to remain in memory for a considerably longer time.", "relearning a list always took as long as learning it originally.", "the forgetting curve applies only to nonsense syllables."]$q$::jsonb, 1, $q$["לא נכון. הפסקה כותבת שחלק גדול נשכח בתוך יום, אך לא הכול — חלק מהחומר שרד.", "נכון. הפסקה מציינת שהחומר ששרד את השעות הראשונות דעך לאט הרבה יותר, ומכאן שהוא נשמר לזמן ארוך יותר.", "לא נכון. הפסקה קובעת במפורש שהלמידה מחדש הייתה מהירה יותר.", "לא נכון. הפסקה אינה מגבילה את העקומה להברות חסרות משמעות בלבד."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, $q$["the material that survived faded much more slowly"]$q$::jsonb, $q$shabbat batch B, passage=ebbinghaus, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the sentence "Even when he could not recall a single syllable, relearning was faster, which showed that some trace of the list remained", the word "which" refers to —$q$, $q$["the fact that relearning took less time", "the syllable", "the forgetting curve described earlier in the paragraph", "the list of syllables"]$q$::jsonb, 0, $q$["נכון. המילה 'which' מתייחסת לעובדה שהלמידה מחדש הייתה מהירה יותר — עובדה זו היא שהראתה שנשאר זכר לרשימה.", "לא נכון. ההברה שלא נזכרה אינה מה שהראה שנשאר זכר.", "לא נכון. עקומת השכחה אינה מוזכרת במשפט זה.", "לא נכון. הרשימה היא מה שנשאר ממנו זכר, לא מה שהראה זאת."]$q$::jsonb, $q$reference_word$q$, $q$anchor$q$, $q$["relearning was faster, which showed that some trace of the list remained"]$q$::jsonb, $q$shabbat batch B, passage=ebbinghaus, q5$q$, 5, true);
