  if not exists (select 1 from reading_passages where title = $q$The Hawthorne Effect$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Hawthorne Effect$q$, $q$Between 1924 and 1932, a series of studies was carried out at the Hawthorne Works, a large factory operated by the Western Electric Company near Chicago. The original goal was modest: managers wanted to know whether brighter lighting would make workers assemble telephone equipment more quickly. When the lighting was increased, output rose, as expected. Yet output also rose when the lighting was dimmed, and it even rose in a control group whose lighting had not changed at all.

Puzzled by these results, the company invited researchers from Harvard, including the psychologist Elton Mayo, to investigate further. In one famous phase, a small group of women assembling relays was moved to a separate room and observed closely for several years. Almost every change the researchers introduced, from rest breaks to shorter hours, seemed to raise productivity. The researchers concluded that the workers were responding not to the changes themselves but to the attention they were receiving. Being singled out and observed made them feel valued, and that feeling appeared to improve their performance.

The term Hawthorne effect was coined in the 1950s to describe this tendency of people to alter their behavior when they know they are being studied. The idea had a lasting influence on management, encouraging companies to pay more attention to workers' morale and social needs. However, later scholars who reexamined the original records argued that the effect was smaller and less consistent than the popular story suggests. Some of the productivity gains, for instance, may have reflected the replacement of slower workers or simple practice with the task. Nevertheless, the studies remain a classic warning that observation can change the very thing a researcher hopes to measure.$q$, $q$psychology$q$, 5, 279, true, $q$reading_shabbat_2026-09-05_B$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the passage, what can be inferred about the connection between the lighting study and the later research?$q$, $q$["The later research was planned before the lighting study began.", "The puzzling outcome of the lighting study prompted the company to seek outside help in understanding it.", "The later research proved that lighting had no effect at all.", "The Harvard researchers rejected the results of the lighting study."]$q$::jsonb, 1, $q$["לא נכון. הפסקה השנייה פותחת בכך שהחברה הזמינה חוקרים בעקבות התוצאות, כלומר אחרי מחקר התאורה.", "נכון. הפסקה הראשונה מסתיימת בתוצאות סותרות, והשנייה פותחת במילה 'נבוכים' ובהזמנת חוקרים מהרווארד — מכאן שהבלבול הוביל לפנייה לעזרה חיצונית.", "לא נכון. הקטע אינו טוען שלתאורה אין שום השפעה, אלא שהתפוקה עלתה גם ללא קשר לה.", "לא נכון. הקטע אינו מזכיר דחייה של תוצאות מחקר התאורה."]$q$::jsonb, $q$inference$q$, $q$text$q$, null, $q$shabbat batch B, passage=hawthorne, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Which of the following is NOT mentioned in the third paragraph?$q$, $q$["The term Hawthorne effect dates from the 1950s.", "The studies influenced how companies treated their employees' morale.", "Some productivity gains may have resulted from practice with the task over time.", "The observed workers were paid higher wages than other employees."]$q$::jsonb, 3, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — המונח נטבע בשנות החמישים.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — הרעיון השפיע על יחס החברות למורל העובדים.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — תרגול במשימה מוזכר כהסבר אפשרי.", "נכון. הפסקה אינה מזכירה כלל שכר גבוה יותר לעובדות שנצפו; זהו הפרט שאינו מופיע."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["the replacement of slower workers or simple practice with the task"]$q$::jsonb, $q$shabbat batch B, passage=hawthorne, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, why did the researchers believe productivity had risen?$q$, $q$["Because rest breaks and shorter hours reduced the workers' fatigue.", "Because the women were competing with one another for promotion.", "Because the workers felt valued by the attention.", "Because the separate room had much better lighting than the factory floor."]$q$::jsonb, 2, $q$["לא נכון. הפסקה קובעת במפורש שהעובדות הגיבו לא לשינויים עצמם אלא לתשומת הלב.", "לא נכון. הפסקה אינה מזכירה תחרות או קידום.", "נכון. הפסקה כותבת שההתבוננות והבחירה בהן גרמו לעובדות להרגיש מוערכות, ותחושה זו שיפרה את ביצועיהן.", "לא נכון. הפסקה אינה מזכירה את התאורה בחדר הנפרד."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Being singled out and observed made them feel valued"]$q$::jsonb, $q$shabbat batch B, passage=hawthorne, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the first paragraph is to —$q$, $q$["describe an experiment whose results contradicted what the managers had expected to find.", "explain why Elton Mayo was invited to the factory.", "describe the daily work of telephone assemblers.", "define the term Hawthorne effect."]$q$::jsonb, 0, $q$["נכון. הפסקה מציגה את מחקר התאורה ואת התוצאה המפתיעה — התפוקה עלתה גם כשהתאורה הוחלשה וגם בקבוצת הביקורת.", "לא נכון. ההזמנה של מאיו מתוארת בפסקה השנייה.", "לא נכון. הפסקה אינה מתארת את עבודת המרכיבים ביומיום.", "לא נכון. המונח מוגדר בפסקה השלישית."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch B, passage=hawthorne, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the second paragraph, the word "Puzzled" is closest in meaning to —$q$, $q$["Pleased", "Confused and surprised", "Extremely angered by the workers' behavior", "Bored"]$q$::jsonb, 1, $q$["לא נכון. תוצאות סותרות אינן מעוררות שביעות רצון, והפסקה מתארת חיפוש אחר הסבר.", "נכון. 'Puzzled' פירושו נבוך, מבולבל — החברה לא הבינה את התוצאות ולכן הזמינה חוקרים.", "לא נכון. אין בהקשר שום כעס על העובדים.", "לא נכון. שעמום לא היה מוביל להזמנת חוקרים מהרווארד."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["Puzzled by these results"]$q$::jsonb, $q$shabbat batch B, passage=hawthorne, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$Cognitive Dissonance$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Cognitive Dissonance$q$, $q$In 1957, the social psychologist Leon Festinger proposed that people experience discomfort when they hold two beliefs that conflict with each other. He called this state cognitive dissonance and argued that people are strongly motivated to reduce it. Since actions that have already been taken cannot be undone, the easiest route is often to change the belief instead. This simple idea proved capable of explaining a surprising range of human behavior.

Festinger first tested the theory by observing a small group that had predicted the end of the world on a specific date. When the date passed without incident, members did not abandon their leader, as outsiders might have expected. Instead, many became more committed, announcing that their faith had persuaded a higher power to spare the planet. Having sacrificed jobs and possessions for their belief, they found it less painful to reinterpret the failure than to admit a mistake.

A laboratory experiment published in 1959 provided more controlled evidence. Participants spent an hour on a deliberately tedious task and were then asked to tell the next participant that it had been enjoyable. Some were paid one dollar for telling this lie, while others received twenty dollars. Afterwards, those paid only one dollar rated the task as significantly more pleasant than those paid twenty. Festinger argued that a large payment offered a sufficient justification for lying, whereas a small payment left participants with a conflict to resolve.

The theory has been challenged and refined over the decades, and some researchers prefer to describe the effect in terms of self-image rather than logical inconsistency. Nevertheless, dissonance remains a central concept in psychology, and its traces can be seen wherever people defend choices they cannot easily reverse.$q$, $q$psychology$q$, 6, 283, true, $q$reading_shabbat_2026-09-05_B$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Festinger's theory that people adjust their beliefs to reduce inner conflict is supported by observations and experiments and remains influential.", "Members of a doomsday group became more committed after their prophecy failed.", "Participants who were paid less rated a boring task as more enjoyable.", "Modern psychologists have largely abandoned Festinger's theory."]$q$::jsonb, 0, $q$["נכון. הקטע מציג את התיאוריה, מביא שתי ראיות תומכות ומסכם שהיא נותרה מושג מרכזי — זהו הרעיון המרכזי.", "לא נכון. זהו פרט מהפסקה השנייה בלבד.", "לא נכון. זהו פרט מהפסקה השלישית בלבד.", "לא נכון. הפסקה האחרונה קובעת את ההפך — התיאוריה נותרה מושג מרכזי."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch B, passage=dissonance, q1$q$, 1, true);
