      values (v_pid, $q$It can be inferred from the phrase "as outsiders might have expected" that —$q$, $q$["outsiders had warned the group that the prophecy would fail.", "a failed prediction would normally be regarded as a reason to abandon the belief behind it.", "the group's leader had expected the prophecy to fail.", "outsiders were more committed to the prophecy than the members."]$q$::jsonb, 1, $q$["לא נכון. הפסקה אינה מזכירה אזהרות מצד גורמים חיצוניים.", "נכון. הביטוי מלמד שמי שאינו חבר בקבוצה היה מצפה שכישלון הנבואה יגרום לחברים לנטוש את מנהיגם — כלומר שזו התגובה הרגילה.", "לא נכון. אין בקטע רמז לכך שהמנהיג ציפה לכישלון.", "לא נכון. הפסקה מתארת דווקא את מחויבותם הגוברת של החברים, לא של הזרים."]$q$::jsonb, $q$inference$q$, $q$anchor$q$, $q$["as outsiders might have expected"]$q$::jsonb, $q$shabbat batch B, passage=dissonance, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the third paragraph, the word "tedious" is closest in meaning to —$q$, $q$["Dangerous", "Extremely complicated and demanding", "Costly", "Boring and repetitive"]$q$::jsonb, 3, $q$["לא נכון. אין בהקשר שום סכנה; המשתתפים התבקשו לומר שהמשימה הייתה מהנה.", "לא נכון. משימה מסובכת אינה בהכרח ההפך ממהנה; ההקשר עוסק בשעמום.", "לא נכון. המשימה לא עלתה כסף למשתתפים — הם דווקא קיבלו תשלום.", "נכון. 'tedious' פירושו משעמם ומייגע — לכן נדרש מהמשתתפים לשקר ולומר שהמשימה הייתה מהנה."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["a deliberately tedious task"]$q$::jsonb, $q$shabbat batch B, passage=dissonance, q5$q$, 5, true);
