  if not exists (select 1 from reading_passages where title = $q$Phineas Gage and the Study of the Brain$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Phineas Gage and the Study of the Brain$q$, $q$In September 1848, a railroad foreman named Phineas Gage was directing a crew that was blasting rock in Vermont. As he packed explosive powder into a hole with a long iron rod, a spark set off the charge. The rod, more than a meter long, shot upward through his left cheek and out of the top of his skull. Remarkably, Gage was speaking within minutes and was able to walk to a cart that carried him to a doctor.

The physician who treated him, John Harlow, later reported that Gage had survived but was no longer the same man. Before the accident, he had been a capable and well-liked worker with a reputation for good judgment. Afterwards, according to Harlow, he became impatient, rude, and unable to carry out his plans. His friends reportedly said he was 'no longer Gage', and the railroad company declined to give him back his job. The case suggested for the first time that a specific region at the front of the brain might govern personality and social conduct.

Gage's story became one of the most frequently repeated tales in psychology textbooks, and it grew more dramatic with each retelling. However, historians who examined the original records found that the change in his behavior was probably less extreme and less permanent than often claimed. Gage later worked for several years as a stagecoach driver in Chile, a demanding job requiring reliability and skill. He died in 1860, and his skull, along with the iron rod, is preserved at Harvard University. Despite the exaggerations, his case helped establish the idea that the brain's frontal regions play a role in who we are.$q$, $q$psychology$q$, 4, 274, true, $q$reading_shabbat_2026-09-05_B$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["Railroad Construction in Nineteenth-Century Vermont", "The Career of Dr. John Harlow", "A Famous Injury and the Birth of an Idea About the Brain", "Why Psychology Textbooks Cannot Be Trusted"]$q$::jsonb, 2, $q$["לא נכון. עבודת הרכבת היא רק הרקע לתאונה בפסקה הראשונה.", "לא נכון. הרלו מוזכר כרופא המטפל בלבד; הקטע אינו עוסק בקריירה שלו.", "נכון. הכותרת מקיפה את הפציעה, את מה שהיא לימדה על המוח ואת הסייגים המאוחרים — כל חלקי הקטע.", "לא נכון. הקטע מציין שהסיפור הוגזם, אך אינו טוען שאין לסמוך על ספרי לימוד."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch B, passage=gage, q1$q$, 1, true);
