    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, all of the following are true EXCEPT —$q$, $q$["Gage had been regarded as a worker with good judgment before the accident.", "Harlow described Gage as calmer and more careful after his recovery.", "The railroad company refused to give Gage his job back.", "The case suggested that a frontal brain region might influence personality and social behavior."]$q$::jsonb, 1, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — לפני התאונה היה גייג' עובד בעל שיקול דעת טוב.", "נכון. זו הקביעה השגויה — הרלו תיאר את גייג' אחרי התאונה כחסר סבלנות וגס, לא כרגוע וזהיר יותר.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — חברת הרכבת סירבה להחזירו לעבודה.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — המקרה רמז שאזור קדמי במוח קשור לאישיות ולהתנהגות חברתית."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["he became impatient, rude, and unable to carry out his plans"]$q$::jsonb, $q$shabbat batch B, passage=gage, q3$q$, 3, true);
