  if not exists (select 1 from reading_passages where title = $q$Loss Aversion$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Loss Aversion$q$, $q$Standard economic theory long assumed that people evaluate outcomes by their effect on total wealth. By this logic, gaining one hundred dollars and losing the same amount should be equal and opposite experiences. In 1979, the psychologists Daniel Kahneman and Amos Tversky published a paper arguing that this assumption was wrong. Their prospect theory held that people judge outcomes relative to a reference point, usually their current situation, rather than in absolute terms. Crucially, they found that losses loom larger than gains: the pain of losing a sum is roughly twice as intense as the pleasure of gaining it.

This asymmetry, which they called loss aversion, has been demonstrated in many settings. In one well-known experiment, some students were given a coffee mug while others were not. Those who owned the mug demanded about twice as much money to sell it as the others were willing to pay for it. Simply possessing an object, it seems, is enough to make giving it up feel like a loss. Loss aversion also explains why investors tend to hold falling shares too long, since selling would turn a paper loss into a real one.

The concept has had consequences far beyond the laboratory. Policy makers now know that describing a choice in terms of what might be lost is often more persuasive than describing the same choice in terms of gains. Kahneman received the Nobel Prize in economics in 2002, an unusual honor for a psychologist; Tversky had died six years earlier. Although some researchers argue that the strength of loss aversion varies more than the original work suggested, the basic finding has proved remarkably durable.$q$, $q$psychology$q$, 6, 271, true, $q$reading_shabbat_2026-09-05_B$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Kahneman won a Nobel Prize for work he did with Tversky.", "The discovery that losses weigh more heavily than gains challenged economic assumptions and has had wide practical influence.", "Students who owned a mug demanded more money than buyers would pay.", "Investors tend to hold falling shares for too long."]$q$::jsonb, 1, $q$["לא נכון. פרס נובל הוא פרט מהפסקה השלישית, לא הרעיון המרכזי.", "נכון. הקטע מציג את הממצא שהפסדים כואבים יותר מרווחים, את הראיות לו ואת השפעתו הרחבה — זהו הרעיון המרכזי.", "לא נכון. ניסוי הספל הוא דוגמה אחת מהפסקה השנייה.", "לא נכון. התנהגות המשקיעים היא דוגמה אחת מהפסקה השנייה."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch B, passage=loss-aversion, q1$q$, 1, true);
