      values (v_pid, $q$According to the second paragraph, why do investors tend to hold falling shares too long?$q$, $q$["Because selling would make the loss real rather than only on paper.", "Because they expect the shares to recover.", "Because owning the shares for a long time makes them seem more valuable than they are.", "Because they were given the shares as gifts."]$q$::jsonb, 0, $q$["נכון. הפסקה מסבירה שמכירה הופכת הפסד על הנייר להפסד ממשי, ולכן משקיעים נמנעים ממנה.", "לא נכון. הפסקה אינה מזכירה ציפייה להתאוששות המניות.", "לא נכון. הפסקה אינה קושרת את משך ההחזקה לערך הנתפס של המניות.", "לא נכון. הפסקה אינה מזכירה מניות שהתקבלו במתנה."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["selling would turn a paper loss into a real one"]$q$::jsonb, $q$shabbat batch B, passage=loss-aversion, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["explain the mug experiment in detail.", "describe the reference point in prospect theory.", "criticize the original research of 1979.", "show the wider influence of the concept and its standing among researchers today."]$q$::jsonb, 3, $q$["לא נכון. ניסוי הספל מתואר בפסקה השנייה.", "לא נכון. נקודת הייחוס מוסברת בפסקה הראשונה.", "לא נכון. הפסקה מזכירה מחלוקת על עוצמת האפקט, אך מסכמת שהממצא הבסיסי עמיד — אין זו ביקורת.", "נכון. הפסקה מתארת את ההשפעה על קובעי מדיניות, את פרס נובל ואת מעמדו העמיד של הממצא בקרב חוקרים."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch B, passage=loss-aversion, q3$q$, 3, true);
