      values (v_pid, $q$It can be inferred from the third paragraph that —$q$, $q$["Kahneman had trained as an economist before turning to psychology.", "the Nobel committee made an error in choosing Kahneman.", "the prize in economics usually goes to economists.", "Tversky would have refused the prize had he been alive."]$q$::jsonb, 2, $q$["לא נכון. הקטע מציג את כהנמן כפסיכולוג ואינו מזכיר הכשרה בכלכלה.", "לא נכון. הביטוי מציין שהדבר יוצא דופן, לא שהוא טעות.", "נכון. אם פרס נובל בכלכלה הוא כבוד יוצא דופן לפסיכולוג, משתמע שבדרך כלל הוא ניתן לכלכלנים.", "לא נכון. הקטע אינו רומז דבר על עמדתו של טברסקי כלפי הפרס."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, $q$["an unusual honor for a psychologist"]$q$::jsonb, $q$shabbat batch B, passage=loss-aversion, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the third paragraph, the word "durable" most nearly means —$q$, $q$["Long-lasting", "Highly controversial", "Very expensive", "Surprising to experts"]$q$::jsonb, 0, $q$["נכון. 'durable' פירושו עמיד, מחזיק מעמד לאורך זמן — הממצא שרד ביקורות ונותר תקף.", "לא נכון. המשפט מנוגד לביקורת ('Although'), ולכן המילה מבטאת יציבות ולא מחלוקת.", "לא נכון. אין בהקשר שום משמעות של עלות.", "לא נכון. המילה מתארת עמידות לאורך זמן, לא הפתעה."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["the basic finding has proved remarkably durable"]$q$::jsonb, $q$shabbat batch B, passage=loss-aversion, q5$q$, 5, true);
