  if not exists (select 1 from reading_passages where title = $q$Pavlov's Dogs and Classical Conditioning$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Pavlov's Dogs and Classical Conditioning$q$, $q$Ivan Pavlov was a Russian scientist who spent many years studying how the body digests food. In 1904, he received the Nobel Prize for this research, which involved measuring the saliva and stomach juices of dogs. During his experiments, Pavlov noticed something he had not planned to study. The dogs began to produce saliva before any food arrived, as soon as they saw the assistant who usually fed them. Pavlov realized that the dogs had learned to connect the assistant with food.

He decided to test this idea in a careful and systematic way. Just before feeding a dog, he made a sound, such as the ticking of a metronome or the ring of a bell. At first, the sound meant nothing to the dog, and only the food made it salivate. After the sound and the food had been paired many times, however, the dog began to salivate at the sound alone. Pavlov called the food an unconditioned stimulus, since it produced saliva naturally, and the sound a conditioned stimulus, since its effect had been learned.

Pavlov also discovered that this kind of learning could be undone. If the sound was repeated many times without food, the dog gradually stopped responding to it, a process he called extinction. He found, too, that dogs would salivate to sounds similar to the original one, though the response was weaker. This type of learning is now called classical conditioning, and it has been shown in many animals, including humans. Today Pavlov is remembered less for his work on digestion than for a discovery he made almost by accident.$q$, $q$psychology$q$, 3, 265, true, $q$reading_shabbat_2026-09-05_B$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the passage, what can be inferred about Pavlov's discovery of conditioning?$q$, $q$["It was the reason he received the Nobel Prize.", "It was based mainly on experiments with humans.", "It took place before he began studying digestion.", "It grew out of an observation that was unrelated to the purpose of his original research."]$q$::jsonb, 3, $q$["לא נכון. הפסקה הראשונה קובעת שהפרס ניתן על מחקר העיכול, לא על ההתניה.", "לא נכון. הניסויים נערכו על כלבים; בני אדם מוזכרים רק כמי שהתופעה הודגמה בהם מאוחר יותר.", "לא נכון. הקטע מתאר שההבחנה עלתה במהלך ניסויי העיכול, לא לפניהם.", "נכון. הקטע כותב שפבלוב הבחין בדבר שלא תכנן לחקור, ומסכם שהגילוי נעשה כמעט במקרה — כלומר לא היה קשור למטרת מחקרו המקורי."]$q$::jsonb, $q$inference$q$, $q$text$q$, null, $q$shabbat batch B, passage=pavlov, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, when did the dogs begin to "produce saliva before any food arrived"?$q$, $q$["When they heard the ticking of a metronome.", "When they were placed in the laboratory.", "When they saw their usual feeder.", "When they had not eaten for several hours."]$q$::jsonb, 2, $q$["לא נכון. המטרונום נכנס לתמונה רק בניסוי המכוון שתואר בפסקה השנייה.", "לא נכון. הפסקה אינה קושרת את הריור לכניסה למעבדה.", "נכון. הפסקה הראשונה כותבת שהכלבים החלו לרייר ברגע שראו את העוזר שנהג להאכיל אותם.", "לא נכון. הפסקה אינה מזכירה רעב או שעות ללא אוכל."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["produce saliva before any food arrived"]$q$::jsonb, $q$shabbat batch B, passage=pavlov, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, all of the following are true EXCEPT —$q$, $q$["The sound at first had no effect.", "Pavlov referred to the food as a conditioned stimulus.", "The sound was paired with food many times before the dog responded to it alone.", "Pavlov used sounds such as a metronome or a bell."]$q$::jsonb, 1, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — בתחילה הצליל לא אמר דבר לכלב.", "נכון. זו הקביעה השגויה — פבלוב כינה את האוכל גירוי בלתי מותנה, ואת הצליל גירוי מותנה.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — הצליל והאוכל הוצמדו פעמים רבות.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — מטרונום ופעמון מוזכרים במפורש."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Pavlov called the food an unconditioned stimulus"]$q$::jsonb, $q$shabbat batch B, passage=pavlov, q3$q$, 3, true);
