  if not exists (select 1 from reading_passages where title = $q$The Dunning-Kruger Effect$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Dunning-Kruger Effect$q$, $q$In 1999, two psychologists at Cornell University, Justin Kruger and David Dunning, published a study with a provocative conclusion. People who perform poorly at a task, they argued, often lack the very skills needed to recognize their own poor performance. As a result, they tend to rate themselves far more highly than their actual results justify.

In their experiments, students completed tests of grammar, logical reasoning, and the ability to judge humor. They were then asked to estimate how well they had done compared with other participants. Students whose scores placed them in the lowest quarter typically guessed that they had performed above average. The strongest performers, by contrast, slightly underestimated their standing, apparently assuming that tasks they found easy were easy for everyone. When the weakest students were given training in the skill being tested, their self-assessments became noticeably more accurate.

The finding quickly spread beyond psychology and is now often mentioned in discussions of politics, business, and everyday life. It is frequently summarized as the claim that incompetent people are the most confident, though this is a simplification. The original study found that poor performers overestimated themselves, not that they were more confident than experts in absolute terms.

Some researchers have also questioned the effect itself, arguing that part of the pattern is a statistical artifact. Since nobody can guess their own rank perfectly, low scorers will tend to guess too high and high scorers too low, simply by chance. Dunning has responded that the effect persists even when such factors are taken into account. Whatever the outcome of this debate, the study remains a useful reminder that confidence and competence are not the same thing.$q$, $q$psychology$q$, 4, 277, true, $q$reading_shabbat_2026-09-05_B$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the second paragraph that —$q$, $q$["the strongest performers were unable to judge their own work.", "learning a skill also improves a person's ability to judge how well he or she performs it.", "the students were given the test results before estimating their rank.", "humor was the most difficult of the three tests."]$q$::jsonb, 1, $q$["לא נכון. החזקים דווקא הפחיתו מעט בערך עצמם, כלומר שפטו את עצמם קרוב למדי למציאות.", "נכון. הפסקה מציינת שאחרי אימון במיומנות, ההערכה העצמית של החלשים הפכה מדויקת יותר — מכאן שלימוד המיומנות משפר גם את היכולת לשפוט את הביצוע.", "לא נכון. הסטודנטים נתבקשו להעריך את ביצועיהם, ואין רמז שקיבלו את התוצאות לפני כן.", "לא נכון. הפסקה אינה משווה את קושי המבחנים."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, $q$["their self-assessments became noticeably more accurate"]$q$::jsonb, $q$shabbat batch B, passage=dunning-kruger, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, what did the study find about students whose scores were "in the lowest quarter"?$q$, $q$["They believed they had outperformed most participants.", "They refused to estimate how well they had done.", "They rated themselves slightly below the average participant.", "They improved dramatically after being told their results."]$q$::jsonb, 0, $q$["נכון. הפסקה השנייה כותבת שהם העריכו בדרך כלל שביצעו מעל הממוצע.", "לא נכון. הפסקה אינה מזכירה סירוב להעריך.", "לא נכון. הפסקה קובעת את ההפך — הם העריכו את עצמם מעל הממוצע.", "לא נכון. השיפור בהערכה העצמית הגיע לאחר אימון במיומנות, לא לאחר מסירת התוצאות."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["in the lowest quarter"]$q$::jsonb, $q$shabbat batch B, passage=dunning-kruger, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Which of the following is NOT mentioned in the third paragraph?$q$, $q$["The finding is now discussed in fields outside psychology.", "The finding is often summarized too simply.", "Poor performers were found to be more confident than experts.", "The original study concerned overestimation rather than absolute confidence levels of participants."]$q$::jsonb, 2, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — הממצא מוזכר בפוליטיקה, בעסקים ובחיי היומיום.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — הפסקה מכנה את הסיכום הנפוץ פישוט.", "נכון. הפסקה אומרת במפורש שהמחקר לא מצא שהחלשים בטוחים בעצמם יותר מהמומחים; זהו הפרט שאינו מופיע כממצא.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — המחקר עסק בהערכת יתר ולא בביטחון מוחלט."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["not that they were more confident than experts in absolute terms"]$q$::jsonb, $q$shabbat batch B, passage=dunning-kruger, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the first paragraph is to —$q$, $q$["describe the tests used in the experiments.", "summarize criticism of the study.", "explain the statistical concept of regression.", "introduce the researchers and the central claim of their study."]$q$::jsonb, 3, $q$["לא נכון. המבחנים מתוארים בפסקה השנייה.", "לא נכון. הביקורת מופיעה בפסקה הרביעית.", "לא נכון. הטיעון הסטטיסטי מופיע בפסקה הרביעית, והמונח עצמו אינו מוסבר.", "נכון. הפסקה מציגה את קרוגר ודאנינג ואת טענתם המרכזית — שמי שמבצע גרוע חסר את הכלים לזהות זאת."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch B, passage=dunning-kruger, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["explain why Dunning rejected all criticism.", "describe how the students estimated their rank.", "present a challenge to the finding along with a response to it.", "argue that the effect is entirely a statistical artifact and should be discarded by researchers."]$q$::jsonb, 2, $q$["לא נכון. הפסקה מביאה את תגובת דאנינג, אך אינה טוענת שדחה כל ביקורת, ואין זו מטרתה.", "לא נכון. אופן ההערכה של הסטודנטים מתואר בפסקה השנייה.", "נכון. הפסקה מציגה את הטענה שהאפקט הוא בחלקו תוצר סטטיסטי, את תשובת דאנינג ואת הלקח שנותר בעינו.", "לא נכון. הפסקה מציגה את הביקורת כטענה של חלק מהחוקרים, ומציינת שהלקח נותר תקף — היא אינה קוראת לזנוח את האפקט."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch B, passage=dunning-kruger, q5$q$, 5, true);
  end if;
end $$;
do $$ declare v_pid uuid; begin

  if not exists (select 1 from reading_passages where title = $q$ARPANET and the Origins of the Internet$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$ARPANET and the Origins of the Internet$q$, $q$In the late 1960s, the Advanced Research Projects Agency of the United States Department of Defense funded an experimental computer network. The project, known as ARPANET, aimed to let expensive computers at distant universities share their resources with one another. A popular story holds that the network was designed to survive a nuclear attack on American cities. However, the engineers who built it have insisted that resource sharing, not military survival, was their central goal.

The technical foundation of ARPANET was packet switching, a method that breaks messages into small blocks sent separately across the network. Each packet could travel by a different route and be reassembled at its destination, which made the system flexible and efficient. The first four nodes were installed in 1969 at three sites in California and one in Utah. On October 29 of that year, a student at UCLA attempted to send the word "login" to a computer at the Stanford Research Institute. The system crashed after only two letters had arrived, so the first message ever sent was simply "lo".

Despite this modest beginning, the network grew steadily throughout the 1970s as more institutions joined. In 1971, the engineer Ray Tomlinson sent the first network email and chose the @ symbol to separate the user's name from the machine's. Yet ARPANET could not easily communicate with other networks that used different technical rules. To solve this problem, Vint Cerf and Robert Kahn designed a common set of protocols called TCP/IP. On January 1, 1983, ARPANET switched to these protocols, a date many historians regard as the birth of the modern internet.

ARPANET itself was shut down in 1990, by which time its role had been taken over by larger networks. Its lasting contribution was not any single machine but the idea that independent networks could join together under shared rules. Every email, web page, and video call today still relies on principles first tested by a handful of researchers.$q$, $q$technology$q$, 5, 319, true, $q$reading_shabbat_2026-09-05_C$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["A student at UCLA accidentally sent the very first message across the network in 1969.", "Ray Tomlinson invented email and chose the @ symbol to separate names from machines.", "An experimental network built for sharing computers developed the ideas behind the internet.", "ARPANET was secretly designed by the military to keep working after a nuclear attack."]$q$::jsonb, 2, $q$["לא נכון. זו קביעה נכונה מהפסקה השנייה, אבל היא פרט אחד בלבד ולא הרעיון המרכזי של הקטע כולו.", "לא נכון. זו קביעה נכונה מהפסקה השלישית, אבל היא פרט צר ולא הרעיון המרכזי של הקטע.", "נכון. הקטע כולו עוקב אחרי ARPANET, רשת ניסיונית שנועדה לשיתוף מחשבים, ומראה כיצד הרעיונות שנבדקו בה הפכו לבסיס האינטרנט המודרני.", "לא נכון. הפסקה הראשונה מציגה את סיפור ההתקפה הגרעינית כסיפור עממי, ומדגישה שהמהנדסים עצמם דחו אותו."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch C, passage=arpanet, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, what happened when the first message was sent in 1969?$q$, $q$["The connection failed before the complete word could reach the computer at the other end.", "The word arrived correctly at the Stanford Research Institute within a few seconds.", "The computer at UCLA caught fire and had to be replaced by the university.", "The message was delivered to the wrong university because of a routing error."]$q$::jsonb, 0, $q$["נכון. הפסקה מספרת שהמערכת קרסה אחרי שתי אותיות בלבד, ולכן רק חלק מהמילה הגיע ליעדו.", "לא נכון. הפסקה מציינת שהמערכת קרסה ורק שתי אותיות הגיעו, ולא שהמילה כולה נשלחה בהצלחה.", "לא נכון. הפסקה מדברת על קריסה של המערכת, ואינה מזכירה שריפה או החלפת מחשב.", "לא נכון. הפסקה אינה מזכירה טעות ניתוב או הגעה לאוניברסיטה אחרת."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["The system crashed after only two letters had arrived"]$q$::jsonb, $q$shabbat batch C, passage=arpanet, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the third paragraph is to —$q$, $q$["explain in detail how packet switching divides messages into small separate blocks.", "describe the failed attempt to send the word \"login\" between two universities in 1969.", "argue that the network was shut down in 1990 because larger networks had replaced it.", "describe the network's growth and the shared protocols that let it connect with other networks."]$q$::jsonb, 3, $q$["לא נכון. זהו תוכן הפסקה השנייה — הסבר על מיתוג מנות — ולא הפסקה השלישית.", "לא נכון. זהו תוכן הפסקה השנייה — ההודעה הראשונה שנכשלה — ולא הפסקה השלישית.", "לא נכון. זהו תוכן הפסקה הרביעית — סגירת הרשת ב-1990 — ולא הפסקה השלישית.", "נכון. הפסקה השלישית מתארת את צמיחת הרשת בשנות השבעים ואת פיתוח הפרוטוקולים המשותפים (TCP/IP) שאפשרו חיבור לרשתות אחרות."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=arpanet, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the statement that the engineers "insisted that resource sharing, not military survival, was their central goal," what can be inferred?$q$, $q$["The engineers who built the network were forbidden from discussing its military purpose.", "The popular account of the network's origin differs from the version given by its builders.", "The Department of Defense had no involvement whatsoever in funding the early network.", "The network was never actually capable of sharing computer resources between universities."]$q$::jsonb, 1, $q$["לא נכון. הקטע אינו מזכיר איסור כלשהו על המהנדסים לדבר על הפרויקט.", "נכון. הפסקה מציגה סיפור עממי על הישרדות מפני התקפה גרעינית, ומיד אחריו את עמדת המהנדסים שהמטרה הייתה שיתוף משאבים — כלומר שני ההסברים אינם תואמים.", "לא נכון. הפסקה הראשונה קובעת במפורש שסוכנות של משרד ההגנה מימנה את הרשת.", "לא נכון. הקטע מתאר שהרשת אכן אפשרה למחשבים באוניברסיטאות לשתף משאבים."]$q$::jsonb, $q$inference$q$, $q$anchor$q$, $q$["insisted that resource sharing, not military survival, was their central goal"]$q$::jsonb, $q$shabbat batch C, passage=arpanet, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the third paragraph, the word "modest" is closest in meaning to —$q$, $q$["Small and unimpressive", "Very expensive", "Highly secret and known to very few people", "Quick and technically successful from the start"]$q$::jsonb, 0, $q$["נכון. 'modest' פירושו צנוע, קטן ולא מרשים — ההתחלה הצנועה היא ההודעה הראשונה שנכשלה אחרי שתי אותיות.", "לא נכון. המילה אינה עוסקת בעלות או בתכנון, אלא בגודל ובחשיבות הצנועים של ההתחלה.", "לא נכון. המילה אינה קשורה לסודיות.", "לא נכון. ההקשר הוא הפוך — ההתחלה הייתה כישלון חלקי, לא הצלחה מהירה."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["Despite this modest beginning"]$q$::jsonb, $q$shabbat batch C, passage=arpanet, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$GPS and Einstein's Relativity$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$GPS and Einstein's Relativity$q$, $q$The Global Positioning System determines a receiver's location by measuring how long radio signals take to arrive from several satellites. Because these signals travel at the speed of light, a timing error of a single microsecond translates into a position error of roughly 300 meters. The system therefore depends on atomic clocks aboard each satellite that are accurate to within a few billionths of a second. Surprisingly, this extreme precision means that the satellites cannot be treated as ordinary clocks at all.

Albert Einstein's theories predict two separate effects on time that become relevant at this level of accuracy. According to special relativity, a clock moving rapidly relative to an observer ticks more slowly than a clock at rest. GPS satellites travel at about 14,000 kilometers per hour, which causes their clocks to fall behind ground clocks by roughly seven microseconds each day. General relativity, however, predicts the opposite tendency, since clocks in weaker gravity run faster than clocks near the Earth's surface. At an altitude of about 20,000 kilometers, this effect makes the satellite clocks gain around 45 microseconds daily. The combined result is that an uncorrected satellite clock would run ahead by approximately 38 microseconds every day.

Although 38 microseconds may sound trivial, the resulting position errors would accumulate to about ten kilometers within a single day. Engineers solved the problem by adjusting the satellite clocks before launch so that they tick slightly more slowly than a clock on the ground. Once in orbit, the relativistic effects speed them up to precisely the intended rate. Every time a phone displays its position on a map, it is quietly relying on a century-old theory. Few technologies offer a more convincing daily demonstration that Einstein's ideas describe the real world.$q$, $q$technology / physics$q$, 6, 284, true, $q$reading_shabbat_2026-09-05_C$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["How Atomic Clocks Are Built and Tested Before Launch", "Why Satellite Navigation Depends on Einstein", "The Difference Between Special and General Relativity", "Maps on Phones"]$q$::jsonb, 1, $q$["לא נכון. הקטע מזכיר שעונים אטומיים, אך אינו עוסק בבנייתם או בבדיקתם.", "נכון. הקטע כולו מסביר מדוע מערכת הניווט הלווייני חייבת להתחשב בתורת היחסות של איינשטיין כדי לפעול.", "לא נכון. הקטע מציג את שתי התיאוריות רק ככלי להסבר בעיית השעונים, ולא כנושא בפני עצמו.", "לא נכון. הטלפון מוזכר במשפט אחד בלבד בפסקה האחרונה, ולא כנושא הקטע."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch C, passage=gps-relativity, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, all of the following are true EXCEPT —$q$, $q$["The rapid motion of the satellites causes their clocks to lose time relative to clocks on the ground.", "Weaker gravity at high altitude causes the satellite clocks to run faster than clocks on Earth.", "The net effect of the two influences is that a satellite clock gains time every day.", "The two relativistic effects cancel each other out exactly, so that no correction of the clocks is needed."]$q$::jsonb, 3, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — היחסות הפרטית אכן גורמת לשעונים הנעים לפגר.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — היחסות הכללית אכן גורמת לשעונים בכבידה חלשה למהר.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — התוצאה המשולבת היא הקדמה של כ-38 מיקרו-שניות ביום.", "נכון. זו הקביעה השגויה — הפסקה קובעת שהאפקטים אינם מבטלים זה את זה, אלא משאירים הפרש של כ-38 מיקרו-שניות ביום, ולכן נדרש תיקון."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["The combined result is that an uncorrected satellite clock would run ahead by approximately 38 microseconds every day"]$q$::jsonb, $q$shabbat batch C, passage=gps-relativity, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the first paragraph is to —$q$, $q$["explain why the system requires such extraordinarily precise timing in order to work.", "describe the two opposite effects that Einstein's theories predict for moving clocks.", "explain how engineers adjust the satellite clocks before they are launched into orbit.", "argue that Einstein's theories have been confirmed by everyday technology."]$q$::jsonb, 0, $q$["נכון. הפסקה הראשונה מסבירה שהמיקום מחושב מזמני הגעת אותות, ולכן טעות זעירה בזמן הופכת לטעות גדולה במרחק — כלומר מדוע נדרש דיוק קיצוני.", "לא נכון. זהו תוכן הפסקה השנייה — שני האפקטים של תורת היחסות — ולא הפסקה הראשונה.", "לא נכון. זהו תוכן הפסקה השלישית — כיוונון השעונים לפני השיגור — ולא הפסקה הראשונה.", "לא נכון. זהו הרעיון שבו מסתיימת הפסקה השלישית, ולא מטרת הפסקה הראשונה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=gps-relativity, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the third paragraph that —$q$, $q$["the satellite clocks are adjusted only after they have reached their final orbit.", "Einstein personally proposed the method used to correct the satellite clocks.", "without the correction, the system would quickly become useless for navigation.", "the correction has proved less effective than the engineers originally expected."]$q$::jsonb, 2, $q$["לא נכון. הפסקה קובעת שהשעונים מכוונים לפני השיגור, ולא אחרי הגעתם למסלול.", "לא נכון. הפסקה מייחסת את הפתרון למהנדסים; איינשטיין רק סיפק את התיאוריה.", "נכון. הפסקה מציינת שטעויות המיקום היו מצטברות לכעשרה קילומטרים בתוך יום אחד, ומכאן שבלי תיקון המערכת הייתה חסרת תועלת במהירות.", "לא נכון. הפסקה מתארת את התיקון כמוצלח — האפקטים מאיצים את השעונים בדיוק לקצב הרצוי."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=gps-relativity, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the third paragraph, the word "trivial" is closest in meaning to —$q$, $q$["Extremely dangerous to the accuracy of the system", "Unimportant", "Difficult to measure with the available instruments", "Surprisingly large compared with the expected value"]$q$::jsonb, 1, $q$["לא נכון. המשמעות היא הפוכה — המילה מתארת משהו שנראה חסר חשיבות.", "נכון. 'trivial' פירושו זניח או חסר חשיבות — הפסקה אומרת ש-38 מיקרו-שניות עשויות להישמע זניחות, אך למעשה הן קריטיות.", "לא נכון. המילה אינה עוסקת בקושי המדידה.", "לא נכון. המשמעות היא הפוכה — המילה מציינת דבר שנראה קטן, לא גדול."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["Although 38 microseconds may sound trivial"]$q$::jsonb, $q$shabbat batch C, passage=gps-relativity, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$The Barcode$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Barcode$q$, $q$In 1948, a graduate student named Bernard Silver overheard a grocery executive asking for a way to read product information automatically at checkout. Silver shared the problem with his friend Norman Joseph Woodland, who became fascinated by it. While sitting on a beach in Florida, Woodland drew the dots and dashes of Morse code in the sand with his fingers. He then pulled his fingers downward, stretching the marks into thin and thick lines. That simple gesture produced the basic idea of the barcode, which the two men patented in 1952.

Their original design used concentric circles rather than straight lines, so that it could be read from any direction. However, the technology of the time was not ready for it, and the idea sat unused for nearly two decades. The invention of the laser in 1960 finally made it practical to scan a printed code quickly and cheaply. In the early 1970s, the grocery industry formed a committee to choose a single standard code for all products. An IBM engineer named George Laurer designed the rectangular pattern that won, known today as the Universal Product Code.

The first item ever scanned commercially was a pack of chewing gum at a supermarket in Troy, Ohio, in June 1974. Adoption was slow at first, since stores had to buy expensive scanners and manufacturers had to print codes on every package. Yet once enough businesses had joined, the benefits became impossible to ignore. Checkout lines moved faster, pricing errors became rarer, and shops could track their inventory automatically. Today the same striped pattern appears on nearly every product sold, and it also organizes hospitals, warehouses, and libraries.$q$, $q$technology$q$, 4, 271, true, $q$reading_shabbat_2026-09-05_C$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Norman Joseph Woodland got the idea for the barcode while sitting on a beach in Florida.", "The first product ever scanned with a barcode was a pack of chewing gum in Ohio.", "The invention of the laser in 1960 was the most important event in the history of retail.", "A simple idea from the 1940s slowly grew into a standard that now organizes commerce around the world."]$q$::jsonb, 3, $q$["לא נכון. זו קביעה נכונה מהפסקה הראשונה, אבל היא פרט אחד בלבד ולא הרעיון המרכזי של הקטע.", "לא נכון. זו קביעה נכונה מהפסקה השלישית, אבל היא פרט צר ולא הרעיון המרכזי.", "לא נכון. הקטע מזכיר את הלייזר כשלב אחד בדרך, ואינו טוען שהוא האירוע החשוב ביותר בתולדות המסחר.", "נכון. הקטע עוקב אחרי הברקוד מרעיון פשוט בשנות הארבעים, דרך עיכובים ותקינה, ועד להפיכתו לתקן כמעט אוניברסלי."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch C, passage=barcode, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, what did Woodland do after drawing "the dots and dashes of Morse code in the sand"?$q$, $q$["He erased the marks and drew a set of concentric circles instead.", "He dragged his fingers down, turning the marks into lines of different widths.", "He telephoned Bernard Silver and asked him to file a patent immediately.", "He copied the pattern onto paper so that a laser could scan it."]$q$::jsonb, 1, $q$["לא נכון. העיגולים הקונצנטריים מוזכרים בפסקה השנייה כעיצוב המקורי, אך לא כפעולה שעשה בחוף.", "נכון. הפסקה מספרת שהוא משך את אצבעותיו כלפי מטה ומתח את הסימנים לקווים דקים ועבים.", "לא נכון. הפסקה אינה מזכירה שיחת טלפון; הפטנט נרשם רק ב-1952.", "לא נכון. הלייזר הומצא רק ב-1960, שנים אחרי האירוע בחוף."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["He then pulled his fingers downward, stretching the marks into thin and thick lines"]$q$::jsonb, $q$shabbat batch C, passage=barcode, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["describe how a beach in Florida inspired the original idea for the barcode.", "list the benefits that stores enjoyed once barcodes were widely adopted.", "explain why the invention was delayed and how a single standard was finally chosen.", "describe the first commercial scan of a product in a supermarket in Ohio."]$q$::jsonb, 2, $q$["לא נכון. זהו תוכן הפסקה הראשונה — ההשראה בחוף — ולא הפסקה השנייה.", "לא נכון. זהו תוכן הפסקה השלישית — היתרונות לחנויות — ולא הפסקה השנייה.", "נכון. הפסקה השנייה מסבירה שהטכנולוגיה לא הייתה בשלה במשך כעשרים שנה, ואז מתארת כיצד נבחר תקן אחיד.", "לא נכון. זהו תוכן הפסקה השלישית — הסריקה המסחרית הראשונה — ולא הפסקה השנייה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=barcode, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["describe the first commercial use of the barcode and its gradual spread to other fields.", "explain how Morse code inspired the thin and thick lines of the barcode.", "describe the committee that selected the Universal Product Code as the standard.", "explain why the original circular design was replaced by a rectangular one."]$q$::jsonb, 0, $q$["נכון. הפסקה האחרונה פותחת בסריקה המסחרית הראשונה ב-1974, ואז מתארת את האימוץ האיטי ואת ההתפשטות הרחבה של הטכנולוגיה.", "לא נכון. זהו תוכן הפסקה הראשונה — ההשראה מקוד מורס — ולא הפסקה האחרונה.", "לא נכון. זהו תוכן הפסקה השנייה — הוועדה והתקן — ולא הפסקה האחרונה.", "לא נכון. הקטע אינו מסביר במפורש מדוע הוחלף העיצוב העגול, ובכל מקרה זה אינו נושא הפסקה האחרונה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=barcode, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the sentence "However, the technology of the time was not ready for it," the word "it" refers to —$q$, $q$["the laser", "the grocery industry", "the Morse code that Woodland drew in the sand", "the circular barcode design"]$q$::jsonb, 3, $q$["לא נכון. הלייזר מוזכר רק במשפט שאחרי, כפתרון לבעיה.", "לא נכון. תעשיית המזון מוזכרת בהמשך הפסקה, ולא במשפט הקודם.", "לא נכון. קוד מורס מוזכר בפסקה הראשונה בלבד, ואינו הנושא של המשפט הקודם.", "נכון. המשפט הקודם מתאר את העיצוב המקורי בעיגולים קונצנטריים, ו'it' מתייחס לעיצוב הזה, שהטכנולוגיה עוד לא הייתה מוכנה לו."]$q$::jsonb, $q$reference_word$q$, $q$anchor$q$, $q$["However, the technology of the time was not ready for it"]$q$::jsonb, $q$shabbat batch C, passage=barcode, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$The QWERTY Keyboard and Why It Survived$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The QWERTY Keyboard and Why It Survived$q$, $q$The arrangement of letters on nearly every keyboard in the English-speaking world dates back to the 1870s. It was developed by Christopher Latham Sholes, a printer from Milwaukee who built one of the first commercially successful typewriters. The layout takes its name from the first six letters on its top row of keys. Sholes sold his design to the arms manufacturer Remington, which began producing the machines in 1874.

The most common explanation for the odd arrangement concerns a mechanical problem in early typewriters. When two neighboring keys were struck in rapid succession, the metal bars that carried the letters tended to collide and jam. According to this account, Sholes separated frequently paired letters so that typists would strike them from different sides of the machine. Some historians have questioned this story, suggesting instead that the layout was shaped by the needs of telegraph operators. Whatever the true origin, the arrangement was certainly not designed with the comfort or speed of modern typists in mind.

In 1936, a professor named August Dvorak patented an alternative layout that placed the most common letters on the middle row. Its supporters claimed it allowed faster and less tiring typing, although later studies found the advantage to be smaller than promised. Nevertheless, the Dvorak layout never came close to replacing its rival. Economists often cite QWERTY as an example of how an early standard can survive simply because everyone has already adopted it. Typists learn the existing layout, manufacturers build for those typists, and the cycle continues regardless of whether a better design exists.$q$, $q$technology$q$, 4, 258, true, $q$reading_shabbat_2026-09-05_C$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["The QWERTY layout arose from early technical constraints and endures because of widespread adoption, not superiority.", "Christopher Latham Sholes designed the first commercially successful typewriter in the 1870s.", "The Dvorak layout offered faster typing but was never adopted by manufacturers.", "Early typewriters jammed when neighboring keys were struck in rapid succession."]$q$::jsonb, 0, $q$["נכון. הקטע מסביר את מקורות הפריסה במגבלות הטכניות של מכונות הכתיבה, ואז מראה שהיא שרדה בגלל האימוץ הנרחב ולא בגלל עליונות.", "לא נכון. זו קביעה נכונה מהפסקה הראשונה, אבל היא פרט אחד בלבד ולא הרעיון המרכזי.", "לא נכון. הפסקה השלישית מציינת שהיתרון של דבוראק היה קטן מהמובטח, וממילא זהו פרט ולא הרעיון המרכזי.", "לא נכון. זו קביעה נכונה מהפסקה השנייה, אבל היא פרט טכני ולא הרעיון המרכזי של הקטע."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch C, passage=qwerty, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Which of the following is NOT mentioned in the first paragraph?$q$, $q$["The city where Sholes worked as a printer before building his typewriter.", "The origin of the name given to the keyboard layout.", "The reason Sholes chose that particular order for the letters.", "The company that manufactured the typewriters from 1874 onward."]$q$::jsonb, 2, $q$["לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — הפסקה מציינת שסולס היה מדפיס ממילווקי.", "לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — הפסקה מסבירה שהשם נגזר משש האותיות הראשונות בשורה העליונה.", "נכון. זו הקביעה השגויה — הסיבה לסדר האותיות נדונה רק בפסקה השנייה, ואינה מוזכרת כלל בפסקה הראשונה.", "לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — הפסקה מציינת שרמינגטון החלה לייצר את המכונות ב-1874."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=qwerty, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["describe how Remington began mass-producing Sholes's typewriter in the 1870s.", "present the traditional explanation for the layout and note that some historians doubt it.", "explain why the Dvorak layout failed to replace the existing keyboard standard.", "argue that telegraph operators were the true inventors of the modern keyboard."]$q$::jsonb, 1, $q$["לא נכון. זהו תוכן הפסקה הראשונה — הייצור על ידי רמינגטון — ולא הפסקה השנייה.", "נכון. הפסקה השנייה מציגה את ההסבר המקובל על התקעות המוטות, ואז מציינת שיש היסטוריונים שמפקפקים בו.", "לא נכון. זהו תוכן הפסקה השלישית — כישלון פריסת דבוראק — ולא הפסקה השנייה.", "לא נכון. הפסקה מזכירה את מפעילי הטלגרף רק כהשערה חלופית, ואינה טוענת שהם המציאו את המקלדת."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=qwerty, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the passage, what can be inferred about the Dvorak layout?$q$, $q$["It was banned by manufacturers who had invested heavily in QWERTY machines.", "It was eventually proven to be slower and more tiring than QWERTY.", "It was designed by Sholes as an improvement on his original arrangement.", "Its failure to spread had more to do with QWERTY's established position than with its own flaws."]$q$::jsonb, 3, $q$["לא נכון. הקטע אינו מזכיר איסור כלשהו; הוא מסביר את הכישלון באמצעות מעגל האימוץ.", "לא נכון. הפסקה השלישית אומרת שהיתרון היה קטן מהמובטח, לא שדבוראק הייתה גרועה יותר.", "לא נכון. הפסקה השלישית מייחסת את הפריסה לאוגוסט דבוראק ב-1936, לא לסולס.", "נכון. הפסקה השלישית מסבירה שתקן מוקדם שורד משום שכולם כבר אימצו אותו, 'בין אם קיים עיצוב טוב יותר ובין אם לא' — כלומר הכישלון נובע ממעמדה של QWERTY."]$q$::jsonb, $q$inference$q$, $q$text$q$, null, $q$shabbat batch C, passage=qwerty, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the third paragraph, the word "rival" most nearly means —$q$, $q$["Inventor", "The original manufacturer of the typewriter", "Competitor", "A newer and more modern version"]$q$::jsonb, 2, $q$["לא נכון. המילה אינה מציינת ממציא.", "לא נכון. המילה אינה מתייחסת ליצרן.", "נכון. 'rival' פירושו מתחרה — פריסת דבוראק לא הצליחה להחליף את מתחרתה, QWERTY.", "לא נכון. היריבה, QWERTY, היא דווקא הפריסה הישנה יותר."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["the Dvorak layout never came close to replacing its rival"]$q$::jsonb, $q$shabbat batch C, passage=qwerty, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$The Transistor$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Transistor$q$, $q$Before the late 1940s, electronic devices depended on vacuum tubes to amplify signals and switch currents on and off. These glass tubes worked, but they were bulky, fragile, and hot, and they burned out with frustrating regularity. A computer built from thousands of tubes could fill an entire room and fail several times a day. Engineers at Bell Laboratories in New Jersey were therefore searching for a solid replacement that had no moving parts and no glowing filament.

In December 1947, two physicists named John Bardeen and Walter Brattain succeeded in building the first working transistor. Their device used a small piece of germanium, a material that conducts electricity only under certain conditions. Their colleague William Shockley, frustrated at being left out of the breakthrough, soon designed an improved version that was easier to manufacture. The three men shared the Nobel Prize in Physics in 1956 for their work.

The transistor performed the same tasks as a vacuum tube while using far less power and occupying a fraction of the space. At first, its most visible application was the portable radio, which appeared in shops in 1954 and became a symbol of youth culture. Yet the deeper revolution came when engineers learned to place many transistors on a single piece of silicon. This integrated circuit, developed independently by Jack Kilby and Robert Noyce in 1958 and 1959, made modern computing possible.

Shockley later founded his own company in California, and several employees who left it went on to establish the firms that built Silicon Valley. Today a single chip may contain billions of transistors, each one a descendant of the crude device assembled at Bell Labs. It is difficult to name another invention of the twentieth century whose influence has spread so quietly and so widely.$q$, $q$technology$q$, 5, 291, true, $q$reading_shabbat_2026-09-05_C$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["The Portable Radio and the Rise of Youth Culture", "The Small Device That Transformed Electronics", "Shockley and Silicon Valley", "The Problems of Vacuum Tubes in Early Computers"]$q$::jsonb, 1, $q$["לא נכון. הרדיו הנייד מוזכר במשפט אחד בפסקה השלישית, ואינו נושא הקטע.", "נכון. הקטע עוקב אחרי המצאת הטרנזיסטור, יתרונותיו והשפעתו העצומה על האלקטרוניקה המודרנית.", "לא נכון. החברה של שוקלי מוזכרת בקצרה בפסקה האחרונה, ואינה הנושא המרכזי.", "לא נכון. זהו תוכן הפסקה הראשונה בלבד — הרקע לבעיה — ולא הקטע כולו."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch C, passage=transistor, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, what was a drawback of vacuum tubes?$q$, $q$["They broke down often and took up a great deal of space.", "They could not amplify signals or switch currents on and off.", "They required moving parts that were expensive to manufacture.", "They were too small to be used in the computers of the time."]$q$::jsonb, 0, $q$["נכון. הפסקה מתארת את השפופרות כגדולות, שבירות וחמות, שנשרפות לעיתים קרובות — מחשב מהן מילא חדר שלם ונכשל כמה פעמים ביום.", "לא נכון. הפסקה קובעת שהשפופרות דווקא הגבירו אותות ומיתגו זרמים — זה היה תפקידן.", "לא נכון. הפסקה אינה מזכירה חלקים נעים בשפופרות; המהנדסים חיפשו תחליף ללא חלקים נעים.", "לא נכון. הבעיה הייתה הפוכה — השפופרות היו גדולות, לא קטנות מדי."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["These glass tubes worked, but they were bulky, fragile, and hot, and they burned out with frustrating regularity"]$q$::jsonb, $q$shabbat batch C, passage=transistor, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, why was William Shockley "frustrated"?$q$, $q$["His improved design was rejected by the managers of Bell Laboratories.", "He was denied a share of the Nobel Prize awarded in 1956.", "His company in California lost several employees to rival firms.", "He had not been part of the team that achieved the first success."]$q$::jsonb, 3, $q$["לא נכון. הפסקה מציינת שהוא תכנן גרסה משופרת, ואינה מזכירה שהיא נדחתה.", "לא נכון. הפסקה השנייה קובעת ששלושת המדענים חלקו את פרס נובל.", "לא נכון. עזיבת העובדים מוזכרת בפסקה האחרונה, ואינה קשורה לתסכול המתואר בפסקה השנייה.", "נכון. הפסקה השנייה אומרת שהוא היה מתוסכל משום שנותר מחוץ לפריצת הדרך של ברדין ובראטיין."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["frustrated at being left out of the breakthrough"]$q$::jsonb, $q$shabbat batch C, passage=transistor, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the third paragraph is to —$q$, $q$["describe the difficulties that vacuum tubes caused for early computer engineers.", "describe how Bardeen and Brattain built the first transistor from germanium.", "explain the transistor's advantages and how it led to the integrated circuit.", "explain how former employees of Shockley's company created Silicon Valley."]$q$::jsonb, 2, $q$["לא נכון. זהו תוכן הפסקה הראשונה — קשיי שפופרות הריק — ולא הפסקה השלישית.", "לא נכון. זהו תוכן הפסקה השנייה — בניית הטרנזיסטור הראשון — ולא הפסקה השלישית.", "נכון. הפסקה השלישית מפרטת את יתרונות הטרנזיסטור על פני השפופרת ומראה כיצד הוביל למעגל המשולב.", "לא נכון. זהו תוכן הפסקה הרביעית — עמק הסיליקון — ולא הפסקה השלישית."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=transistor, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["emphasize the vast and lasting influence of the invention.", "describe the Nobel Prize that the three physicists received in 1956.", "explain why germanium was eventually replaced by silicon in most devices.", "describe the portable radio that made the transistor famous in the 1950s."]$q$::jsonb, 0, $q$["נכון. הפסקה האחרונה מראה כיצד הטרנזיסטור הוליד את עמק הסיליקון ואת השבבים בני מיליארדי הטרנזיסטורים, ומסכמת את השפעתו הרחבה.", "לא נכון. פרס נובל מוזכר בפסקה השנייה, ולא בפסקה האחרונה.", "לא נכון. הקטע אינו מסביר מדוע הסיליקון החליף את הגרמניום.", "לא נכון. הרדיו הנייד מוזכר בפסקה השלישית, ולא בפסקה האחרונה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=transistor, q5$q$, 5, true);
  end if;
end $$;
do $$ declare v_pid uuid; begin

  if not exists (select 1 from reading_passages where title = $q$The Antikythera Mechanism$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Antikythera Mechanism$q$, $q$In 1901, sponge divers working off the small Greek island of Antikythera discovered the wreck of an ancient ship. Among the statues and pottery they recovered was a lump of corroded bronze that at first attracted little attention. Only later did scholars notice that it contained gears, a feature unknown in any other object from the ancient world. The ship is believed to have sunk during the first century BC, while carrying luxury goods from Greece toward Rome.

For most of the twentieth century, the purpose of the device remained a subject of debate. Its fragments were too fragile to take apart, and its inscriptions were largely hidden beneath layers of corrosion. The breakthrough came in the 2000s, when researchers used advanced X-ray imaging to look inside the metal without damaging it. The scans revealed at least thirty interlocking gears and thousands of tiny letters describing how the machine worked. It turned out to be an astronomical calculator that could display the positions of the sun and moon and predict eclipses decades in advance.

Nothing of comparable complexity is known to have existed for roughly a thousand years after the ship went down. The mechanism's precision suggests that it was not a unique experiment but the product of an established tradition of craftsmanship. Nevertheless, no other example of that tradition has ever been found, and no ancient text describes such a device in detail. Historians must therefore accept that a sophisticated technology could flourish, disappear, and leave behind almost no trace. The corroded lump from the seabed remains a reminder of how incomplete our picture of the ancient world may be.$q$, $q$history / technology$q$, 5, 270, true, $q$reading_shabbat_2026-09-05_C$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, all of the following are true EXCEPT —$q$, $q$["The fragments were too delicate to be taken apart for examination.", "Advanced imaging in the 2000s revealed the device's internal gears and inscriptions.", "The device was able to forecast eclipses many years ahead of time.", "Researchers disassembled the device in order to count its gears precisely."]$q$::jsonb, 3, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — השברים אכן היו שבירים מכדי לפרקם.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — הדימות בקרני רנטגן חשף את גלגלי השיניים והכתובות.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — המכשיר חזה ליקויים עשרות שנים מראש.", "נכון. זו הקביעה השגויה — הפסקה קובעת שהשברים היו שבירים מכדי לפרקם, והחוקרים הסתכלו לתוך המתכת דווקא בלי לפגוע בה."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Its fragments were too fragile to take apart"]$q$::jsonb, $q$shabbat batch C, passage=antikythera, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, what eventually drew scholars' attention to the bronze object?$q$, $q$["It was found alongside valuable statues and pottery from the same wreck.", "It carried an inscription naming the ship and its destination in Rome.", "It contained gears, unlike any other known object from antiquity.", "It was far larger and heavier than the other items the divers recovered."]$q$::jsonb, 2, $q$["לא נכון. הפסלים והכלים מוזכרים, אך הפסקה אומרת שהגוש דווקא לא משך תשומת לב בתחילה.", "לא נכון. הפסקה הראשונה אינה מזכירה כתובת המזהה את הספינה או יעדה.", "נכון. הפסקה מציינת שרק מאוחר יותר הבחינו החוקרים שהגוש מכיל גלגלי שיניים — תכונה שאינה מוכרת בשום חפץ אחר מהעולם העתיק.", "לא נכון. הפסקה אינה משווה את גודלו או משקלו של הגוש לפריטים אחרים."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Only later did scholars notice that it contained gears"]$q$::jsonb, $q$shabbat batch C, passage=antikythera, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["describe the imaging techniques that finally revealed the purpose of the device.", "reflect on what the device reveals about gaps in our knowledge of ancient technology.", "explain how sponge divers discovered the shipwreck in 1901.", "list the astronomical functions that the mechanism could perform."]$q$::jsonb, 1, $q$["לא נכון. זהו תוכן הפסקה השנייה — טכניקות הדימות — ולא הפסקה האחרונה.", "נכון. הפסקה האחרונה מסיקה שטכנולוגיה מתוחכמת יכולה להיעלם בלי להשאיר עקבות, ומסיימת בהערה על התמונה החלקית שיש לנו על העולם העתיק.", "לא נכון. זהו תוכן הפסקה הראשונה — גילוי הספינה — ולא הפסקה האחרונה.", "לא נכון. הפונקציות האסטרונומיות מפורטות בפסקה השנייה, ולא בפסקה האחרונה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=antikythera, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the statement that the mechanism "was not a unique experiment but the product of an established tradition of craftsmanship," what can be inferred?$q$, $q$["Similar devices were probably built in antiquity even though none of them survive.", "The device was almost certainly made by a single isolated inventor working alone.", "Many other examples of such machines have been recovered from other shipwrecks.", "The craftsmen who built it left detailed written descriptions of their methods."]$q$::jsonb, 0, $q$["נכון. אם המכשיר היה תוצר של מסורת מבוססת, סביר שנבנו מכשירים דומים — אף שהפסקה מציינת שאף אחד מהם לא נמצא.", "לא נכון. זה ההפך מהקביעה — 'מסורת מבוססת' שוללת ממציא בודד ומבודד.", "לא נכון. הפסקה קובעת במפורש שלא נמצאה שום דוגמה נוספת.", "לא נכון. הפסקה אומרת ששום טקסט עתיק אינו מתאר מכשיר כזה בפירוט."]$q$::jsonb, $q$inference$q$, $q$anchor$q$, $q$["was not a unique experiment but the product of an established tradition of craftsmanship"]$q$::jsonb, $q$shabbat batch C, passage=antikythera, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the third paragraph, the word "flourish" is closest in meaning to —$q$, $q$["Sink to the bottom of the sea", "Develop successfully", "Be recorded carefully in written documents", "Remain hidden from view for a long period"]$q$::jsonb, 1, $q$["לא נכון. המילה אינה קשורה לטביעה; הספינה טבעה, אך המילה מתארת את הטכנולוגיה.", "נכון. 'flourish' פירושו לשגשג, להתפתח בהצלחה — הפסקה אומרת שטכנולוגיה מתוחכמת יכולה לשגשג, להיעלם ולא להשאיר עקבות.", "לא נכון. הפסקה אומרת דווקא שאף טקסט אינו מתאר את המכשיר.", "לא נכון. המילה מתארת שלב של פריחה, לא של הסתתרות."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["a sophisticated technology could flourish, disappear, and leave behind almost no trace"]$q$::jsonb, $q$shabbat batch C, passage=antikythera, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$How Refrigeration Changed What People Eat$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$How Refrigeration Changed What People Eat$q$, $q$For most of human history, keeping food fresh was a constant struggle against heat and time. People preserved meat and fish by salting, smoking, or drying them, and they turned milk into cheese so that it would last. Fresh fruit and vegetables were available only in season and only near the places where they grew. In the nineteenth century, wealthy households could buy blocks of natural ice cut from frozen lakes and stored in insulated warehouses. However, ice was expensive, melted quickly, and depended entirely on cold winters.

Mechanical refrigeration changed this situation completely when, in the 1870s, engineers such as the German scientist Carl von Linde built reliable machines that produced cold by compressing and expanding gases. Refrigerated railway cars soon allowed meat packed in Chicago to reach dinner tables on the East Coast. By the 1880s, ships equipped with cooling systems were carrying frozen meat from Australia and Argentina to Europe. Household refrigerators became affordable in the 1930s, and frozen vegetables, pioneered by Clarence Birdseye, appeared in shops around the same time.

The effects of these developments on everyday diet were profound and far-reaching. Fresh milk, meat, and produce became available year-round, and city dwellers could eat foods that had once been reserved for farmers. Diets grew more varied and, in many cases, healthier, while the heavy use of salt as a preservative declined. Yet refrigeration also lengthened the distance between people and the sources of their food. A tomato in a winter supermarket may have traveled thousands of kilometers, and few shoppers know where it grew. The cold chain that makes such abundance possible has become so ordinary that most people never notice it at all.$q$, $q$technology / society$q$, 4, 279, true, $q$reading_shabbat_2026-09-05_C$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Carl von Linde built the first reliable machine that produced cold by compressing gases.", "Natural ice was too expensive and unreliable to preserve food for ordinary families.", "Refrigeration transformed how food is stored, transported, and eaten, with mixed consequences.", "Shoppers today rarely know where the fruit and vegetables in their supermarket were grown."]$q$::jsonb, 2, $q$["לא נכון. זו קביעה נכונה מהפסקה השנייה, אבל היא פרט אחד בלבד ולא הרעיון המרכזי.", "לא נכון. זו קביעה נכונה מהפסקה הראשונה, אבל היא מתארת את המצב שלפני הקירור ולא את הקטע כולו.", "נכון. הקטע עוקב אחרי המעבר משיטות שימור מסורתיות לקירור מכני, ומראה כיצד שינה את התזונה — לטובה וגם במחיר מסוים.", "לא נכון. זו קביעה נכונה מהפסקה השלישית, אבל היא דוגמה אחת בלבד ולא הרעיון המרכזי."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch C, passage=refrigeration, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, what was a disadvantage of natural ice?$q$, $q$["It could be stored only in the warehouses of the wealthiest households.", "It made meat and fish taste of salt and smoke.", "It was available only near the frozen lakes where it was cut.", "It cost a great deal, did not last long, and relied on the weather."]$q$::jsonb, 3, $q$["לא נכון. הפסקה אומרת שמשקי בית עשירים קנו קרח, לא שהוא נשמר רק במחסניהם.", "לא נכון. המלח והעשן הם שיטות שימור אחרות שהפסקה מזכירה, ואינם קשורים לקרח.", "לא נכון. הפסקה מציינת שהקרח נשמר במחסנים מבודדים ונמכר, לא שהיה זמין רק ליד האגמים.", "נכון. הפסקה קובעת שהקרח היה יקר, נמס במהירות ותלוי לחלוטין בחורפים קרים."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["ice was expensive, melted quickly, and depended entirely on cold winters"]$q$::jsonb, $q$shabbat batch C, passage=refrigeration, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["trace the development and spread of mechanical cooling technology.", "describe the traditional methods people used to preserve food before refrigeration.", "explain how refrigeration changed the diet of city dwellers.", "argue that refrigeration has separated people from the sources of their food."]$q$::jsonb, 0, $q$["נכון. הפסקה השנייה מתארת את המצאת הקירור המכני ואת התפשטותו — קרונות רכבת, ספינות ומקררים ביתיים.", "לא נכון. זהו תוכן הפסקה הראשונה — שיטות השימור המסורתיות — ולא הפסקה השנייה.", "לא נכון. זהו תוכן הפסקה השלישית — ההשפעה על התזונה — ולא הפסקה השנייה.", "לא נכון. זהו רעיון מהפסקה השלישית, ולא מטרת הפסקה השנייה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=refrigeration, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the third paragraph that —$q$, $q$["the author believes people should return to preserving food with salt.", "the author regards refrigeration as having both benefits and drawbacks.", "the author thinks most shoppers deliberately ignore where their food comes from.", "the author considers the cold chain to be the most important invention in history."]$q$::jsonb, 1, $q$["לא נכון. הפסקה מציינת שהירידה בשימוש במלח הייתה חלק מתזונה בריאה יותר, ואינה ממליצה לחזור אליו.", "נכון. הפסקה מונה יתרונות — מגוון ובריאות — ואז אומרת 'Yet' ומצביעה על המרחק שנוצר בין אנשים למקורות מזונם.", "לא נכון. הפסקה אומרת שמעטים יודעים היכן גדל המזון, לא שהם מתעלמים מכך בכוונה.", "לא נכון. הפסקה אומרת ששרשרת הקור הפכה שגרתית עד שאיש אינו מבחין בה, ואינה מדרגת אותה כהמצאה החשובה ביותר."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=refrigeration, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the sentence "few shoppers know where it grew," the word "it" refers to —$q$, $q$["the winter supermarket", "the abundance of food", "the distance traveled", "the tomato"]$q$::jsonb, 3, $q$["לא נכון. הסופרמרקט הוא המקום שבו העגבנייה נמכרת, לא הדבר שגדל.", "לא נכון. השפע מוזכר רק במשפט הבא.", "לא נכון. מרחק אינו דבר שגדל.", "נכון. הנושא של המשפט הוא העגבנייה, שאולי נסעה אלפי קילומטרים, ו'it' מתייחס אליה."]$q$::jsonb, $q$reference_word$q$, $q$anchor$q$, $q$["few shoppers know where it grew"]$q$::jsonb, $q$shabbat batch C, passage=refrigeration, q5$q$, 5, true);
