  if not exists (select 1 from reading_passages where title = $q$Percy Spencer and the Microwave Oven$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Percy Spencer and the Microwave Oven$q$, $q$Percy Spencer never finished grammar school, yet he became one of the most important engineers of his generation. Born in Maine in 1894, he lost his father as a baby and began working full time at the age of twelve. He taught himself electronics while serving in the navy, reading textbooks late at night on board ship. By the 1940s, Spencer was a senior engineer at the Raytheon company in Massachusetts, where he worked on radar equipment.

One day in 1945, Spencer was standing near a magnetron, the powerful tube that generates the radio waves used in radar. He noticed that a candy bar in his pocket had melted, even though he had not felt any heat. Curious, he placed some popcorn kernels near the tube, and within moments they began to pop across the laboratory. The next morning he tried an egg, which exploded in the face of a colleague who leaned in too closely. Spencer realized that the invisible waves were heating food from the inside, and Raytheon filed a patent that same year.

The first commercial microwave oven went on sale in 1947 under the name Radarange. It stood nearly two meters tall, weighed more than 300 kilograms, and cost about 5,000 dollars, a huge sum at the time. Only restaurants, ships, and railway companies could afford such a machine. However, the technology improved and the price fell, and a compact countertop model reached American kitchens in 1967. Within a few decades, the accidental discovery of a self-taught engineer had become a standard appliance in homes around the world.$q$, $q$technology$q$, 3, 256, true, $q$reading_shabbat_2026-09-05_C$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, what happened to the "candy bar in his pocket"?$q$, $q$["It melted, even though Spencer had not sensed any warmth coming from the tube.", "It exploded and struck a colleague who was standing nearby.", "It began to pop like popcorn when he placed it near the tube.", "It was taken away by Raytheon to be examined for the patent application."]$q$::jsonb, 0, $q$["נכון. הפסקה מספרת שהחטיף נמס אף על פי שספנסר לא הרגיש שום חום.", "לא נכון. הביצה היא שהתפוצצה על עמיתו, לא החטיף.", "לא נכון. גרגירי התירס הם שהתפוצצו, לא החטיף.", "לא נכון. הפסקה אינה מזכירה שהחטיף נלקח לבדיקה."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["a candy bar in his pocket had melted, even though he had not felt any heat"]$q$::jsonb, $q$shabbat batch C, passage=microwave, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, all of the following are true EXCEPT —$q$, $q$["Spencer started working full time when he was still a child.", "Spencer studied engineering at a university before joining the navy.", "Spencer learned about electronics on his own while in the navy.", "Spencer was working on radar equipment at Raytheon in the 1940s."]$q$::jsonb, 1, $q$["לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — הוא החל לעבוד במשרה מלאה בגיל שתים עשרה.", "נכון. זו הקביעה השגויה — הפסקה אומרת שספנסר לא סיים אפילו בית ספר יסודי ולימד את עצמו אלקטרוניקה, ואינה מזכירה לימודים באוניברסיטה.", "לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — הוא קרא ספרי לימוד בלילות על סיפון הספינה.", "לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — בשנות הארבעים עבד על ציוד מכ\"ם ברייתאון."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Percy Spencer never finished grammar school"]$q$::jsonb, $q$shabbat batch C, passage=microwave, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["describe the experiments with popcorn and eggs that led to the patent.", "explain how a magnetron produces the radio waves used in radar.", "describe how the microwave oven developed from a costly machine into an everyday appliance.", "describe Spencer's early life and the way he educated himself."]$q$::jsonb, 2, $q$["לא נכון. זהו תוכן הפסקה השנייה — הניסויים בפופקורן ובביצה — ולא הפסקה האחרונה.", "לא נכון. המגנטרון מוזכר בפסקה השנייה, והקטע כלל אינו מסביר כיצד הוא פועל.", "נכון. הפסקה האחרונה מתארת את התנור הראשון הגדול והיקר, ואת הדרך שבה הפך למכשיר ביתי זול ונפוץ.", "לא נכון. זהו תוכן הפסקה הראשונה — ילדותו והשכלתו העצמית של ספנסר — ולא הפסקה האחרונה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=microwave, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the third paragraph that —$q$, $q$["the Radarange was an immediate commercial failure that was quickly withdrawn.", "restaurants stopped using microwave ovens after the countertop model appeared.", "Raytheon lost its patent rights before the countertop model was introduced.", "early microwave ovens were impractical for ordinary families."]$q$::jsonb, 3, $q$["לא נכון. הפסקה אומרת שרק מסעדות, ספינות וחברות רכבת יכלו להרשות לעצמן את המכשיר — לא שהוא נכשל או הוסר מהשוק.", "לא נכון. הפסקה אינה אומרת דבר על הפסקת השימוש במסעדות.", "לא נכון. הפסקה אינה מזכירה אובדן זכויות פטנט.", "נכון. מכשיר בגובה שני מטרים, במשקל 300 קילוגרם ובמחיר עצום, שרק עסקים יכלו לרכוש, לא היה מעשי למשפחה רגילה."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch C, passage=microwave, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the third paragraph, the word "compact" most nearly means —$q$, $q$["Extremely expensive", "Powerful enough to be used in a restaurant", "Small", "Made entirely of metal parts"]$q$::jsonb, 2, $q$["לא נכון. הפסקה אומרת שהמחיר ירד, ולכן המילה אינה מתארת יוקר.", "לא נכון. המילה אינה מתארת עוצמה.", "נכון. 'compact' פירושו קטן וחסכוני במקום — בניגוד למכשיר הראשון בגובה שני מטרים.", "לא נכון. המילה אינה מתארת חומר."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["a compact countertop model reached American kitchens in 1967"]$q$::jsonb, $q$shabbat batch C, passage=microwave, q5$q$, 5, true);
