  if not exists (select 1 from reading_passages where title = $q$Elisha Otis, the Safety Elevator, and the Skyscraper$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Elisha Otis, the Safety Elevator, and the Skyscraper$q$, $q$Lifting platforms powered by ropes and pulleys had existed for centuries before the modern elevator appeared. They were used mainly to raise goods in warehouses and factories, since few people trusted them enough to ride inside. The reason was simple: if the rope broke, the platform fell to the bottom of the shaft. Accidents were common, and passenger elevators were widely regarded as too dangerous to be practical.

Elisha Otis, a mechanic working at a bed factory in New York, solved the problem in 1852. He attached a spring to the top of the platform that, if the rope lost tension, would push toothed bars into the guide rails and hold the car in place. Otis demonstrated his invention dramatically at an exhibition in New York in 1854. Standing on a raised platform before a crowd, he ordered an assistant to cut the only rope with an axe. The platform dropped a few centimeters and then stopped, and Otis calmly announced that all was safe.

The first passenger elevator with the safety device was installed in a New York department store in 1857. Otis himself died only a few years later, but his sons expanded the business into a major company. Meanwhile, the introduction of steel frames in the 1880s allowed architects to design buildings far taller than before. Without a safe and reliable elevator, however, such towers would have been useless, since nobody could climb twenty flights of stairs to reach an office.

The safety elevator therefore did more than prevent accidents; it changed the shape of cities. Before its arrival, the upper floors of a building were the least desirable, because reaching them required exhausting effort. Afterward, the highest floors became the most prestigious, offering quiet, light, and views far above the street.$q$, $q$technology / history$q$, 4, 292, true, $q$reading_shabbat_2026-09-05_C$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Elisha Otis cut a rope in front of a crowd in 1854 to prove that his platform would not fall.", "Steel frames introduced in the 1880s allowed architects to build much taller buildings.", "The upper floors of buildings were once considered the least desirable places to work.", "A device that made elevators safe helped make tall buildings possible and reshaped cities."]$q$::jsonb, 3, $q$["לא נכון. זו קביעה נכונה מהפסקה השנייה, אבל היא אירוע אחד בלבד ולא הרעיון המרכזי של הקטע.", "לא נכון. זו קביעה נכונה מהפסקה השלישית, אבל היא פרט אחד ולא הרעיון המרכזי.", "לא נכון. זו קביעה נכונה מהפסקה הרביעית, אבל היא פרט צר ולא הרעיון המרכזי.", "נכון. הקטע כולו מראה כיצד המעצור של אוטיס הפך את המעליות לבטוחות, אפשר את גורדי השחקים ושינה את פני הערים."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch C, passage=otis-elevator, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, how did Otis's safety device work?$q$, $q$["A spring forced bars into the rails whenever the rope went slack.", "A second rope automatically took over if the first rope snapped.", "An assistant standing below the platform pulled a brake lever by hand.", "The platform was suspended from several ropes instead of only one."]$q$::jsonb, 0, $q$["נכון. הפסקה מתארת קפיץ שבמקרה שהחבל מאבד מתח דוחף מוטות משוננים לתוך המסילות ומחזיק את התא במקומו.", "לא נכון. הפסקה אינה מזכירה חבל שני; להפך, בהדגמה נחתך החבל היחיד.", "לא נכון. העוזר בהדגמה חתך את החבל, לא הפעיל בלם.", "לא נכון. הפסקה מציינת במפורש שהיה חבל אחד בלבד בהדגמה."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["He attached a spring to the top of the platform that, if the rope lost tension, would push toothed bars into the guide rails and hold the car in place"]$q$::jsonb, $q$shabbat batch C, passage=otis-elevator, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, what happened when the assistant cut "the only rope with an axe"?$q$, $q$["The platform crashed to the ground, but Otis escaped without injury.", "The platform fell only slightly before the mechanism stopped it.", "The crowd panicked and the exhibition was closed by the authorities.", "The platform remained completely motionless, without moving at all."]$q$::jsonb, 1, $q$["לא נכון. הפסקה אומרת שהמשטח ירד כמה סנטימטרים בלבד ונעצר.", "נכון. הפסקה מספרת שהמשטח צנח כמה סנטימטרים ואז נעצר, ואוטיס הכריז בשלווה שהכול בטוח.", "לא נכון. הפסקה אינה מזכירה בהלה או סגירת התערוכה.", "לא נכון. הפסקה מציינת שהמשטח אכן ירד מעט לפני שנעצר."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["The platform dropped a few centimeters and then stopped"]$q$::jsonb, $q$shabbat batch C, passage=otis-elevator, q3$q$, 3, true);
