    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the passage, what can be inferred about urban heat islands?$q$, $q$["They are partly the result of choices about how cities are built.", "They occur only in cities that have very tall buildings.", "They were first noticed in the twentieth century.", "They can be eliminated completely by planting more trees."]$q$::jsonb, 0, $q$["נכון. הקטע מייחס את התופעה לחומרי בנייה כהים, לגובה הבניינים ולמיעוט צמחייה, ומראה שאמצעים תכנוניים כמו גגות ירוקים מפחיתים אותה — כלומר אופן בניית העיר משפיע עליה.", "לא נכון. בניינים גבוהים הם רק אחד מכמה גורמים שהפסקה השנייה מונה.", "לא נכון. הפסקה הראשונה מציינת שלוק הווארד תיאר את התופעה כבר בתחילת המאה התשע-עשרה.", "לא נכון. הקטע אומר שעצים מורידים את הטמפרטורה המקומית, לא שהם מבטלים את התופעה לחלוטין."]$q$::jsonb, $q$inference$q$, $q$text$q$, null, $q$shabbat batch D, passage=heat-islands, q5$q$, 5, true);
