  if not exists (select 1 from reading_passages where title = $q$The Eurasian Beaver Returns to Britain$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Eurasian Beaver Returns to Britain$q$, $q$The Eurasian beaver once lived in rivers across Britain, but by the sixteenth century it had been hunted to extinction there. People killed beavers for their thick fur, for their meat, and for a strong-smelling substance that was used in medicine and perfume. For roughly four hundred years, no wild beavers swam in British rivers, and most people forgot the animal had ever lived there.

That began to change in 2009, when a small number of beavers from Norway were released in a forest in western Scotland. This was the first official trial of its kind in Britain, and scientists watched the animals closely for five years. Around the same time, beavers of unknown origin appeared on the River Otter in Devon, in the southwest of England. Rather than remove them, the authorities allowed a second trial to take place there.

The results of the trials surprised many people. Beavers build dams from branches and mud, and behind these dams the water spreads out to form ponds and wetlands. The ponds slow the flow of rivers after heavy rain, which reduced flooding in villages downstream. They also trapped sediment and pollutants, so the water leaving the area was cleaner than the water entering it. Frogs, fish, insects, and birds all became more common around the new beaver ponds.

Not everyone welcomed the returning beavers, however. Some farmers complained that the dams flooded their fields, and others lost trees that the animals had cut down. Managing these conflicts is now a normal part of living with beavers again. In 2016 Scotland formally recognized the beaver as a native species, and England gave it legal protection in 2022. An animal that vanished four centuries ago is once more a permanent resident of Britain's rivers.$q$, $q$environment / ecology$q$, 3, 289, true, $q$reading_shabbat_2026-09-05_D$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, beavers were hunted for all of the following EXCEPT —$q$, $q$["their meat.", "their thick fur.", "their teeth.", "a substance used in perfume and medicine."]$q$::jsonb, 2, $q$["לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — הבשר מוזכר כאחת הסיבות לציד.", "לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — הפרווה העבה מוזכרת כסיבה לציד.", "נכון. זו הקביעה שאינה מופיעה — הפסקה אינה מזכירה שיניים כלל.", "לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — החומר החריף ששימש לרפואה ולבשמים מוזכר במפורש."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch D, passage=beavers, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["explain why beavers disappeared from Britain in the sixteenth century.", "describe the trials that brought beavers back to Scotland and England.", "describe the benefits that beaver dams bring to rivers and wildlife.", "present the objections of farmers to the return of the beavers."]$q$::jsonb, 1, $q$["לא נכון. היעלמות הבונים והסיבות לציד מתוארות בפסקה הראשונה.", "נכון. הפסקה השנייה מתארת את הניסוי הרשמי בסקוטלנד ב-2009 ואת הניסוי השני בנהר אוטר שבאנגליה.", "לא נכון. יתרונות הסכרים מתוארים בפסקה השלישית.", "לא נכון. תלונות החקלאים מופיעות בפסקה הרביעית."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch D, passage=beavers, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the third paragraph is to —$q$, $q$["explain how the authorities decided to allow a second trial in Devon.", "describe the damage that beavers caused to farmers' fields and trees.", "list the laws that now protect beavers in Scotland and England.", "describe the positive effects that the beavers had on rivers, water quality, and wildlife."]$q$::jsonb, 3, $q$["לא נכון. ההחלטה על הניסוי השני מוזכרת בסוף הפסקה השנייה.", "לא נכון. הנזק לשדות ולעצים מתואר בפסקה הרביעית.", "לא נכון. ההכרה החוקית בבונים מוזכרת בפסקה הרביעית.", "נכון. הפסקה השלישית מתארת כיצד סכרי הבונים הפחיתו שיטפונות, ניקו את המים והגדילו את מגוון בעלי החיים."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch D, passage=beavers, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, how did the authorities respond when beavers "of unknown origin" appeared on the River Otter?$q$, $q$["They let them stay as part of a second trial.", "They captured the animals and returned them to Norway.", "They moved the animals to the forest in western Scotland.", "They removed the animals because farmers had complained about flooding."]$q$::jsonb, 0, $q$["נכון. הפסקה השנייה כותבת שבמקום להרחיק את הבונים, הרשויות אפשרו ניסוי שני במקום.", "לא נכון. הבונים מנורווגיה שוחררו בסקוטלנד; הפסקה אינה מזכירה החזרה של בונים לנורווגיה.", "לא נכון. הבונים בדבון נשארו בנהר אוטר ולא הועברו לסקוטלנד.", "לא נכון. הפסקה אומרת במפורש שהרשויות בחרו שלא להרחיק אותם."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["beavers of unknown origin appeared on the River Otter"]$q$::jsonb, $q$shabbat batch D, passage=beavers, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["How Beaver Dams Reduce Flooding in English Villages", "Why British Farmers Oppose the Return of the Beaver", "The Hunting of Beavers in Medieval Britain", "The Beaver's Return to Britain After Four Centuries"]$q$::jsonb, 3, $q$["לא נכון. הפחתת השיטפונות היא פרט אחד מהפסקה השלישית, לא נושא הקטע כולו.", "לא נכון. התנגדות החקלאים מוזכרת בקצרה בפסקה הרביעית בלבד.", "לא נכון. הציד מתואר רק בפסקה הראשונה כרקע להיעלמות.", "נכון. הקטע כולו עוסק בהיעלמות הבונה מבריטניה ובשובו לאחר כארבע מאות שנה, על יתרונותיו והקשיים שבו."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch D, passage=beavers, q5$q$, 5, true);
  end if;
end $$;
do $$ declare v_pid uuid; begin

  if not exists (select 1 from reading_passages where title = $q$Tulip Mania: Legend and Reality$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Tulip Mania: Legend and Reality$q$, $q$In the 1630s the Dutch Republic was the wealthiest trading nation in Europe, and its merchants had money to spend on luxuries. Tulips, introduced from the Ottoman Empire in the previous century, became a fashionable status symbol among the prosperous. The most prized bulbs produced striped or flamed petals, a pattern that was actually caused by a virus. Because such bulbs were rare and slow to reproduce, their prices rose steadily during the early years of the decade.

In late 1636 and early 1637, trading in tulip contracts reached a feverish pitch in taverns across Holland. Buyers were not purchasing flowers but promises of bulbs still in the ground, and contracts changed hands many times before spring. According to popular accounts, a single bulb of the rarest variety could be exchanged for a fine house on an Amsterdam canal. In February 1637 buyers suddenly stopped appearing at auctions, and prices collapsed within days. The episode has been described ever since as the first speculative bubble in economic history.

However, modern historians argue that the legend is far more dramatic than the events themselves. The famous stories of ruined families and a paralyzed economy come mostly from moralizing pamphlets written after the crash. Careful research in archives suggests that only a small number of wealthy traders were involved, and that few of them were bankrupted. The Dutch economy showed no visible damage, and courts often refused to enforce the unpaid contracts at all. Tulip mania therefore survives less as an economic catastrophe than as a cautionary tale that later writers found too useful to abandon.$q$, $q$economics / history$q$, 5, 261, true, $q$reading_shabbat_2026-09-05_F$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Tulip prices rose because the most beautiful bulbs were infected by a virus that made them rare.", "Dutch courts refused to enforce tulip contracts, which protected buyers from financial ruin.", "The famous tulip bubble was a real but limited episode that later storytelling greatly exaggerated into a catastrophe.", "The Dutch Republic of the 1630s was the richest trading nation in Europe and could afford luxury goods."]$q$::jsonb, 2, $q$["לא נכון. זהו פרט מהפסקה הראשונה בלבד, ולא הרעיון המרכזי של הקטע כולו.", "לא נכון. זהו פרט מהפסקה השלישית, ולא הרעיון המרכזי של הקטע כולו.", "נכון. הקטע מתאר את הבועה ואז מראה שההיסטוריונים רואים בה אירוע מצומצם שהאגדה ניפחה — זה הרעיון המרכזי.", "לא נכון. זהו רקע מהפסקה הראשונה, ולא הרעיון המרכזי של הקטע כולו."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch F, passage=tulips, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, all of the following are true EXCEPT —$q$, $q$["Buyers examined the flowers carefully before agreeing on a price.", "Contracts were often resold several times before the bulbs were dug up.", "Prices collapsed within days after buyers stopped coming to auctions.", "Popular accounts claim that one rare bulb could be worth a canal house."]$q$::jsonb, 0, $q$["נכון. זו הקביעה השגויה — הפסקה כותבת שהקונים לא רכשו פרחים אלא הבטחות לבצלים שעדיין באדמה, כך שלא יכלו לבחון אותם.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — החוזים החליפו ידיים פעמים רבות לפני האביב.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — המחירים קרסו בתוך ימים בפברואר 1637.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — לפי הסיפורים העממיים בצל נדיר הוחלף בבית על תעלה."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Buyers were not purchasing flowers but promises of bulbs still in the ground"]$q$::jsonb, $q$shabbat batch F, passage=tulips, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the third paragraph is to —$q$, $q$["explain why the striped petals of the rarest tulips were so highly valued by buyers.", "describe the frantic trading in tulip contracts that took place in Dutch taverns.", "narrate the sudden collapse of prices at the tulip auctions of February 1637.", "challenge the traditional story of the bubble by presenting what historians have found."]$q$::jsonb, 3, $q$["לא נכון. זהו תוכן הפסקה הראשונה, ולא מטרת הפסקה השלישית.", "לא נכון. זהו תוכן הפסקה השנייה, ולא מטרת הפסקה השלישית.", "לא נכון. זהו תוכן הפסקה השנייה, ולא מטרת הפסקה השלישית.", "נכון. הפסקה השלישית פותחת ב-However ומציגה את ממצאי ההיסטוריונים המערערים על האגדה המפורסמת."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch F, passage=tulips, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the second paragraph, the word "feverish" is closest in meaning to —$q$, $q$["cautious and slow", "wildly excited", "strictly regulated", "unusually quiet"]$q$::jsonb, 1, $q$["לא נכון. המסחר מתואר כסוער ומהיר, ההפך מזהיר ואיטי.", "נכון. 'feverish' פירושו נרגש ומטורף, כמו חום גבוה — המסחר הגיע לשיא של התלהבות פרועה.", "לא נכון. הפסקה מתארת מסחר בבתי מרזח, ללא כל פיקוח.", "לא נכון. המילה מתארת פעילות סוערת, לא שקט."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["reached a feverish pitch in taverns across Holland"]$q$::jsonb, $q$shabbat batch F, passage=tulips, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the statement that courts "often refused to enforce the unpaid contracts," what can be inferred?$q$, $q$["The Dutch government banned all trading in tulips after the crash of 1637.", "Most traders who lost money were later compensated by the courts.", "The contracts had been written in a foreign language that judges could not read.", "Many buyers who owed money after the crash never actually had to pay it."]$q$::jsonb, 3, $q$["לא נכון. הקטע אינו מזכיר איסור ממשלתי על מסחר בצבעונים.", "לא נכון. הקטע מציין שבתי המשפט סירבו לאכוף חוזים, לא שפיצו מפסידים.", "לא נכון. הקטע אינו מזכיר דבר על שפת החוזים.", "נכון. אם בתי המשפט סירבו לאכוף את החוזים שלא שולמו, נובע מכך שקונים רבים שהתחייבו לשלם לא נאלצו לעשות זאת בפועל."]$q$::jsonb, $q$inference$q$, $q$anchor$q$, $q$["courts often refused to enforce the unpaid contracts at all"]$q$::jsonb, $q$shabbat batch F, passage=tulips, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$The Tragedy of the Commons and Its Critics$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Tragedy of the Commons and Its Critics$q$, $q$In 1968 the ecologist Garrett Hardin published an essay in the journal Science that became one of the most cited papers in the social sciences. He asked readers to imagine a pasture open to all, on which each herder may graze as many animals as he wishes. Every additional animal brings its owner a full benefit, while the cost of overgrazing is shared among all the users. Hardin argued that rational individuals will therefore keep adding animals until the shared pasture is destroyed. He called this outcome the tragedy of the commons.

Hardin saw the same logic at work in overfishing, pollution, and population growth. In his view, freedom in a commons brings ruin to all, and only two remedies exist. Either the resource must be privatized, so that a single owner bears the full cost of abuse, or the state must regulate its use by force. The essay influenced a generation of policy makers who favored private property or central control.

The political scientist Elinor Ostrom challenged this framework by studying how real communities manage shared resources. She examined Swiss alpine meadows, Japanese forests, Spanish irrigation systems, and fisheries in many countries. In case after case, she found that users had devised their own rules, monitored one another, and punished violators without any outside authority. These arrangements had often survived for centuries, precisely where Hardin's theory predicted collapse.

Ostrom did not claim that cooperation always succeeds; instead, she identified the conditions under which it tends to work. Clear boundaries, rules adapted to local circumstances, and graduated sanctions all mattered, as did the users' ability to change the rules. In 2009 she became the first woman to receive the Nobel Memorial Prize in Economic Sciences. Her work suggests that the choice between the market and the state is a false one, because communities themselves may form a third option.$q$, $q$economics$q$, 6, 307, true, $q$reading_shabbat_2026-09-05_F$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Garrett Hardin's 1968 essay became one of the most frequently cited papers in the social sciences.", "Hardin predicted that shared resources are doomed, but Ostrom showed that communities can manage them successfully.", "Elinor Ostrom became the first woman to win the Nobel Memorial Prize in Economic Sciences in 2009.", "Overfishing, pollution, and population growth all follow the same destructive logic as the shared pasture."]$q$::jsonb, 1, $q$["לא נכון. זהו פרט מהפסקה הראשונה, ולא הרעיון המרכזי של הקטע.", "נכון. הקטע מציג את טענת הרדין ואת תגובתה של אוסטרום, שהראתה שקהילות מסוגלות לנהל משאבים משותפים — זה המבנה והרעיון המרכזי.", "לא נכון. זהו פרט מהפסקה האחרונה, ולא הרעיון המרכזי של הקטע.", "לא נכון. זהו פרט מהפסקה השנייה שמייצג רק את עמדת הרדין, ולא את הקטע כולו."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch F, passage=commons, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, which two solutions did Hardin believe could prevent the destruction of a commons?$q$, $q$["Educating users about the long-term consequences of overgrazing, or reducing the number of users.", "Allowing communities to write their own rules, or appointing local monitors to enforce them.", "Encouraging population control among herders, or banning the grazing of animals entirely.", "Transferring the resource to a single private owner, or having the state impose regulations."]$q$::jsonb, 3, $q$["לא נכון. הפסקה השנייה אינה מזכירה חינוך או הפחתת מספר המשתמשים.", "לא נכון. זהו הפתרון שאוסטרום גילתה בפסקה השלישית, לא זה שהרדין הציע.", "לא נכון. הפסקה מזכירה גידול אוכלוסייה כדוגמה לבעיה, לא כפתרון, ואינה מזכירה איסור על מרעה.", "נכון. הפסקה השנייה מציגה בדיוק שתי תרופות לפי הרדין: הפרטה של המשאב או פיקוח מדינתי בכוח."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Either the resource must be privatized, so that a single owner bears the full cost of abuse, or the state must regulate its use by force"]$q$::jsonb, $q$shabbat batch F, passage=commons, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the third paragraph is to —$q$, $q$["present real-world evidence that contradicts Hardin's prediction.", "explain the logic behind the image of the shared pasture.", "list the conditions under which cooperation is most likely to succeed.", "describe the two remedies that Hardin proposed for shared resources."]$q$::jsonb, 0, $q$["נכון. הפסקה השלישית מביאה מקרים אמיתיים — אחו בשווייץ, יערות ביפן, השקיה בספרד — שבהם קהילות ניהלו משאבים בהצלחה, בניגוד לתחזית של הרדין.", "לא נכון. זהו תוכן הפסקה הראשונה, ולא מטרת הפסקה השלישית.", "לא נכון. זהו תוכן הפסקה הרביעית, ולא מטרת הפסקה השלישית.", "לא נכון. זהו תוכן הפסקה השנייה, ולא מטרת הפסקה השלישית."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch F, passage=commons, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
