  if not exists (select 1 from reading_passages where title = $q$Microfinance and the Grameen Bank$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Microfinance and the Grameen Bank$q$, $q$In 1976 Muhammad Yunus, an economics professor in Bangladesh, visited a village near his university and met women who made bamboo stools. Because they could not afford the raw materials, they borrowed from local moneylenders at rates that swallowed almost all of their profit. Yunus found that a total of twenty-seven dollars would free a group of forty-two villagers from this cycle, and he lent them the money himself. The experience convinced him that the poor were excluded from banking not because they were unreliable but because they lacked collateral.

Out of this experiment grew the Grameen Bank, which was formally established in 1983. Instead of demanding property as security, the bank lent small sums to groups of borrowers, usually women, who took responsibility for one another's repayment. Social pressure within the group replaced the legal guarantees that conventional banks required. The bank reported repayment rates far higher than those of ordinary commercial lenders, and it expanded into thousands of villages. In 2006 Yunus and the bank shared the Nobel Peace Prize for their efforts to create economic development from below.

Microfinance was soon copied around the world, and for a time it was celebrated as a cure for poverty. Yet later studies found more modest effects than the early enthusiasm suggested. Careful evaluations showed that small loans helped some households start businesses, but they rarely lifted whole communities out of poverty. In some countries, aggressive lenders charged high interest and pushed borrowers into debt. Most economists now regard microcredit as a useful tool rather than a miracle, one that works best when combined with savings, insurance, and other services.$q$, $q$economics$q$, 5, 267, true, $q$reading_shabbat_2026-09-05_F$q$)
      returning id into v_pid;
