    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, what did "social pressure within the group" take the place of?$q$, $q$["The legal guarantees demanded by ordinary banks.", "The high interest charged by village moneylenders.", "The savings and insurance services offered later.", "The personal loans that Yunus made in 1976."]$q$::jsonb, 0, $q$["נכון. הפסקה השנייה כותבת שלחץ חברתי בתוך הקבוצה החליף את הערבויות המשפטיות שבנקים רגילים דרשו.", "לא נכון. הריבית הגבוהה של המלווים מוזכרת בפסקה הראשונה כבעיה, לא כדבר שהוחלף בלחץ חברתי.", "לא נכון. חיסכון וביטוח מוזכרים בפסקה השלישית כשירותים משלימים, לא כדבר שהוחלף.", "לא נכון. ההלוואה האישית של יונוס הייתה ראשית הסיפור, לא מה שהלחץ החברתי החליף."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["Social pressure within the group replaced the legal guarantees that conventional banks required"]$q$::jsonb, $q$shabbat batch F, passage=grameen, q5$q$, 5, true);
