    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, what did Henry Ford do in the 1920s?$q$, $q$["He introduced a four-day week in his factories as an experiment.", "He shortened the working week in his factories without reducing wages.", "He raised productivity in his factories by lengthening the working day.", "He persuaded the government to pass a law limiting the working week."]$q$::jsonb, 1, $q$["לא נכון. פורד קיצר את השבוע משישה ימים לחמישה, לא לארבעה.", "נכון. הפסקה הראשונה כותבת שפורד הפחית את שבוע העבודה משישה ימים לחמישה בלי לקצץ בשכר.", "לא נכון. הפסקה מתארת קיצור של שבוע העבודה, לא הארכה של יום העבודה.", "לא נכון. הפסקה אינה מזכירה חקיקה; מעסיקים אחרים הלכו בעקבותיו בהדרגה."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Henry Ford reduced the working week in his factories from six days to five without cutting pay"]$q$::jsonb, $q$shabbat batch F, passage=fourday, q2$q$, 2, true);
