      values (v_pid, $q$In the third paragraph, the word "squeezed" is closest in meaning to —$q$, $q$["compressed", "removed", "divided", "postponed"]$q$::jsonb, 0, $q$["נכון. 'squeezed' פירושו נדחס — אותה כמות עבודה נדחסה לפחות זמן.", "לא נכון. העבודה לא הוסרה אלא נדחסה לזמן קצר יותר.", "לא נכון. המילה אינה מתארת חלוקה של העבודה.", "לא נכון. העבודה לא נדחתה; היא בוצעה בזמן קצר יותר."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["the same work was squeezed into less time"]$q$::jsonb, $q$shabbat batch F, passage=fourday, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, what happened after the British pilot ended?$q$, $q$["Researchers in Iceland launched a larger trial in the public sector.", "The government made the four-day week compulsory for large firms.", "The majority of participating organizations kept the shorter week.", "Most organizations returned to five days because productivity fell."]$q$::jsonb, 2, $q$["לא נכון. הניסויים באיסלנד נערכו בין 2015 ל-2019, לפני הפיילוט הבריטי.", "לא נכון. הפסקה אינה מזכירה חקיקה או חובה ממשלתית.", "נכון. הפסקה השנייה כותבת שרוב הארגונים בחרו להמשיך לאחר הפיילוט.", "לא נכון. זה ההפך ממה שכתוב — רוב הארגונים המשיכו בשבוע הקצר."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Most of them chose to continue afterward"]$q$::jsonb, $q$shabbat batch F, passage=fourday, q5$q$, 5, true);
