  if not exists (select 1 from reading_passages where title = $q$Victor Gruen and the Shopping Mall$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Victor Gruen and the Shopping Mall$q$, $q$Victor Gruen was born in Vienna in 1903 and trained as an architect in a city famous for its cafes, squares, and pedestrian streets. In 1938, after Austria was annexed by Nazi Germany, he fled to the United States with little money and almost no English. He began by designing shop fronts in New York, and his skill at attracting customers soon brought him larger commissions. Within a decade he had founded his own firm and moved to the growing suburbs of the American West and Midwest.

Gruen was troubled by what he saw in those suburbs. Families lived in scattered houses connected only by highways, with nowhere to walk and no public place to gather. His answer was to recreate the European city center in a single planned building. In 1956 he completed Southdale Center near Minneapolis, the first fully enclosed shopping mall with a controlled climate. Its shops surrounded a central court with a garden, a cafe, and space for concerts, all protected from the Minnesota winter.

Gruen imagined that Southdale would be only the core of a larger community, with apartments, schools, offices, and parks built around it. Instead, developers copied the enclosed mall and dropped the rest of the plan. Surrounded by vast parking lots, malls spread across the country and drew shoppers away from traditional downtowns. The pedestrian life Gruen hoped to encourage rarely appeared outside the mall's walls.

Toward the end of his life, Gruen rejected the very buildings that had made him famous. He returned to Vienna in 1968 and, in a speech a decade later, refused to accept responsibility for what he called the ugly developments built in his name. He died in 1980, remembered as the father of the shopping mall, a title he would gladly have given away.$q$, $q$society / history$q$, 4, 293, true, $q$reading_shabbat_2026-09-05_F$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Southdale Center was the first shopping mall in the world to be fully enclosed and climate controlled.", "Gruen invented the enclosed mall as a substitute for the city center, but the result betrayed his vision.", "Suburban families in the 1950s lived in scattered houses with no public places in which to gather.", "Victor Gruen fled Vienna in 1938 and built a successful architecture practice in the United States."]$q$::jsonb, 1, $q$["לא נכון. זהו פרט מהפסקה השנייה, ולא הרעיון המרכזי של הקטע.", "נכון. הקטע עוקב אחר החזון של גרואן, מימושו החלקי והתנערותו ממנו — זה הרעיון המרכזי.", "לא נכון. זהו הרקע שהטריד את גרואן בפסקה השנייה, ולא הרעיון המרכזי.", "לא נכון. זהו תוכן הפסקה הראשונה בלבד, ולא הרעיון המרכזי של הקטע."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch F, passage=gruen, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, what made Southdale Center different from earlier shopping centers?$q$, $q$["It was entirely enclosed and kept at a controlled temperature.", "It was the first shopping center to be built in the suburbs of Minneapolis.", "It was surrounded by apartments, schools, offices, and parks.", "It was designed by an architect who had trained in Vienna."]$q$::jsonb, 0, $q$["נכון. הפסקה השנייה מציינת שסאות'דייל היה הקניון הראשון שהיה סגור לחלוטין עם אקלים מבוקר.", "לא נכון. הפסקה אינה טוענת שהוא היה מרכז הקניות הראשון בפרברי מיניאפוליס.", "לא נכון. הפסקה השלישית אומרת שדווקא חלק זה של התוכנית ננטש.", "לא נכון. הכשרתו של גרואן מוזכרת בפסקה הראשונה ואינה מה שייחד את הקניון."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["the first fully enclosed shopping mall with a controlled climate"]$q$::jsonb, $q$shabbat batch F, passage=gruen, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the third paragraph is to —$q$, $q$["describe Gruen's early career designing shop fronts in New York.", "explain why Gruen decided to return to Vienna toward the end of his life.", "describe the garden, cafe, and concert space at the heart of Southdale.", "show how developers eagerly adopted the enclosed mall while abandoning the larger community Gruen had planned."]$q$::jsonb, 3, $q$["לא נכון. זהו תוכן הפסקה הראשונה, ולא מטרת הפסקה השלישית.", "לא נכון. זהו תוכן הפסקה הרביעית, ולא מטרת הפסקה השלישית.", "לא נכון. זהו תוכן הפסקה השנייה, ולא מטרת הפסקה השלישית.", "נכון. הפסקה מתארת את החזון הרחב של גרואן ואז, עם Instead, מראה שהיזמים העתיקו רק את הקניון וזנחו את השאר."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch F, passage=gruen, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the phrase "a title he would gladly have given away," what can be inferred about Gruen?$q$, $q$["He wanted a younger architect to receive credit for designing Southdale.", "He hoped to be remembered mainly for his work in Vienna after 1968.", "He felt no pride in being known as the inventor of the shopping mall.", "He believed the title had been given to the wrong architect by mistake."]$q$::jsonb, 2, $q$["לא נכון. הקטע אינו מזכיר אדריכל צעיר אחר.", "לא נכון. הקטע אינו מציין במה רצה להיזכר.", "נכון. אם היה מוותר בשמחה על התואר 'אבי הקניון', נובע מכך שלא חש בו גאווה — וזה מתיישב עם דחייתו את הבניינים בפסקה האחרונה.", "לא נכון. הקטע אינו רומז לטעות בזיהוי המתכנן."]$q$::jsonb, $q$inference$q$, $q$anchor$q$, $q$["a title he would gladly have given away"]$q$::jsonb, $q$shabbat batch F, passage=gruen, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Which of the following is NOT mentioned in the first paragraph?$q$, $q$["Gruen was born in Vienna in 1903.", "Gruen was invited to America by a wealthy developer.", "Gruen designed shop fronts in New York.", "Gruen founded his own firm within ten years."]$q$::jsonb, 1, $q$["לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש.", "נכון. זו הקביעה שאינה מופיעה — הפסקה כותבת שגרואן ברח לארצות הברית כמעט בלי כסף, ולא מזכירה הזמנה מיזם עשיר.", "לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש.", "לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — הוא ייסד משרד משלו בתוך עשור."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["He began by designing shop fronts in New York, and his skill at attracting customers soon brought him larger commissions"]$q$::jsonb, $q$shabbat batch F, passage=gruen, q5$q$, 5, true);
  end if;
