do $$ declare v_pid uuid; begin

  if not exists (select 1 from reading_passages where title = $q$Malcom McLean and the Shipping Container$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Malcom McLean and the Shipping Container$q$, $q$Malcom McLean was a truck driver from North Carolina who built a small trucking company into one of the largest in the United States. In the 1930s, while waiting at a dock for his cargo to be loaded, he reportedly watched workers moving crates one at a time from truck to ship. The process struck him as absurdly slow, and the idea of lifting the entire truck body onto the vessel stayed with him for years. Before containers existed, loading a ship could take longer than the voyage itself, and theft on the docks was common.

In 1956 McLean sold his trucking business, bought an old tanker, and refitted it to carry steel boxes on its deck. The ship, renamed the Ideal-X, sailed from Newark to Houston in April of that year with fifty-eight containers aboard. The cost of loading cargo fell to a small fraction of the previous figure. Yet the invention itself was less important than the system built around it. Ports needed new cranes, railways needed special wagons, and shipping companies had to agree on a standard box. That agreement came only after years of argument, when international standards for container sizes were adopted in the 1960s.

The consequences reached far beyond the shipping industry. Because moving goods became cheap and predictable, factories could be located wherever labor was least expensive, and components could cross oceans several times before a product was finished. Old ports such as London and New York declined as traffic moved to new terminals with room for cranes and trucks. Economists now regard the humble container as one of the main causes of modern globalization, although few consumers ever notice it.$q$, $q$economics / technology$q$, 4, 277, true, $q$reading_shabbat_2026-09-05_F$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["The Voyage of the Ideal-X from Newark to Houston", "Why Old Ports Such as London and New York Declined", "The Steel Box That Quietly Reshaped World Trade", "A Truck Driver's Long Wait at a Crowded Dock"]$q$::jsonb, 2, $q$["לא נכון. ההפלגה היא פרט אחד מהפסקה השנייה, ולא נושא הקטע כולו.", "לא נכון. דעיכת הנמלים היא פרט מהפסקה השלישית, ולא הנושא המרכזי.", "נכון. הכותרת מקיפה את המצאת המכולה ואת השפעתה הרחבה על הסחר העולמי — נושא הקטע כולו.", "לא נכון. ההמתנה בנמל היא נקודת הפתיחה בלבד, לא נושא הקטע."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch F, passage=container, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, what problem did McLean observe at the dock?$q$, $q$["The dock workers were stealing crates from his trucks.", "The ship was too small to carry all of his cargo.", "His trucks were not allowed to drive onto the ship.", "Cargo was being transferred piece by piece, which took a very long time."]$q$::jsonb, 3, $q$["לא נכון. גניבה בנמלים מוזכרת כבעיה כללית, לא כמשהו שמקלין ראה קורה למשאיותיו.", "לא נכון. הפסקה אינה מזכירה את גודל הספינה.", "לא נכון. הפסקה אינה מזכירה איסור כזה; הרעיון להעלות את גוף המשאית היה רעיון של מקלין.", "נכון. הפסקה הראשונה מתארת פועלים המעבירים ארגזים אחד-אחד מהמשאית לספינה, תהליך שנראה לו איטי להחריד."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["he reportedly watched workers moving crates one at a time from truck to ship"]$q$::jsonb, $q$shabbat batch F, passage=container, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["describe the wider economic effects of containerization.", "explain how McLean converted an old tanker into a container ship.", "describe the slow process of loading ships before containers existed.", "explain why shipping companies argued for years over a standard box."]$q$::jsonb, 0, $q$["נכון. הפסקה האחרונה מתארת את ההשלכות שחרגו מענף הספנות: מיקום מפעלים, דעיכת נמלים ישנים וגלובליזציה.", "לא נכון. זהו תוכן הפסקה השנייה, ולא מטרת הפסקה האחרונה.", "לא נכון. זהו תוכן הפסקה הראשונה, ולא מטרת הפסקה האחרונה.", "לא נכון. זהו תוכן הפסקה השנייה, ולא מטרת הפסקה האחרונה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch F, passage=container, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the second paragraph, the word "refitted" most nearly means —$q$, $q$["repainted it in the company's colors", "modified it to serve a new purpose", "sold it to another shipping company", "repaired it after a serious accident"]$q$::jsonb, 1, $q$["לא נכון. המילה אינה עוסקת בצביעה.", "נכון. 'refitted' פירושו שינה והתאים מחדש — מקלין התאים את המכלית כדי שתוכל לשאת מכולות פלדה.", "לא נכון. מקלין קנה את הספינה, לא מכר אותה.", "לא נכון. הפסקה אינה מזכירה תאונה או תיקון."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["refitted it to carry steel boxes on its deck"]$q$::jsonb, $q$shabbat batch F, passage=container, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the second paragraph that —$q$, $q$["the container's success depended on cooperation among several industries.", "the Ideal-X was the largest cargo ship of its time.", "McLean regretted selling his profitable trucking business.", "container sizes were standardized before the Ideal-X sailed."]$q$::jsonb, 0, $q$["נכון. הפסקה מדגישה שהמערכת סביב ההמצאה הייתה חשובה יותר ממנה, ושנמלים, רכבות וחברות ספנות נדרשו כולם להתאים את עצמם — מכאן שהצלחה תלויה בשיתוף פעולה בין ענפים.", "לא נכון. הפסקה מתארת מכלית ישנה עם 58 מכולות, לא ספינת ענק.", "לא נכון. הפסקה אינה מזכירה חרטה.", "לא נכון. הפסקה כותבת שהתקנים אומצו בשנות השישים, אחרי ההפלגה ב-1956."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, $q$["Ports needed new cranes, railways needed special wagons, and shipping companies had to agree on a standard box"]$q$::jsonb, $q$shabbat batch F, passage=container, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$The Origins of the Metric System$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Origins of the Metric System$q$, $q$Before the French Revolution, measurement in France was a source of endless confusion. The length of a foot or the size of a bushel varied from one town to the next, and a bewildering number of local units were in use. Merchants exploited the confusion, and peasants complained that landlords measured grain with one container and rent with another. Reformers in the National Assembly decided in 1790 that a single system should apply to the whole nation.

The new units were to be based on nature rather than on the body of any king. The meter was defined as one ten-millionth of the distance from the North Pole to the equator along the meridian passing through Paris. To fix this length, two astronomers, Jean-Baptiste Delambre and Pierre Mechain, spent seven years measuring the arc between Dunkirk and Barcelona. They worked through war and revolution, climbing church towers and mountains with delicate instruments. Their survey was completed in 1799, and a platinum bar representing the meter was deposited in the national archives.

Although the system was logical, ordinary people resisted it for decades. Napoleon allowed the old names to return in 1812, and the metric system did not become compulsory in France until 1840. Adoption elsewhere was gradual, spreading with trade, science, and the requirements of industry. In 1875 seventeen nations signed the Metre Convention, creating an international bureau to maintain the standards. Today nearly every country uses the metric system, while the United States remains the most prominent exception.$q$, $q$history / science$q$, 4, 244, true, $q$reading_shabbat_2026-09-05_F$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, why did peasants complain about their landlords?$q$, $q$["Landlords refused to accept grain as a form of payment for rent.", "Landlords raised the rent every time the harvest was good.", "Landlords insisted on using the new units before the law required them.", "Landlords used one size of container for grain and a different size for rent."]$q$::jsonb, 3, $q$["לא נכון. הפסקה אינה מזכירה סירוב לקבל תבואה.", "לא נכון. הפסקה אינה מזכירה העלאת שכר דירה לפי היבול.", "לא נכון. היחידות החדשות הוצגו רק מאוחר יותר; התלונה עסקה במידות הישנות.", "נכון. הפסקה הראשונה כותבת שבעלי הקרקע מדדו תבואה בכלי אחד ושכר דירה בכלי אחר — כלומר השתמשו במידות שונות לטובתם."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["peasants complained that landlords measured grain with one container and rent with another"]$q$::jsonb, $q$shabbat batch F, passage=metric, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["explain why French peasants and merchants distrusted the old units.", "trace the slow spread of the metric system beyond France.", "describe how the meter was defined and physically measured.", "explain why Napoleon allowed the old names to return in 1812."]$q$::jsonb, 2, $q$["לא נכון. זהו תוכן הפסקה הראשונה, ולא מטרת הפסקה השנייה.", "לא נכון. זהו תוכן הפסקה השלישית, ולא מטרת הפסקה השנייה.", "נכון. הפסקה השנייה מסבירה את ההגדרה של המטר לפי מרידיאן כדור הארץ ומתארת את המדידה בת שבע השנים של דלמבר ומשן.", "לא נכון. זהו תוכן הפסקה השלישית, ולא מטרת הפסקה השנייה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch F, passage=metric, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the sentence "They worked through war and revolution, climbing church towers and mountains with delicate instruments," the word "They" refers to —$q$, $q$["the reformers of the National Assembly", "the two astronomers", "the church towers and mountains", "the delicate instruments"]$q$::jsonb, 1, $q$["לא נכון. הרפורמטורים מוזכרים בפסקה הראשונה ולא ביצעו את המדידה.", "נכון. המשפט הקודם מציג את שני האסטרונומים, דלמבר ומשן, ו'They' מתייחס אליהם — הם שמדדו את הקשת.", "לא נכון. מגדלים והרים הם המקומות שעליהם טיפסו, לא מי שעבד.", "לא נכון. המכשירים הם הכלים שנשאו, לא מי שעבד."]$q$::jsonb, $q$reference_word$q$, $q$anchor$q$, $q$["They worked through war and revolution, climbing church towers and mountains with delicate instruments"]$q$::jsonb, $q$shabbat batch F, passage=metric, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, what happened "in 1875"?$q$, $q$["A group of countries signed a treaty that set up an international body to maintain the standards.", "France finally made the use of the metric system compulsory throughout the country.", "The United States announced that it would not adopt the metric system.", "The platinum bar representing the meter was placed in the national archives."]$q$::jsonb, 0, $q$["נכון. הפסקה השלישית כותבת שב-1875 שבע-עשרה מדינות חתמו על אמנת המטר, שהקימה לשכה בינלאומית לשמירת התקנים.", "לא נכון. השיטה נעשתה חובה בצרפת ב-1840, לא ב-1875.", "לא נכון. הקטע מציין שארצות הברית היא חריג, אך אינו מזכיר הודעה כזו.", "לא נכון. מוט הפלטינה הופקד בארכיון ב-1799, לפי הפסקה השנייה."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["In 1875 seventeen nations signed the Metre Convention, creating an international bureau to maintain the standards"]$q$::jsonb, $q$shabbat batch F, passage=metric, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["describe the survey conducted by Delambre and Mechain.", "explain why the meter was based on the size of the earth.", "describe the confusion caused by local units before 1790.", "trace the gradual and uneven adoption of the metric system."]$q$::jsonb, 3, $q$["לא נכון. זהו תוכן הפסקה השנייה, ולא מטרת הפסקה האחרונה.", "לא נכון. זהו תוכן הפסקה השנייה, ולא מטרת הפסקה האחרונה.", "לא נכון. זהו תוכן הפסקה הראשונה, ולא מטרת הפסקה האחרונה.", "נכון. הפסקה האחרונה עוקבת אחר ההתנגדות בצרפת, ההתפשטות ההדרגתית, אמנת 1875 והחריג האמריקאי — כלומר האימוץ האיטי והלא אחיד."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch F, passage=metric, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$Paper Money in Song and Yuan China$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Paper Money in Song and Yuan China$q$, $q$Paper money first appeared in China during the Song dynasty, centuries before it reached Europe. In the province of Sichuan, coins were made of iron rather than copper, and they were so heavy that a large purchase required a cart to carry the payment. Merchants began leaving their coins with trusted shops and exchanging paper receipts instead. Around 1024 the Song government took over the practice and issued the world's first official paper currency, known as jiaozi.

The early notes were meant to be exchanged for coins on demand, and the state limited how many could be printed. Over time, however, wars and deficits tempted officials to issue more notes than they could redeem. Prices rose, confidence fell, and the government repeatedly replaced discredited notes with new ones.

When the Mongols conquered China and founded the Yuan dynasty, they went further than any previous rulers. Kublai Khan made paper the only legal money in much of his empire and forbade the use of gold and silver in trade. The Venetian traveler Marco Polo described the system with astonishment, noting that notes made of mulberry bark were accepted everywhere as if they were metal. He marveled that the Great Khan could produce unlimited wealth from what seemed to be nothing.

That power proved to be the system's weakness. Later Yuan rulers printed enormous quantities of money to cover their expenses, and by the middle of the fourteenth century the notes had lost most of their value. The inflation contributed to the unrest that ended the dynasty in 1368. The succeeding Ming dynasty issued its own notes but eventually abandoned them in favor of silver, and China did not return to paper money for centuries. The lesson that a currency backed only by trust can be destroyed by overprinting was learned in China long before Europe had its first bank.$q$, $q$economics / history$q$, 5, 306, true, $q$reading_shabbat_2026-09-05_F$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["China invented paper money and also discovered, through repeated inflation, its central danger.", "Iron coins in Sichuan were so heavy that merchants preferred to use paper receipts instead.", "Marco Polo was astonished to find that notes made of mulberry bark were accepted as money.", "The Ming dynasty abandoned paper money and relied on silver for several centuries."]$q$::jsonb, 0, $q$["נכון. הקטע עוקב אחר המצאת הכסף הנייר בסין ואחר האינפלציה החוזרת שחשפה את חולשתו — זה הרעיון המרכזי.", "לא נכון. זהו פרט מהפסקה הראשונה, ולא הרעיון המרכזי של הקטע.", "לא נכון. זהו פרט מהפסקה השלישית, ולא הרעיון המרכזי של הקטע.", "לא נכון. זהו פרט מהפסקה האחרונה, ולא הרעיון המרכזי של הקטע."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch F, passage=papermoney, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the third paragraph, all of the following are true EXCEPT —$q$, $q$["The Yuan dynasty was founded by Mongol conquerors.", "Kublai Khan allowed gold and silver to be used alongside paper notes.", "Marco Polo wrote about the paper money system with amazement.", "The notes were made from the bark of mulberry trees."]$q$::jsonb, 1, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש.", "נכון. זו הקביעה השגויה — הפסקה כותבת שקובלאי חאן אסר על שימוש בזהב ובכסף במסחר.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — מרקו פולו תיאר את השיטה בהשתאות.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — השטרות היו עשויים מקליפת עץ תות."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["forbade the use of gold and silver in trade"]$q$::jsonb, $q$shabbat batch F, passage=papermoney, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["explain why iron coins were used in Sichuan instead of copper.", "describe Marco Polo's reaction to the Yuan monetary system.", "explain how the early Song notes gradually lost their value.", "describe the fall of the Yuan dynasty in the fourteenth century."]$q$::jsonb, 2, $q$["לא נכון. זהו תוכן הפסקה הראשונה, ולא מטרת הפסקה השנייה.", "לא נכון. זהו תוכן הפסקה השלישית, ולא מטרת הפסקה השנייה.", "נכון. הפסקה השנייה מסבירה שהמדינה הנפיקה יותר שטרות ממה שיכלה לפדות, ולכן המחירים עלו והאמון ירד.", "לא נכון. זהו תוכן הפסקה הרביעית, ולא מטרת הפסקה השנייה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch F, passage=papermoney, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the second paragraph, the word "redeem" is closest in meaning to —$q$, $q$["print", "forbid", "collect as tax", "exchange for coins"]$q$::jsonb, 3, $q$["לא נכון. הפסקה מבחינה בין הדפסת שטרות לבין פדייתם.", "לא נכון. המילה אינה עוסקת באיסור.", "לא נכון. המילה אינה עוסקת בגביית מס.", "נכון. 'redeem' פירושו לפדות — להחליף את השטר במטבעות, כפי שהשטרות המוקדמים היו אמורים להיות מוחלפים במטבעות לפי דרישה."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["issue more notes than they could redeem"]$q$::jsonb, $q$shabbat batch F, passage=papermoney, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the first paragraph that —$q$, $q$["copper was more plentiful in Sichuan than in the rest of China.", "the Song government invented paper receipts before merchants did.", "the inconvenience of carrying heavy iron coins helped bring paper money into being.", "paper money reached Europe only a few years after it appeared in China."]$q$::jsonb, 2, $q$["לא נכון. הפסקה אומרת שבסצ'ואן השתמשו בברזל במקום נחושת, ואינה טוענת שהנחושת הייתה שופעת שם.", "לא נכון. הפסקה כותבת שהסוחרים החלו בנוהג והממשלה השתלטה עליו רק לאחר מכן.", "נכון. הפסקה מתארת מטבעות ברזל כבדים כל כך שנדרשה עגלה, ומיד אחר כך את המעבר לקבלות נייר — מכאן שהכובד סייע להולדת הכסף הנייר.", "לא נכון. הפסקה כותבת שהכסף הנייר הגיע לאירופה מאות שנים מאוחר יותר."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, $q$["they were so heavy that a large purchase required a cart to carry the payment"]$q$::jsonb, $q$shabbat batch F, passage=papermoney, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$Fair Trade Coffee: Promise and Debate$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Fair Trade Coffee: Promise and Debate$q$, $q$Coffee is grown mainly by small farmers in tropical countries, yet most of the profit is earned far from the fields. World prices swing sharply from year to year, and a poor harvest or a glut in Brazil can leave growers in Africa or Central America unable to cover their costs. In 1988 a Dutch organization launched the first fair trade label, named Max Havelaar after a nineteenth-century novel about colonial abuses. The idea was simple: consumers would pay slightly more, and the extra money would guarantee farmers a decent income.

Under the system that developed, certified cooperatives receive a minimum price that protects them when the market collapses. They also receive a premium to spend on community projects such as schools or wells. In return, they must meet standards covering labor conditions and environmental practices. The label spread from coffee to bananas, cocoa, and tea, and by the 2000s it appeared in supermarkets across Europe and North America. For many shoppers it became the most visible way to connect an everyday purchase with the people who produced it.

Nevertheless, economists have questioned how much of the extra price actually reaches the poor. Certification is costly, so the poorest farmers often cannot join, and the benefits tend to flow to cooperatives rather than to the hired laborers who do the hardest work. Some studies have found only small differences in income between certified and uncertified growers. Critics also argue that a guaranteed price encourages farmers to keep producing coffee when the market is oversupplied. Supporters respond that fair trade was never meant to solve poverty alone, but to give consumers a way to reward better practices.$q$, $q$economics$q$, 5, 275, true, $q$reading_shabbat_2026-09-05_F$q$)
      returning id into v_pid;
