      values (v_pid, $q$Based on the passage, what can be inferred about fair trade coffee?$q$, $q$["It has largely eliminated poverty among coffee farmers in Africa and Central America.", "Its benefits are real but smaller and less evenly shared than early supporters hoped.", "It has been abandoned by most European supermarkets because of economists' criticism.", "Its main purpose was to protect Brazilian growers from sudden falls in world prices."]$q$::jsonb, 1, $q$["לא נכון. הפסקה השלישית מציינת שההשפעה על ההכנסה נמצאה קטנה, ואף התומכים אינם טוענים שהעוני נפתר.", "נכון. הקטע מציג את הרעיון ואת התפשטותו, ואז ביקורת על כך שהתועלת קטנה ואינה מגיעה לעניים ביותר — מכאן שהיתרונות אמיתיים אך מוגבלים.", "לא נכון. הקטע כותב שהתווית מופיעה בסופרמרקטים, ואינו מזכיר נטישה.", "לא נכון. ברזיל מוזכרת כמקור לעודף היצע, לא כמי שהתווית נועדה להגן עליה."]$q$::jsonb, $q$inference$q$, $q$text$q$, null, $q$shabbat batch F, passage=fairtrade, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, why was the first fair trade label given the name Max Havelaar?$q$, $q$["It was named after a novel that criticized colonial exploitation.", "It was named after the Dutch activist who founded the organization.", "It was named after a coffee plantation in the Dutch colonies.", "It was named after the first farmer to receive certification."]$q$::jsonb, 0, $q$["נכון. הפסקה הראשונה כותבת שהתווית נקראה על שם רומן מהמאה התשע-עשרה על עוולות קולוניאליות.", "לא נכון. הפסקה אינה מזכירה פעיל בשם זה; מדובר ברומן.", "לא נכון. הפסקה אינה מזכירה מטע.", "לא נכון. הפסקה אינה מזכירה חקלאי ראשון."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["named Max Havelaar after a nineteenth-century novel about colonial abuses"]$q$::jsonb, $q$shabbat batch F, passage=fairtrade, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["explain why world coffee prices are so unstable from year to year.", "present the arguments of economists who doubt the value of fair trade.", "describe the origins of the Max Havelaar label in the Netherlands.", "explain how the fair trade system operates and how widely it spread."]$q$::jsonb, 3, $q$["לא נכון. זהו תוכן הפסקה הראשונה, ולא מטרת הפסקה השנייה.", "לא נכון. זהו תוכן הפסקה השלישית, ולא מטרת הפסקה השנייה.", "לא נכון. זהו תוכן הפסקה הראשונה, ולא מטרת הפסקה השנייה.", "נכון. הפסקה השנייה מתארת את מנגנון המחיר המינימלי והפרמיה, את התנאים הנדרשים ואת התפשטות התווית למוצרים ולמדינות נוספים."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch F, passage=fairtrade, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, what do critics say that a "guaranteed price" encourages?$q$, $q$["Cooperatives to spend their premium on schools rather than on wells.", "Supermarkets to charge consumers more than the label justifies.", "Growers to go on producing coffee even when there is already too much of it.", "The poorest farmers to seek certification they cannot afford."]$q$::jsonb, 2, $q$["לא נכון. הפסקה אינה קושרת בין המחיר המובטח לבחירה בין בתי ספר לבארות.", "לא נכון. הפסקה אינה מזכירה תמחור של סופרמרקטים.", "נכון. הפסקה השלישית כותבת שהמבקרים טוענים שמחיר מובטח מעודד חקלאים להמשיך לגדל קפה כשהשוק כבר רווי.", "לא נכון. הפסקה אומרת שהעניים ביותר אינם יכולים להצטרף, לא שהמחיר המובטח מעודד אותם לנסות."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["a guaranteed price encourages farmers to keep producing coffee when the market is oversupplied"]$q$::jsonb, $q$shabbat batch F, passage=fairtrade, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["describe the standards that certified cooperatives are required to meet.", "present criticisms of fair trade along with a brief reply from its supporters.", "explain how the fair trade label spread from coffee to other products.", "argue that consumers should stop buying fair trade coffee."]$q$::jsonb, 1, $q$["לא נכון. זהו תוכן הפסקה השנייה, ולא מטרת הפסקה האחרונה.", "נכון. הפסקה מונה את טענות הכלכלנים והמבקרים ומסיימת בתגובת התומכים.", "לא נכון. זהו תוכן הפסקה השנייה, ולא מטרת הפסקה האחרונה.", "לא נכון. הפסקה מציגה ביקורת ותגובה, ואינה קוראת להפסיק לקנות."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch F, passage=fairtrade, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$The Gig Economy$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Gig Economy$q$, $q$The term gig economy describes a labor market in which work is divided into short tasks that are allocated through digital platforms. A driver accepts a ride through an app, a courier delivers a meal, a designer completes a logo for a client on another continent. The word gig was borrowed from musicians, for whom a single paid performance has long been the normal unit of work. What is new is not the temporary job itself but the speed with which software now matches supply and demand.

Platforms present this arrangement as liberation. Workers choose their own hours, answer to no supervisor, and can combine several sources of income. For students, parents, and people between jobs, the flexibility is real and valuable. The companies, meanwhile, avoid the fixed costs of employment, since they classify the people who work through their apps as independent contractors rather than staff.

That classification lies at the heart of the controversy. Contractors receive no minimum wage, paid leave, or protection against dismissal, and they bear the costs of their own vehicles and insurance. Critics argue that the freedom is partly an illusion, because algorithms set prices, distribute tasks, and quietly penalize those who decline too many offers. Courts have begun to agree. In 2021 the British Supreme Court ruled that Uber drivers were workers entitled to basic rights, and similar decisions have followed elsewhere.

The deeper question is whether gig work represents the future of employment or a return to its past. Before the twentieth century, most laborers were hired by the day and enjoyed few guarantees; the permanent job with benefits was a relatively recent achievement. Defenders of the platforms reply that rigid employment rules would destroy the flexibility that many workers genuinely want. The likely outcome is neither full employment status nor pure contracting, but a third category that several governments are now attempting to define.$q$, $q$economics / society$q$, 6, 312, true, $q$reading_shabbat_2026-09-05_F$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["The word gig was borrowed from musicians, for whom a single performance is the normal unit of work.", "In 2021 the British Supreme Court ruled that Uber drivers were workers entitled to basic rights.", "Digital platforms give students and parents a valuable way to earn money on a flexible schedule.", "Gig work offers real flexibility but raises unresolved questions about workers' status and rights."]$q$::jsonb, 3, $q$["לא נכון. זהו פרט מהפסקה הראשונה, ולא הרעיון המרכזי של הקטע.", "לא נכון. זהו פרט מהפסקה השלישית, ולא הרעיון המרכזי של הקטע.", "לא נכון. זהו צד אחד בלבד של הוויכוח, המוצג בפסקה השנייה.", "נכון. הקטע מציג את הגמישות של עבודת הפלטפורמות ואת המחלוקת על מעמד העובדים וזכויותיהם, ומסיים בשאלה שעדיין פתוחה."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch F, passage=gig, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the third paragraph, all of the following are true EXCEPT —$q$, $q$["Contractors must pay for their own vehicles and insurance.", "Algorithms may penalize workers who reject too many offers.", "Contractors are guaranteed a minimum wage under most platform agreements.", "A British court decided that Uber drivers deserve basic rights."]$q$::jsonb, 2, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — האלגוריתמים מענישים בשקט את מי שמסרב להצעות רבות.", "נכון. זו הקביעה השגויה — הפסקה כותבת במפורש שקבלנים אינם מקבלים שכר מינימום.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — בית המשפט העליון הבריטי פסק כך ב-2021."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Contractors receive no minimum wage, paid leave, or protection against dismissal"]$q$::jsonb, $q$shabbat batch F, passage=gig, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["present the advantages of gig work for workers and for the platforms.", "explain the origin of the word gig in the world of music.", "describe the court decisions that have challenged the platforms.", "compare gig work with the labor markets of the nineteenth century."]$q$::jsonb, 0, $q$["נכון. הפסקה השנייה מציגה את היתרונות: גמישות לעובדים וחיסכון בעלויות קבועות לחברות.", "לא נכון. זהו תוכן הפסקה הראשונה, ולא מטרת הפסקה השנייה.", "לא נכון. זהו תוכן הפסקה השלישית, ולא מטרת הפסקה השנייה.", "לא נכון. זהו תוכן הפסקה הרביעית, ולא מטרת הפסקה השנייה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch F, passage=gig, q3$q$, 3, true);
