      values (v_pid, $q$In the first paragraph, the word "allocated" most nearly means —$q$, $q$["cancelled", "distributed", "invented", "completed"]$q$::jsonb, 1, $q$["לא נכון. המשימות אינן מבוטלות אלא מחולקות דרך הפלטפורמות.", "נכון. 'allocated' פירושו מחולק או מוקצה — המשימות מוקצות לעובדים באמצעות הפלטפורמות.", "לא נכון. המילה אינה עוסקת בהמצאה.", "לא נכון. המשימות מחולקות דרך הפלטפורמה, לא מושלמות על ידה."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["short tasks that are allocated through digital platforms"]$q$::jsonb, $q$shabbat batch F, passage=gig, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the statement that "the permanent job with benefits was a relatively recent achievement," what can be inferred?$q$, $q$["For most of history, secure employment was not the normal condition of workers.", "Permanent jobs with benefits were first introduced by the digital platforms.", "Governments have already decided to abolish permanent employment.", "Day laborers before the twentieth century earned more than gig workers today."]$q$::jsonb, 0, $q$["נכון. אם משרה קבועה עם הטבות היא הישג חדש יחסית, נובע מכך שבמשך רוב ההיסטוריה תעסוקה בטוחה לא הייתה המצב הרגיל — וכך כותבת גם הפסקה על שכירים יומיים.", "לא נכון. הפלטפורמות מסווגות עובדים כקבלנים, לא יוצרות משרות קבועות.", "לא נכון. הפסקה כותבת שממשלות מנסות להגדיר קטגוריה שלישית, לא לבטל תעסוקה קבועה.", "לא נכון. הקטע אינו משווה שכר בין התקופות."]$q$::jsonb, $q$inference$q$, $q$anchor$q$, $q$["the permanent job with benefits was a relatively recent achievement"]$q$::jsonb, $q$shabbat batch F, passage=gig, q5$q$, 5, true);
  end if;
end $$;
do $$ declare v_pid uuid; begin

  if not exists (select 1 from reading_passages where title = $q$The Library of Alexandria$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Library of Alexandria$q$, $q$The Library of Alexandria was founded in Egypt in the early third century BCE, during the reign of the first Ptolemaic kings. It formed part of a larger research institution known as the Mouseion, where scholars lived, studied and taught at royal expense. The founders had an unusually ambitious goal: to gather a copy of every book in the known world. Agents were sent abroad to purchase manuscripts, and ships entering the harbor were reportedly searched for scrolls to copy. Ancient sources claim the collection eventually held hundreds of thousands of rolls, although modern historians treat such figures with caution.

The library attracted some of the most gifted thinkers of the ancient Mediterranean. Eratosthenes, who served as head librarian, calculated the circumference of the Earth with remarkable accuracy using only shadows and geometry. The poet Callimachus compiled a vast catalogue of the holdings, organized by subject and author, which is often regarded as the first library catalogue. Scholars there also produced careful editions of Homer, establishing methods of textual comparison that survive in modern scholarship. In this way, the institution became a model for how knowledge could be collected, sorted and preserved.

A popular story holds that the library vanished in a single great fire, yet the evidence points to a slower decline. Julius Caesar's troops did start a fire in the harbor in 48 BCE, and some scrolls stored nearby were probably lost. However, the library's real problems were political: rulers cut funding, expelled scholars and neglected the collection over several centuries. By late antiquity, it had faded so gradually that no contemporary writer recorded its final end. Its legend nevertheless endured, and in 2002 a modern library opened on the Alexandrian shore in its memory.$q$, $q$history$q$, 4, 285, true, $q$reading_shabbat_2026-09-05_G$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["The Library of Alexandria was an ambitious center of scholarship whose decline was gradual rather than sudden.", "Eratosthenes measured the Earth's circumference using only shadows and geometry.", "Julius Caesar's troops burned the library to the ground in 48 BCE.", "A modern library was opened in Alexandria in 2002 to honor the ancient one."]$q$::jsonb, 0, $q$["נכון. הקטע כולו מתאר את שאיפות הספרייה, את הישגי חוקריה ואת דעיכתה ההדרגתית, ולכן זהו הרעיון המרכזי.", "לא נכון. זהו פרט אחד מהפסקה השנייה, ולא הרעיון המרכזי של הקטע כולו.", "לא נכון. הפסקה השלישית דווקא טוענת שהשריפה של קיסר גרמה לאובדן חלקי בלבד, והדעיכה הייתה איטית.", "לא נכון. זהו פרט מסיים מהפסקה השלישית, ולא הרעיון המרכזי של הקטע."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch G, passage=alexandria, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, how did the library try to build its collection?$q$, $q$["By requiring every scholar at the Mouseion to donate his personal books.", "By buying manuscripts abroad and copying scrolls found on ships in the harbor.", "By accepting only original works written by authors living in Egypt.", "By forcing rival kingdoms in the eastern Mediterranean to hand over their royal archives as tribute."]$q$::jsonb, 1, $q$["לא נכון. הפסקה אינה מזכירה חובת תרומה של החוקרים במוזיאון.", "נכון. הפסקה מספרת ששליחים נשלחו לחו\"ל לרכוש כתבי יד, וספינות שנכנסו לנמל נבדקו כדי להעתיק מגילות.", "לא נכון. הפסקה מדגישה שהמטרה הייתה לאסוף עותק של כל ספר בעולם, לא רק יצירות מקוריות ממצרים.", "לא נכון. הפסקה אינה מזכירה סחיטת ארכיונים מממלכות יריבות."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Agents were sent abroad to purchase manuscripts, and ships entering the harbor were reportedly searched for scrolls to copy"]$q$::jsonb, $q$shabbat batch G, passage=alexandria, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["explain why the library's collection declined slowly over several centuries.", "describe the political conflicts between the Ptolemaic kings and their scholars.", "illustrate the scholarly achievements of the people who worked at the library.", "argue that ancient figures for the size of the collection cannot be trusted."]$q$::jsonb, 2, $q$["לא נכון. הדעיכה ההדרגתית היא נושא הפסקה השלישית, לא השנייה.", "לא נכון. סכסוכים פוליטיים נזכרים בקצרה בפסקה השלישית, ואינם נושא הפסקה השנייה.", "נכון. הפסקה מביאה דוגמאות להישגי החוקרים בספרייה — ארטוסתנס, קלימכוס ומהדורות הומרוס.", "לא נכון. הספקנות לגבי מספר המגילות מופיעה בסוף הפסקה הראשונה, לא בשנייה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch G, passage=alexandria, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the statement that "no contemporary writer recorded its final end" that —$q$, $q$["ancient writers were forbidden by the rulers from mentioning the library.", "the library was destroyed so suddenly that nobody survived to describe the event.", "all records of the library were deliberately destroyed by later governments.", "there was no single dramatic moment that people at the time saw as its destruction."]$q$::jsonb, 3, $q$["לא נכון. הקטע אינו מזכיר איסור כלשהו על כתיבה אודות הספרייה.", "לא נכון. הפסקה אומרת את ההפך — הספרייה דעכה בהדרגה, לא בחורבן פתאומי.", "לא נכון. הקטע אינו טוען שרשומות הושמדו בכוונה.", "נכון. אם הדעיכה הייתה כה הדרגתית שאיש לא תיעד את סופה, משתמע שלא היה רגע דרמטי אחד שנתפס בזמנו כחורבן."]$q$::jsonb, $q$inference$q$, $q$anchor$q$, $q$["no contemporary writer recorded its final end"]$q$::jsonb, $q$shabbat batch G, passage=alexandria, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the first paragraph, the word "ambitious" is closest in meaning to —$q$, $q$["aiming very high", "extremely expensive to carry out", "impossible to explain clearly", "based on a foreign tradition"]$q$::jsonb, 0, $q$["נכון. 'ambitious' פירושו שאפתני — מטרה השואפת גבוה מאוד, כמו איסוף עותק של כל ספר בעולם.", "לא נכון. המילה מתארת את גודל השאיפה, לא את העלות.", "לא נכון. המילה אינה קשורה לקושי בהסבר.", "לא נכון. המילה אינה קשורה למקור המסורת."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["unusually ambitious goal"]$q$::jsonb, $q$shabbat batch G, passage=alexandria, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$The Black Death and the Wages of Labor$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Black Death and the Wages of Labor$q$, $q$The Black Death reached the ports of Sicily in 1347 aboard merchant ships arriving from the Black Sea. Within four years, the plague had spread across nearly all of Europe, killing somewhere between a third and half of the population. Whole villages were emptied, and fields that had been cultivated for centuries were left to grow wild. Historians have long debated the precise mortality figures, yet few doubt that the demographic collapse was without precedent in European history.

The economic consequences of this catastrophe were profound and, in some respects, surprising. Before the plague, Europe's population had grown so large that land was scarce and labor was cheap. Afterward, the situation was reversed: land was abundant, but workers to farm it were suddenly in short supply. Surviving peasants and craftsmen discovered that they could demand higher wages, better conditions or the freedom to leave their lord's estate. In many regions, real wages climbed to levels that would not be matched again for several centuries.

Landowners and governments reacted with alarm to this shift in bargaining power. In England, the Statute of Labourers of 1351 attempted to freeze wages at the levels that had prevailed before the plague. Similar measures appeared elsewhere, and courts imposed fines on workers who asked for more than the legal rate. Nevertheless, such laws proved extremely difficult to enforce, because employers competing for scarce workers were often willing to pay illegally high wages. Resentment against these restrictions contributed to the outbreak of the Peasants' Revolt in England in 1381.

The long-term effects varied considerably across the continent. In much of Western Europe, serfdom gradually weakened as lords conceded greater freedom in order to retain their tenants. In parts of Eastern Europe, by contrast, the nobility responded to the labor shortage by tightening legal restrictions on peasants. The same shock, in other words, produced opposite outcomes depending on the balance of political power in each society.$q$, $q$history / economics$q$, 6, 316, true, $q$reading_shabbat_2026-09-05_G$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["How the Plague Arrived in Sicily in 1347", "A Plague That Reshaped the Balance Between Workers and Landowners", "The Peasants' Revolt of 1381 and Its Causes", "Serfdom in Eastern Europe During the Late Middle Ages"]$q$::jsonb, 1, $q$["לא נכון. הגעת המגפה לסיציליה היא פרט מהפסקה הראשונה בלבד.", "נכון. הקטע כולו עוסק בשינוי ביחסי הכוח בין עובדים לבעלי אדמות בעקבות המגפה, ולכן זו הכותרת המתאימה.", "לא נכון. המרד נזכר במשפט אחד בפסקה השלישית, ואינו נושא הקטע.", "לא נכון. הצמיתות במזרח אירופה נזכרת רק בפסקה האחרונה כדוגמה אחת מבין שתיים."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch G, passage=blackdeath, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the third paragraph, all of the following are true EXCEPT —$q$, $q$["English law in 1351 tried to hold wages at the levels of the years before the plague.", "Workers who demanded more than the legal wage could be fined by the courts.", "Employers generally cooperated with the authorities by refusing to pay above the legal rate.", "Anger at wage restrictions helped fuel a major uprising in England in 1381."]$q$::jsonb, 2, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — חוק העובדים מ-1351 ניסה להקפיא את השכר ברמות שלפני המגפה.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — בתי משפט הטילו קנסות על עובדים שדרשו יותר מהשכר החוקי.", "נכון. זו הקביעה השגויה — הפסקה אומרת שמעסיקים שהתחרו על עובדים היו מוכנים לשלם שכר גבוה באופן בלתי חוקי, ולכן החוק היה קשה לאכיפה.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — הטינה כלפי ההגבלות תרמה למרד האיכרים ב-1381."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["employers competing for scarce workers were often willing to pay illegally high wages"]$q$::jsonb, $q$shabbat batch G, passage=blackdeath, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["explain why wages rose so sharply in the years immediately after the plague.", "describe how governments attempted to control wages through legislation.", "estimate how many people died in Europe between 1347 and 1351.", "show that the same labor shortage led to different outcomes in different regions."]$q$::jsonb, 3, $q$["לא נכון. עליית השכר מוסברת בפסקה השנייה, לא באחרונה.", "לא נכון. חקיקת השכר היא נושא הפסקה השלישית, לא האחרונה.", "לא נכון. הערכת מספר המתים מופיעה בפסקה הראשונה.", "נכון. הפסקה האחרונה משווה בין מערב אירופה למזרחה ומראה שאותו מחסור בעובדים הוביל לתוצאות הפוכות."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch G, passage=blackdeath, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the second paragraph that —$q$, $q$["before the plague, plentiful labor had kept wages low.", "the plague destroyed most of Europe's farmland, making land scarce.", "craftsmen benefited from the labor shortage far more than peasants did.", "wages in Europe returned to their pre-plague levels within a single generation."]$q$::jsonb, 0, $q$["נכון. הפסקה אומרת שלפני המגפה האוכלוסייה הייתה גדולה והעבודה זולה — מכאן שהיצע העובדים הגדול החזיק את השכר נמוך.", "לא נכון. הפסקה אומרת שאחרי המגפה האדמה הייתה בשפע, לא במחסור.", "לא נכון. הפסקה מזכירה איכרים ובעלי מלאכה יחד, ואינה משווה ביניהם.", "לא נכון. הפסקה אומרת שהשכר הריאלי הגיע לרמות שלא הושגו שוב במשך מאות שנים."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch G, passage=blackdeath, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the first paragraph, the word "precedent" most nearly means —$q$, $q$["a clear scientific explanation", "an earlier example of the same kind", "a written record kept by officials", "an obvious warning sign"]$q$::jsonb, 1, $q$["לא נכון. המילה אינה עוסקת בהסבר מדעי.", "נכון. 'precedent' פירושו תקדים — מקרה קודם מאותו סוג; הקטע אומר שהקריסה הדמוגרפית הייתה ללא תקדים בהיסטוריה האירופית.", "לא נכון. המילה אינה מתייחסת לרישום רשמי.", "לא נכון. המילה אינה מתייחסת לאזהרה."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["without precedent in European history"]$q$::jsonb, $q$shabbat batch G, passage=blackdeath, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$The Trans-Siberian Railway$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Trans-Siberian Railway$q$, $q$The Trans-Siberian Railway is the longest railway line in the world, stretching roughly 9,300 kilometers from Moscow to the Pacific port of Vladivostok. Construction began in 1891, when the future Tsar Nicholas II laid a ceremonial stone at the eastern end of the route. The Russian government hoped the railway would bind its vast Siberian territories more firmly to the capital. Finance minister Sergei Witte, the project's most powerful supporter, also believed it would open the region to settlers and trade. Until then, a journey across Siberia could take months by horse-drawn carriage and river boat.

Building the line across such distances presented enormous engineering difficulties. Workers had to lay track through swamps, dense forest and ground that remained frozen for much of the year. Lake Baikal, the deepest lake in the world, blocked the route entirely, so for several years trains were carried across its waters by a specially built ferry. A track around the southern shore of the lake, requiring dozens of tunnels, was finally completed in the early twentieth century. Despite these obstacles, the main sections of the railway were finished in a little over a decade.

The railway transformed Siberia far more quickly than its planners had expected. Millions of peasants from European Russia moved east along the line in search of land, and new towns grew up around its stations. The route also proved to be of great military importance, although its limited capacity was exposed during the war with Japan in 1904 and 1905. Today the full journey still takes about a week, crossing seven time zones along the way. It remains a vital freight corridor, and it continues to attract travelers drawn by the sheer scale of the crossing.$q$, $q$history / technology$q$, 4, 282, true, $q$reading_shabbat_2026-09-05_G$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Lake Baikal was the single greatest obstacle to the railway's builders.", "Sergei Witte was the most influential supporter of the railway project.", "The railway was a vast undertaking that overcame great obstacles and transformed Siberia.", "Modern travelers still choose the railway mainly for the impressive scale of the journey."]$q$::jsonb, 2, $q$["לא נכון. אגם בייקל הוא דוגמה אחת לקשיים בפסקה השנייה, לא הרעיון המרכזי.", "לא נכון. ויטה נזכר במשפט אחד בפסקה הראשונה בלבד.", "נכון. הקטע מתאר את היקף הפרויקט, את הקשיים ההנדסיים ואת השפעתו על סיביר — זהו הרעיון המרכזי.", "לא נכון. זהו פרט מהמשפט האחרון בלבד."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch G, passage=transsib, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, how did trains cross Lake Baikal before the southern track was completed?$q$, $q$["They traveled over a long bridge built across the narrowest part of the lake.", "They were pulled around the northern shore of the lake by teams of horses.", "They used a series of tunnels dug beneath the lake bed.", "They were transported across the water on a purpose-built ferry."]$q$::jsonb, 3, $q$["לא נכון. הפסקה אינה מזכירה גשר על האגם.", "לא נכון. הפסקה אינה מזכירה סוסים או מסלול בחוף הצפוני.", "לא נכון. המנהרות שבפסקה נחפרו במסלול היבשתי בחוף הדרומי, לא מתחת לאגם.", "נכון. הפסקה אומרת שבמשך כמה שנים הרכבות הועברו על פני המים במעבורת שנבנתה במיוחד."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["trains were carried across its waters by a specially built ferry"]$q$::jsonb, $q$shabbat batch G, passage=transsib, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the third paragraph is to —$q$, $q$["describe the railway's effects on settlement, warfare and travel after its completion.", "explain the engineering methods used to lay track across frozen ground.", "describe the ceremony that marked the start of construction in 1891.", "compare the speed of the railway with that of horse-drawn travel across Siberia."]$q$::jsonb, 0, $q$["נכון. הפסקה מתארת את השפעת הרכבת — הגירת איכרים, חשיבות צבאית, ומסע הנוסעים כיום.", "לא נכון. הקשיים ההנדסיים הם נושא הפסקה השנייה.", "לא נכון. הטקס ב-1891 מתואר בפסקה הראשונה.", "לא נכון. הנסיעה בכרכרות נזכרת בפסקה הראשונה, והפסקה השלישית אינה עורכת השוואה כזו."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch G, passage=transsib, q3$q$, 3, true);
