  if not exists (select 1 from reading_passages where title = $q$The 1918 Influenza Pandemic$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The 1918 Influenza Pandemic$q$, $q$In the spring of 1918, as the First World War entered its final year, a new strain of influenza began to spread among soldiers and civilians. At first, the illness seemed relatively mild, and most patients recovered within a few days. A second wave that began in late summer was far deadlier, and a third wave followed in the winter of 1919. By the time the pandemic subsided, it had infected roughly a third of the world's population and killed an estimated fifty million people.

The disease became widely known as the "Spanish flu," although it did not begin in Spain. Wartime governments censored reports of illness to protect morale, whereas neutral Spain allowed its newspapers to describe the outbreak freely. As a result, readers elsewhere formed the false impression that Spain was the center of the epidemic. The name has persisted for a century despite being a product of censorship rather than of epidemiology.

One feature of the pandemic puzzled doctors at the time and still interests researchers today. Ordinary influenza is most dangerous to the very young and the very old, yet this strain killed an unusually high proportion of healthy adults in their twenties and thirties. Many victims died within days from pneumonia, which physicians could not treat because antibiotics had not yet been discovered. The virus itself was not identified until the 1930s, so doctors in 1918 were fighting an enemy they could not see.

Public health authorities responded with the tools available to them. Cities closed schools, theaters and churches, and some required residents to wear masks in public. Communities that acted early and kept restrictions in place generally suffered lower death rates than those that delayed. Decades later, scientists managed to reconstruct the virus from preserved tissue samples, giving modern researchers a clearer picture of why it had been so lethal.$q$, $q$history / medicine$q$, 5, 304, true, $q$reading_shabbat_2026-09-05_G$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["The 1918 pandemic was an unusually deadly outbreak whose name, victims and cause puzzled contemporaries.", "Spain was unfairly blamed for an epidemic that started elsewhere.", "Antibiotics would have saved most victims of the pandemic.", "Cities that closed schools and theaters early suffered fewer deaths."]$q$::jsonb, 0, $q$["נכון. הקטע מציג את היקף המגפה, את מקור שמה המטעה, את קורבנותיה הבלתי צפויים ואת מגבלות הרפואה — זהו הרעיון המרכזי.", "לא נכון. זהו נושא הפסקה השנייה בלבד.", "לא נכון. הקטע אומר שאנטיביוטיקה טרם התגלתה, אך אינו טוען שהייתה מצילה את רוב הקורבנות.", "לא נכון. זהו פרט מהפסקה האחרונה בלבד."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch G, passage=flu1918, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, why was the disease named after Spain?$q$, $q$["Because the first cases were recorded in Spanish military camps.", "Because Spanish newspapers, unlike those elsewhere, reported openly on the outbreak.", "Because Spanish doctors were the first to identify the virus responsible.", "Because the Spanish government officially asked other countries to send medical help."]$q$::jsonb, 1, $q$["לא נכון. הפסקה אומרת במפורש שהמחלה לא החלה בספרד.", "נכון. הפסקה מסבירה שממשלות לוחמות צנזרו דיווחים, ואילו ספרד הנייטרלית אפשרה לעיתוניה לדווח בחופשיות.", "לא נכון. הפסקה השלישית אומרת שהנגיף זוהה רק בשנות השלושים.", "לא נכון. הקטע אינו מזכיר בקשת עזרה מצד ספרד."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["neutral Spain allowed its newspapers to describe the outbreak freely"]$q$::jsonb, $q$shabbat batch G, passage=flu1918, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the third paragraph is to —$q$, $q$["describe the measures that cities took to slow the spread of the disease.", "explain how the pandemic's misleading name came about.", "point out an unusual feature of the pandemic and the limits of medicine at the time.", "describe the three waves in which the pandemic spread around the world."]$q$::jsonb, 2, $q$["לא נכון. אמצעי הערים מתוארים בפסקה האחרונה.", "לא נכון. מקור השם מוסבר בפסקה השנייה.", "נכון. הפסקה מצביעה על התמותה הגבוהה בקרב מבוגרים צעירים ועל כך שהרופאים לא יכלו לטפל בדלקת הריאות או לזהות את הנגיף.", "לא נכון. שלושת הגלים מתוארים בפסקה הראשונה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch G, passage=flu1918, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, what did communities that "acted early" experience?$q$, $q$["A faster return to normal economic activity than other cities.", "A sharp rise in deaths once their restrictions were finally lifted.", "Strong public protests against the closing of churches.", "Fewer deaths than places that delayed."]$q$::jsonb, 3, $q$["לא נכון. הקטע אינו מזכיר פעילות כלכלית.", "לא נכון. הקטע אינו מזכיר עלייה בתמותה לאחר הסרת ההגבלות.", "לא נכון. הקטע אינו מזכיר מחאות.", "נכון. הפסקה האחרונה אומרת שקהילות שפעלו מוקדם סבלו בדרך כלל משיעורי תמותה נמוכים יותר מאלה שהתמהמהו."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["Communities that acted early and kept restrictions in place generally suffered lower death rates"]$q$::jsonb, $q$shabbat batch G, passage=flu1918, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the first paragraph that —$q$, $q$["the later waves of the pandemic were more dangerous than the first one.", "the war ended because so many soldiers had fallen ill.", "the pandemic was confined mainly to soldiers fighting in Europe.", "doctors identified the cause of the illness during the spring of 1918."]$q$::jsonb, 0, $q$["נכון. הפסקה אומרת שהגל הראשון היה קל יחסית ואילו הגל השני היה קטלני בהרבה — מכאן שהגלים המאוחרים היו מסוכנים יותר.", "לא נכון. הפסקה אינה קושרת בין סיום המלחמה למחלה.", "לא נכון. הפסקה אומרת שהמגפה הדביקה כשליש מאוכלוסיית העולם, לא רק חיילים.", "לא נכון. הפסקה השלישית אומרת שהנגיף זוהה רק בשנות השלושים."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch G, passage=flu1918, q5$q$, 5, true);
  end if;
