do $$ declare v_pid uuid; begin

  if not exists (select 1 from reading_passages where title = $q$The Little Ice Age$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Little Ice Age$q$, $q$Between roughly 1300 and 1850, much of the Northern Hemisphere experienced a period of cooler temperatures now known as the Little Ice Age. The name, coined by an American geologist in 1939, is somewhat misleading, since the cooling was modest compared with a true ice age. Nor was the period uniformly cold: harsh decades alternated with milder ones, and different regions were affected at different times. Nevertheless, its consequences were visible across Europe, from advancing Alpine glaciers to rivers that froze solid in winter.

The cold left its mark on everyday life and even on art. The River Thames in London froze so thoroughly on several occasions that residents held fairs on the ice, complete with stalls and entertainment. In the Alps, glaciers crept forward and crushed farms and villages that had stood for generations. Vineyards in England, which had flourished in the warmer centuries before, largely disappeared. Painters such as Pieter Bruegel produced winter scenes of frozen landscapes that remain among the most famous images of the era.

Scientists still debate the causes of the cooling, and most believe that several factors combined. Solar activity declined noticeably during part of the period, especially between 1645 and 1715, when astronomers observed very few sunspots. A series of large volcanic eruptions also threw ash and gases into the atmosphere, blocking sunlight for years at a time. Changes in ocean circulation may have amplified these effects in the North Atlantic. Whatever the exact mix of causes, the Little Ice Age shows how even small shifts in climate can reshape landscapes, economies and human lives.$q$, $q$history / environment$q$, 5, 257, true, $q$reading_shabbat_2026-09-05_G$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["Why the Thames Froze Over in London", "A Cooler Age: Its Effects and Its Possible Causes", "The Sunspot Shortage of 1645 to 1715", "Pieter Bruegel and the Art of Winter"]$q$::jsonb, 1, $q$["לא נכון. קפיאת התמזה היא דוגמה אחת מהפסקה השנייה.", "נכון. הקטע מגדיר את התקופה, מתאר את השפעותיה ודן בגורמיה האפשריים — הכותרת מקיפה את כל אלה.", "לא נכון. מיעוט כתמי השמש הוא גורם אחד מבין כמה בפסקה השלישית.", "לא נכון. ברויגל נזכר במשפט אחד בלבד."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch G, passage=littleice, q1$q$, 1, true);
