  if not exists (select 1 from reading_passages where title = $q$The Halifax Explosion of 1917$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Halifax Explosion of 1917$q$, $q$On the morning of December 6, 1917, the Canadian port of Halifax was crowded with ships supporting the war in Europe. Among them was the Mont-Blanc, a French vessel loaded with thousands of tons of explosives destined for the front. As it entered the narrow channel leading to the inner harbor, it collided with a Norwegian ship, the Imo, which was heading out to sea. The impact was not especially violent, but sparks ignited flammable liquid stored on the Mont-Blanc's deck. The crew, aware of what lay below, abandoned ship and rowed desperately for the shore.

For about twenty minutes, the burning vessel drifted toward the city while curious residents gathered at windows and along the waterfront to watch. Then the cargo exploded with a force greater than any man-made blast before the atomic bomb. The shock wave flattened the northern district of the city, and a wall of water swept over the shore. Nearly two thousand people were killed, and roughly nine thousand were injured, many of them blinded by shattered glass. A railway dispatcher named Vince Coleman stayed at his post to warn an incoming train and died when the explosion struck.

Relief arrived quickly despite a blizzard that buried the ruined city in snow the following day. Trains carrying doctors, nurses and supplies set out from across Canada and from the United States, with Boston sending especially generous aid. Halifax was gradually rebuilt, and new housing replaced the devastated neighborhood. The disaster also led to lasting improvements in the handling of dangerous cargo in ports. To this day, Nova Scotia sends a large Christmas tree to Boston each year as a gesture of thanks.$q$, $q$history$q$, 4, 275, true, $q$reading_shabbat_2026-09-05_G$q$)
      returning id into v_pid;
