      values (v_pid, $q$According to the first paragraph, what caused the fire aboard the Mont-Blanc?$q$, $q$["An explosion in the engine room of the Norwegian ship.", "A deliberate act by sailors who wanted to abandon the vessel.", "Sparks from the collision that set fire to liquid on the deck.", "A lantern dropped by a crew member while the ship was still docked."]$q$::jsonb, 2, $q$["לא נכון. הפסקה אינה מזכירה פיצוץ בחדר המכונות של האימו.", "לא נכון. הצוות נטש את הספינה בגלל השריפה, לא הצית אותה.", "נכון. הפסקה אומרת שניצוצות מההתנגשות הציתו נוזל דליק שאוחסן על הסיפון.", "לא נכון. הפסקה אינה מזכירה פנס, והספינה הייתה בתנועה בתעלה."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["sparks ignited flammable liquid stored on the Mont-Blanc's deck"]$q$::jsonb, $q$shabbat batch G, passage=halifax, q1$q$, 1, true);
