      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Joseph Paxton's greenhouse experience made him the ideal architect.", "The Koh-i-Noor diamond was the most popular exhibit of 1851.", "Cheap railway excursions allowed workers to visit London.", "The Great Exhibition was a hugely successful event whose building and profits left a lasting legacy."]$q$::jsonb, 3, $q$["לא נכון. פקסטון נזכר בפסקה השנייה בלבד.", "לא נכון. היהלום נזכר כפריט אחד ברשימה, והקטע אינו אומר שהיה הפופולרי ביותר.", "לא נכון. זהו פרט אחד מהפסקה השלישית.", "נכון. הקטע מתאר את התערוכה, את הצלחתה, את מבנה הזכוכית ואת המורשת שהותירה — זהו הרעיון המרכזי."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch G, passage=crystalpalace, q1$q$, 1, true);
