      values (v_pid, $q$According to the fourth paragraph, all of the following are true EXCEPT —$q$, $q$["The Crystal Palace still stands in Hyde Park as a museum.", "Profits from the exhibition paid for land in South Kensington.", "Several museums were eventually built on the purchased land.", "The building was destroyed by fire in 1936."]$q$::jsonb, 0, $q$["נכון. זו הקביעה השגויה — הפסקה אומרת שהמבנה פורק, הועבר לדרום לונדון ונשרף ב-1936.", "לא נכון. זו קביעה נכונה על פי הפסקה הרביעית, ולכן אינה החריג המבוקש — הרווחים שימשו לרכישת קרקע בסאות' קנזינגטון.", "לא נכון. זו קביעה נכונה על פי הפסקה הרביעית, ולכן אינה החריג המבוקש — מוזיאונים למדע, לטבע ולאמנות נבנו שם.", "לא נכון. זו קביעה נכונה על פי הפסקה הרביעית, ולכן אינה החריג המבוקש — שריפה השמידה את המבנה ב-1936."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["The Crystal Palace was dismantled and rebuilt in south London"]$q$::jsonb, $q$shabbat batch G, passage=crystalpalace, q2$q$, 2, true);
