    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the first paragraph, the word "promoted" is closest in meaning to —$q$, $q$["quietly opposed", "carefully examined", "given a higher rank", "actively supported"]$q$::jsonb, 3, $q$["לא נכון. המילה היא ההפך מהתנגדות.", "לא נכון. המילה אינה מתארת בדיקה.", "לא נכון. זו משמעות אחרת של המילה (קידום בדרגה) שאינה מתאימה להקשר של רעיון.", "נכון. 'promoted' כאן פירושו קידם ותמך באופן פעיל — הנסיך אלברט והנרי קול דחפו את רעיון התערוכה."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["The idea was promoted by Prince Albert"]$q$::jsonb, $q$shabbat batch G, passage=crystalpalace, q5$q$, 5, true);
