  if not exists (select 1 from reading_passages where title = $q$The Suez Canal$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Suez Canal$q$, $q$For centuries, ships sailing between Europe and Asia had to travel around the southern tip of Africa, a voyage of many months. The idea of cutting a canal across the Egyptian isthmus separating the Mediterranean and the Red Sea was ancient, but it was not realized until the nineteenth century. The French diplomat Ferdinand de Lesseps obtained permission from Egypt's ruler in 1854 and founded a company to raise the necessary funds. Construction began in 1859, and the canal was opened with elaborate ceremonies in November 1869.

Digging a waterway of more than 160 kilometers through desert required a labor force of enormous size. In the early years, Egyptian peasants were compelled to work on the project, a practice that drew international criticism and was eventually abandoned. Steam-powered dredging machines then took over much of the heavy work, greatly speeding construction. Unlike many canals, the Suez route required no locks, because the two seas lie at almost the same level. When completed, it shortened the journey from London to India by thousands of kilometers.

The canal's commercial importance soon made it a focus of international rivalry. In 1875, Britain purchased Egypt's shares in the company, and British troops occupied the country a few years later, partly to protect the route to India. In 1956, the Egyptian president Gamal Abdel Nasser nationalized the canal, provoking a military intervention by Britain, France and Israel that ended under pressure from the United States. The waterway was closed for eight years after the war of 1967 and reopened in 1975. It remains one of the busiest shipping lanes in the world, as the six-day blockage caused by a grounded container ship in 2021 clearly demonstrated.$q$, $q$history / economics$q$, 5, 272, true, $q$reading_shabbat_2026-09-05_G$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["The Suez Canal: A Shortcut That Reshaped Trade and Politics", "Ferdinand de Lesseps and the Company He Founded", "How Britain Gained Control of Egypt in 1882", "The Six-Day Blockage of 2021 and Its Lessons for Shipping"]$q$::jsonb, 0, $q$["נכון. הקטע מתאר את בניית התעלה, את תרומתה למסחר ואת המאבקים הפוליטיים סביבה — הכותרת מקיפה את כולם.", "לא נכון. דה לספס נזכר בפסקה הראשונה בלבד.", "לא נכון. הכיבוש הבריטי נזכר במשפט אחד בפסקה השלישית.", "לא נכון. החסימה ב-2021 נזכרת רק במשפט האחרון."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch G, passage=suez, q1$q$, 1, true);
