  if not exists (select 1 from reading_passages where title = $q$The Berlin Airlift$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Berlin Airlift$q$, $q$After the Second World War, Germany was divided into four zones controlled by the United States, Britain, France and the Soviet Union. The capital, Berlin, lay deep inside the Soviet zone, but the city itself was also split into four sectors. In June 1948, the Soviet authorities closed all roads, railways and canals leading from the western zones into West Berlin. Their goal was to force the Western powers out of the city by cutting off food, fuel and other supplies to its two million residents.

The Western allies faced a difficult choice. Sending troops along the closed roads risked starting a new war, while abandoning the city would hand the Soviets a major victory. Instead, they decided to supply West Berlin entirely by air, using three narrow flight corridors that earlier agreements had guaranteed. Few experts believed that aircraft could deliver enough food and coal to keep a large city alive through the winter.

The operation that followed became one of the largest logistical efforts in history. American and British planes landed in Berlin around the clock, at busy times touching down every few minutes. Coal made up the largest share of the cargo, since the city needed fuel for heating and electricity as well as food. One American pilot began dropping small parcels of candy attached to tiny parachutes for the children who watched the planes, and the practice spread to other crews. By the spring of 1949, the airlift was delivering more supplies each day than had arrived by land before the blockade.

The Soviets lifted the blockade in May 1949, after nearly eleven months. Flights continued for several more months to build up reserves in case the closure was repeated. The airlift had delivered more than two million tons of supplies, and it turned former enemies into partners. Within weeks of its end, the Western nations formed a new military alliance, and the division of Germany into two separate states became permanent.$q$, $q$history$q$, 3, 323, true, $q$reading_shabbat_2026-09-05_G$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, what was the Soviet aim in closing the routes into West Berlin?$q$, $q$["To punish the residents of Berlin for supporting the Western powers.", "To drive the Western powers out of the city by starving it of supplies.", "To prevent Western troops from entering the Soviet zone of Germany.", "To force the Western nations to hand over their zones of Germany."]$q$::jsonb, 1, $q$["לא נכון. הפסקה אינה מזכירה ענישה של התושבים.", "נכון. הפסקה אומרת שמטרת הסובייטים הייתה להכריח את המעצמות המערביות לצאת מהעיר על ידי ניתוק המזון, הדלק והאספקה.", "לא נכון. הפסקה מדברת על ניתוק העיר, לא על מניעת כניסת חיילים לאזור הסובייטי.", "לא נכון. הפסקה אינה מזכירה דרישה למסור את האזורים המערביים של גרמניה."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Their goal was to force the Western powers out of the city by cutting off food, fuel and other supplies"]$q$::jsonb, $q$shabbat batch G, passage=berlinairlift, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the third paragraph, all of the following are true EXCEPT —$q$, $q$["Planes landed in Berlin at all hours of the day and night.", "Coal was the largest single item carried by the aircraft.", "Food made up most of the cargo because the city's power stations had closed.", "By spring 1949, air deliveries exceeded the earlier land deliveries."]$q$::jsonb, 2, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — המטוסים נחתו מסביב לשעון.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — פחם היווה את החלק הגדול ביותר מהמטען.", "נכון. זו הקביעה השגויה — הפסקה אומרת שפחם, לא מזון, היה עיקר המטען, ואינה מזכירה סגירת תחנות כוח.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — באביב 1949 הרכבת האווירית סיפקה יותר מכפי שהגיע ביבשה לפני המצור."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Coal made up the largest share of the cargo"]$q$::jsonb, $q$shabbat batch G, passage=berlinairlift, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, what did "one American pilot" begin doing?$q$, $q$["Flying extra missions at night to speed up the delivery of coal.", "Training German children to help unload the aircraft.", "Carrying letters from Berliners to their relatives in the west.", "Dropping sweets on tiny parachutes for children."]$q$::jsonb, 3, $q$["לא נכון. הקטע אינו מזכיר טיסות לילה נוספות.", "לא נכון. הילדים צפו במטוסים, ולא עבדו בפריקה.", "לא נכון. הקטע אינו מזכיר מכתבים.", "נכון. הפסקה השלישית אומרת שטייס אמריקאי החל להצניח חבילות ממתקים קטנות במצנחים זעירים לילדים."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["One American pilot began dropping small parcels of candy attached to tiny parachutes"]$q$::jsonb, $q$shabbat batch G, passage=berlinairlift, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["explain why the Western allies chose to supply the city by air.", "describe how Germany was divided after the war.", "describe the daily operation of the airlift.", "explain what happened after the blockade was lifted in 1949."]$q$::jsonb, 0, $q$["נכון. הפסקה מציגה את הדילמה — סיכון מלחמה מול ויתור על העיר — ומסבירה מדוע נבחרה האספקה מהאוויר.", "לא נכון. חלוקת גרמניה מתוארת בפסקה הראשונה.", "לא נכון. הפעילות היומיומית מתוארת בפסקה השלישית.", "לא נכון. סיום המצור מתואר בפסקה האחרונה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch G, passage=berlinairlift, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the passage, what can be inferred about the outcome of the blockade?$q$, $q$["The Soviets achieved their main goal, since Germany was permanently divided.", "The blockade failed and strengthened cooperation between the Western nations and West Berliners.", "Soviet forces eventually allowed the Western powers to use the roads again in exchange for coal.", "The Western allies abandoned the airlift as soon as the blockade ended."]$q$::jsonb, 1, $q$["לא נכון. מטרת הסובייטים הייתה להוציא את המערב מברלין, וזה לא קרה.", "נכון. המערב נשאר בעיר, המצור הוסר, והקטע אומר שהרכבת האווירית הפכה אויבים לשעבר לשותפים והובילה לברית צבאית חדשה.", "לא נכון. הקטע אינו מזכיר עסקה כלשהי תמורת פחם.", "לא נכון. הפסקה האחרונה אומרת שהטיסות נמשכו עוד כמה חודשים כדי לצבור מלאי."]$q$::jsonb, $q$inference$q$, $q$text$q$, null, $q$shabbat batch G, passage=berlinairlift, q5$q$, 5, true);
  end if;
