do $$ declare v_pid uuid; begin

  if not exists (select 1 from reading_passages where title = $q$John Snow and the Broad Street Pump$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$John Snow and the Broad Street Pump$q$, $q$In the late summer of 1854, a violent outbreak of cholera struck the Soho district of London, killing more than five hundred people within a few weeks. At the time, most physicians believed that the disease spread through miasma, a poisonous vapor that supposedly rose from rotting waste and sewage. John Snow, a doctor who had already studied earlier epidemics, rejected this explanation and suspected that contaminated drinking water was the real culprit. Instead of relying on theory alone, he walked the neighborhood and recorded the home address of every victim on a street map.

The pattern that emerged was striking, since the deaths clustered tightly around a single public water pump on Broad Street. Snow also noticed several curious exceptions that strengthened his argument rather than weakening it. Workers at a nearby brewery, who drank mostly beer and had their own water supply, remained almost entirely healthy. Residents of a local workhouse, which drew water from a private well, were similarly spared. Snow presented his evidence to the parish authorities, who agreed to remove the pump handle on September 8. The outbreak, which was probably already declining by then, ended soon afterward.

Although Snow's theory was not fully accepted during his lifetime, later investigation confirmed his suspicion. A local clergyman named Henry Whitehead discovered that the well had been dug only a few feet away from an old cesspit. Waste from a sick infant had leaked into the water shortly before the first cases appeared. Today Snow's map is regarded as a founding document of epidemiology, the science of how diseases spread through populations. His method, which combined careful observation with simple geography, remains a model for public health investigators around the world.$q$, $q$medicine / history$q$, 4, 282, true, $q$reading_shabbat_2026-09-05_H$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["By mapping cholera deaths, John Snow showed that contaminated water, not bad air, spread the disease.", "The miasma theory of disease was widely accepted by London physicians in the 1850s.", "Henry Whitehead discovered that a cesspit had contaminated the Broad Street well.", "Workers at a brewery in Soho avoided cholera because they drank beer instead of water."]$q$::jsonb, 0, $q$["נכון. הקטע כולו עוסק בדרך שבה סנואו מיפה את מקרי המוות והוכיח שמים מזוהמים, ולא אוויר רע, הפיצו את הכולרה.", "לא נכון. זו קביעה נכונה מהפסקה הראשונה, אך היא רק הרקע לסיפור ולא הרעיון המרכזי של הקטע.", "לא נכון. זו קביעה נכונה מהפסקה השלישית, אך היא פרט אחד שמאשר את התיאוריה ולא הרעיון המרכזי.", "לא נכון. זו קביעה נכונה מהפסקה השנייה, אך היא דוגמה אחת בלבד מתוך הראיות של סנואו."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch H, passage=snow-pump, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, all of the following are true EXCEPT —$q$, $q$["Workers at a nearby brewery who drank mostly beer stayed largely healthy.", "The parish authorities ignored Snow's evidence.", "Residents of a workhouse that used a private well were mostly unaffected.", "The recorded deaths were concentrated around one public pump on Broad Street."]$q$::jsonb, 1, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — עובדי מבשלת הבירה אכן נשארו בריאים כמעט לחלוטין.", "נכון. זו הקביעה השגויה — הפסקה כותבת שרשויות הקהילה הסכימו להסיר את ידית המשאבה, כלומר הן קיבלו את הראיות של סנואו ולא התעלמו מהן.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — דיירי בית המחסה עם הבאר הפרטית אכן ניצלו.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — מקרי המוות אכן התרכזו סביב משאבה אחת ברחוב ברוד."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Snow presented his evidence to the parish authorities, who agreed to remove the pump handle"]$q$::jsonb, $q$shabbat batch H, passage=snow-pump, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the third paragraph is to —$q$, $q$["describe how Snow recorded the address of each cholera victim on a map.", "explain why most doctors of the period believed in the miasma theory.", "show that later evidence confirmed Snow's theory and secured his lasting reputation.", "describe the exceptions, such as the brewery, that supported Snow's argument."]$q$::jsonb, 2, $q$["לא נכון. זהו תוכן הפסקה הראשונה — מיפוי כתובות הקורבנות — ולא הפסקה השלישית.", "לא נכון. תיאוריית המיאזמה מוזכרת בפסקה הראשונה, והפסקה השלישית אינה מסבירה מדוע האמינו בה.", "נכון. הפסקה מתארת את גילויו של וייטהד שאישר את החשד, ואת מעמדה של המפה כמסמך מכונן באפידמיולוגיה.", "לא נכון. זהו תוכן הפסקה השנייה — מבשלת הבירה ובית המחסה — ולא הפסקה השלישית."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=snow-pump, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the statement that the outbreak "was probably already declining by then," what can be inferred?$q$, $q$["Snow's map was drawn several weeks after the last death had occurred.", "The authorities removed the handle only because the epidemic was over.", "The pump handle was removed too late to have any effect at all.", "Removing the pump handle was probably not the only reason the outbreak came to an end."]$q$::jsonb, 3, $q$["לא נכון. הקטע אינה מציין מתי בדיוק צוירה המפה, ומהמשפט אי אפשר להסיק זאת.", "לא נכון. הפסקה אומרת שהרשויות פעלו בעקבות הראיות של סנואו, לא משום שהמגפה הסתיימה.", "לא נכון. זו הגזמה — המשפט אומר שההתפרצות כבר דעכה, לא שלהסרת הידית לא הייתה שום השפעה.", "נכון. אם ההתפרצות כבר דעכה לפני הסרת הידית, ניתן להסיק שהסרתה לא הייתה בהכרח הסיבה היחידה לסיום המגפה."]$q$::jsonb, $q$inference$q$, $q$anchor$q$, $q$["which was probably already declining by then"]$q$::jsonb, $q$shabbat batch H, passage=snow-pump, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the first paragraph, the word "culprit" most nearly means —$q$, $q$["the cause of the harm", "an experimental medical treatment", "a widely accepted scientific theory about disease", "a poisonous vapor"]$q$::jsonb, 0, $q$["נכון. 'culprit' פירושו האשם או הגורם לנזק — סנואו חשד שמי השתייה המזוהמים הם הגורם האמיתי למחלה.", "לא נכון. המילה אינה מתארת טיפול רפואי; המשפט עוסק בגורם למחלה.", "לא נכון. המילה אינה מתארת תיאוריה; היא מתארת את מה שסנואו חשד שגורם למחלה בפועל.", "לא נכון. האדים הרעילים הם חלק מתיאוריית המיאזמה שסנואו דחה, ולא פירוש המילה."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["culprit"]$q$::jsonb, $q$shabbat batch H, passage=snow-pump, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$The Discovery of Surgical Anesthesia$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Discovery of Surgical Anesthesia$q$, $q$Before the middle of the nineteenth century, surgery was an ordeal that patients endured while fully awake. Surgeons prized speed above all else, and the most admired among them could remove a limb in under a minute. Alcohol, opium, and simple physical restraint were the only tools available to reduce a patient's agony, and many people chose to die from their illnesses rather than face the knife.

The breakthrough came in Boston on October 16, 1846. William Morton, a young dentist, had been experimenting with ether, a volatile liquid whose vapor produced unconsciousness when inhaled. He persuaded the senior surgeon John Collins Warren to let him test it publicly at Massachusetts General Hospital. Morton administered the ether through a glass device to a patient named Gilbert Abbott, and Warren then removed a tumor from the man's neck. Abbott remained still throughout and later reported that he had felt no pain. According to witnesses, Warren then turned to the audience and declared that the demonstration was no humbug.

News of the operation spread with remarkable speed for the era. Within two months, surgeons in London were using ether, and the practice soon reached hospitals across Europe. However, the question of who deserved credit for the discovery quickly turned bitter. Morton attempted to patent the substance under the name Letheon, hoping to profit from its use, but the disguise fooled nobody. A Georgia physician, Crawford Long, had quietly used ether during operations as early as 1842, although he did not publish his results until 1849.

The dispute consumed Morton's remaining years, and he died in 1868 without ever receiving the fortune he expected. Nevertheless, the demonstration he arranged transformed medicine permanently. Surgeons could now work slowly and carefully inside the body, making possible operations that would once have been unthinkable. The room where the operation took place is still preserved at the hospital and is known today as the Ether Dome.$q$, $q$medicine / history$q$, 5, 314, true, $q$reading_shabbat_2026-09-05_H$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["Crawford Long: The Forgotten Pioneer of Ether", "The Public Demonstration That Ended Pain in Surgery", "Why Surgeons of the Nineteenth Century Valued Speed Above Everything", "The Ether Dome: A Preserved Room in a Boston Hospital"]$q$::jsonb, 1, $q$["לא נכון. קרופורד לונג מוזכר בפסקה השלישית בלבד כפרט במחלוקת על הקרדיט, ולא כנושא הקטע.", "נכון. הקטע כולו סובב סביב ההדגמה הפומבית של מורטון ב-1846 והשינוי שהביאה לניתוחים.", "לא נכון. זו קביעה נכונה מהפסקה הראשונה, אך היא הרקע בלבד ולא הנושא של הקטע כולו.", "לא נכון. החדר המשומר מוזכר רק במשפט האחרון של הקטע, ואינו הנושא המרכזי."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch H, passage=ether-1846, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, what happened after Morton administered the ether?$q$, $q$["The patient woke up screaming halfway through the operation.", "Warren refused to operate until the patient confirmed he was unconscious.", "Warren removed a growth from the patient's neck while he lay still and painless.", "The audience left the room in protest, calling the demonstration a fraud."]$q$::jsonb, 2, $q$["לא נכון. הפסקה השנייה כותבת שאבוט נשאר ללא תנועה ודיווח שלא חש כאב.", "לא נכון. הפסקה אינה מזכירה סירוב כלשהו של וורן או אישור מצד המטופל.", "נכון. הפסקה מספרת שוורן הסיר גידול מצווארו של המטופל, שנשאר ללא תנועה ולא חש כאב.", "לא נכון. לפי הפסקה, וורן פנה לקהל והכריז שההדגמה אינה הונאה — ההפך מהאפשרות הזו."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=ether-1846, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, why did Morton call the substance "Letheon"?$q$, $q$["because ether was considered too dangerous to name openly", "because Crawford Long had already claimed the name", "because hospitals demanded a more scientific-sounding name", "to disguise it and make money"]$q$::jsonb, 3, $q$["לא נכון. הפסקה השלישית אינה מזכירה שהאתר נחשב מסוכן מכדי לנקוב בשמו.", "לא נכון. הפסקה מזכירה את לונג רק כמי שהשתמש באתר לפני מורטון, לא כמי שתבע בעלות על השם.", "לא נכון. הפסקה אינה מזכירה דרישה כלשהי של בתי חולים.", "נכון. הפסקה השלישית כותבת שמורטון ניסה לרשום פטנט על החומר בשם לתיאון בתקווה להרוויח, וש'התחפושת' לא הטעתה איש."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["patent the substance under the name Letheon, hoping to profit from its use"]$q$::jsonb, $q$shabbat batch H, passage=ether-1846, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the first paragraph is to —$q$, $q$["describe the brutal conditions of surgery before anesthesia existed.", "explain how Morton persuaded Warren to allow a public test of ether.", "describe the bitter dispute over credit that followed the discovery.", "explain why the operating room is now called the Ether Dome."]$q$::jsonb, 0, $q$["נכון. הפסקה הראשונה מתארת את הניתוחים האכזריים שנערכו בזמן שהמטופלים ערים לחלוטין, לפני המצאת ההרדמה.", "לא נכון. זהו תוכן הפסקה השנייה — ההדגמה בבוסטון — ולא הפסקה הראשונה.", "לא נכון. זהו תוכן הפסקה השלישית — המחלוקת על הקרדיט — ולא הפסקה הראשונה.", "לא נכון. שם החדר מוזכר בפסקה האחרונה, לא בראשונה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=ether-1846, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the third paragraph, the word "bitter" is closest in meaning to —$q$, $q$["sharp in taste", "full of anger and resentment", "extremely cold", "sad but calm"]$q$::jsonb, 1, $q$["לא נכון. כאן המילה מתארת מחלוקת, לא טעם.", "נכון. 'bitter' בהקשר של מחלוקת פירושו מלא כעס ומרירות — המאבק על הקרדיט הפך למר ועוין.", "לא נכון. המילה אינה מתארת טמפרטורה בהקשר הזה.", "לא נכון. מחלוקת מרה אינה רגועה; ההפך הוא הנכון."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["quickly turned bitter"]$q$::jsonb, $q$shabbat batch H, passage=ether-1846, q5$q$, 5, true);
