  if not exists (select 1 from reading_passages where title = $q$Karl Landsteiner and Blood Types$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Karl Landsteiner and Blood Types$q$, $q$For centuries, doctors who attempted to transfer blood from one person to another faced a mystery. Some patients recovered dramatically after receiving blood, while others suffered fever, shock, and death within hours. The procedure seemed to work by chance, and by the late nineteenth century many physicians had abandoned it as too dangerous. Nobody understood why the same treatment could save one patient and kill the next.

In 1901, Karl Landsteiner, a young Austrian physician working in Vienna, found the answer. He drew blood from himself and from several colleagues, separated the fluid serum from the red cells, and then mixed samples from different people together. In some combinations the red cells clumped together, whereas in others they remained evenly suspended. Landsteiner concluded that human blood falls into distinct groups, which he initially labeled A, B, and C. The third group was later renamed O, and a fourth group, AB, was identified by two of his colleagues the following year. Mixing incompatible groups caused clumping, which explained why so many earlier transfusions had failed.

The practical consequences of this discovery were enormous, although they took time to arrive. Within a few years, doctors began testing blood compatibility before transfusions, and the death rate from the procedure fell sharply. During the First World War, the ability to store matched blood saved countless wounded soldiers. Landsteiner received the Nobel Prize in Medicine in 1930, and nearly four decades after his original work he helped identify the Rh factor as well. Today his birthday, June 14, is celebrated around the world as World Blood Donor Day.$q$, $q$medicine / biology$q$, 5, 260, true, $q$reading_shabbat_2026-09-05_H$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Doctors in the nineteenth century abandoned transfusions because they were too risky.", "World Blood Donor Day honors the birthday of a famous Austrian physician.", "Landsteiner's discovery of blood groups explained transfusion failures and made the procedure safe.", "Storing matched blood during the First World War saved the lives of many wounded soldiers."]$q$::jsonb, 2, $q$["לא נכון. זו קביעה נכונה מהפסקה הראשונה, אך היא רק הרקע לתגלית ולא הרעיון המרכזי.", "לא נכון. זהו פרט מהמשפט האחרון של הקטע, ולא הרעיון המרכזי.", "נכון. הקטע כולו עוסק בתגלית של לנדשטיינר — סוגי הדם — ובאופן שבו היא הסבירה את הכישלונות והפכה עירויים לבטוחים.", "לא נכון. זו קביעה נכונה מהפסקה השלישית, אך היא תוצאה אחת בלבד של התגלית."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch H, passage=blood-types, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Which of the following is NOT mentioned in the second paragraph?$q$, $q$["Landsteiner used his own blood in the experiments.", "Two of Landsteiner's colleagues identified the AB group.", "Group C was later given the name O.", "Landsteiner received a prize for the discovery."]$q$::jsonb, 3, $q$["לא נכון. הפסקה השנייה מציינת במפורש שלנדשטיינר לקח דם מעצמו ומעמיתיו, ולכן פרט זה מוזכר.", "לא נכון. הפסקה השנייה מציינת ששני עמיתים זיהו את קבוצה AB בשנה שלאחר מכן, ולכן פרט זה מוזכר.", "לא נכון. הפסקה השנייה מציינת שהקבוצה השלישית נקראה מאוחר יותר O, ולכן פרט זה מוזכר.", "נכון. פרס נובל מוזכר בפסקה השלישית בלבד; הפסקה השנייה אינה מזכירה פרס כלשהו. למה לשים לב: השאלה מוגבלת לפסקה השנייה."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=blood-types, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the first paragraph is to —$q$, $q$["present the long-standing medical puzzle that Landsteiner's research would eventually solve.", "describe the experiment in which blood samples were mixed together.", "explain how compatibility testing lowered the death rate from transfusions.", "describe the honors that Landsteiner received late in his life."]$q$::jsonb, 0, $q$["נכון. הפסקה הראשונה מציגה את התעלומה — מדוע עירויים הצילו חולה אחד והרגו אחר — שהמחקר של לנדשטיינר פתר בהמשך.", "לא נכון. זהו תוכן הפסקה השנייה — הניסוי עם ערבוב הדגימות — ולא הפסקה הראשונה.", "לא נכון. זהו תוכן הפסקה השלישית — ירידת שיעור התמותה — ולא הפסקה הראשונה.", "לא נכון. פרס נובל ויום תורמי הדם מוזכרים בפסקה השלישית, לא בראשונה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=blood-types, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the third paragraph that —$q$, $q$["compatibility testing was adopted immediately after Landsteiner published his findings.", "the significance of Landsteiner's findings was recognized only gradually over time.", "the Rh factor was identified before the ABO groups.", "the Nobel Prize was awarded to Landsteiner in the same year as his discovery."]$q$::jsonb, 1, $q$["לא נכון. הפסקה כותבת שהתוצאות 'לקחו זמן להגיע' ושבדיקות ההתאמה החלו 'בתוך שנים אחדות', לא מיד.", "נכון. הפסקה מציינת שההשלכות המעשיות הגיעו באיטיות, ושפרס נובל הוענק רק ב-1930 — כמעט שלושים שנה אחרי התגלית — ולכן ההכרה הייתה הדרגתית.", "לא נכון. הפסקה אומרת שגורם Rh זוהה כמעט ארבעה עשורים אחרי העבודה המקורית על סוגי הדם, כלומר אחריה ולא לפניה.", "לא נכון. התגלית הייתה ב-1901 והפרס הוענק ב-1930, לפי הפסקאות השנייה והשלישית."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=blood-types, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the sentence "Mixing incompatible groups caused clumping, which explained why so many earlier transfusions had failed," the word "which" refers to —$q$, $q$["the earlier transfusions", "the incompatible groups", "the clumping of red cells", "the failure"]$q$::jsonb, 2, $q$["לא נכון. העירויים המוקדמים הם מה שהוסבר, לא מה שמסביר.", "לא נכון. הקבוצות הבלתי תואמות הן הגורם להצטברות, אך המילה 'which' מתייחסת לתוצאה שהוסברה במשפט — ההצטברות.", "נכון. 'which' מתייחס להצטברות (clumping) של תאי הדם — היא זו שהסבירה מדוע עירויים רבים נכשלו.", "לא נכון. הכישלון הוא מה שהוסבר, ולא הדבר שהמילה מתייחסת אליו."]$q$::jsonb, $q$reference_word$q$, $q$anchor$q$, $q$["Mixing incompatible groups caused clumping, which explained why so many earlier transfusions had failed"]$q$::jsonb, $q$shabbat batch H, passage=blood-types, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$James Lind and the Cure for Scurvy$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$James Lind and the Cure for Scurvy$q$, $q$During the age of sail, scurvy was the greatest killer of sailors on long ocean voyages. After a few months at sea, men developed swollen gums, loose teeth, old wounds that reopened, and a weakness so severe that they could barely stand. On some expeditions the disease killed far more men than storms or enemy action. Doctors offered dozens of explanations, blaming damp air, laziness, or bad digestion, yet none of their remedies worked.

In 1747, James Lind, a surgeon aboard the British warship Salisbury, decided to test the remedies systematically. He selected twelve sailors suffering from scurvy and divided them into six pairs, giving each pair a different treatment. The options included cider, vinegar, seawater, a dilute acid, a medicinal paste, and two oranges with one lemon daily. Within a week, the two men who had eaten the citrus fruit were nearly fit for duty, while the others showed little improvement. Lind's experiment is now often described as the first controlled clinical trial in the history of medicine.

Surprisingly, the discovery did not lead to an immediate change in naval practice. Lind himself never fully grasped why the fruit worked, and he recommended a boiled concentrate that destroyed most of its curative power. Nearly fifty years passed before the Royal Navy, in 1795, ordered a regular ration of lemon juice for its crews. Scurvy soon vanished from British ships, and the sailors acquired the nickname limeys from the citrus they were made to drink. The true explanation, a deficiency of vitamin C, was not established until the twentieth century.$q$, $q$medicine / history$q$, 4, 258, true, $q$reading_shabbat_2026-09-05_H$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, how did Lind organize his experiment?$q$, $q$["He gave all twelve sailors citrus fruit and compared them with healthy crew members.", "He tested one remedy on each sailor over several months.", "He allowed each sailor to choose the treatment he preferred from a list of six.", "He split the sick sailors into pairs, with each pair receiving a different remedy."]$q$::jsonb, 3, $q$["לא נכון. רק זוג אחד קיבל פירות הדר, והשוואה הייתה בין החולים לבין עצמם, לא מול אנשי צוות בריאים.", "לא נכון. הפסקה מתארת ניסוי שנמשך כשבוע, עם זוגות של מלחים ולא מלח בודד לכל תרופה.", "לא נכון. הפסקה אינה מזכירה בחירה של המלחים; לינד הוא שחילק את הטיפולים.", "נכון. הפסקה מספרת שלינד חילק שנים עשר מלחים חולים לשישה זוגות ונתן לכל זוג טיפול שונה."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=lind-scurvy, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, why did Lind's "boiled concentrate" fail to help sailors?$q$, $q$["Heating the fruit juice destroyed most of its healing properties before it was consumed.", "The Royal Navy refused to pay for the expensive concentrate.", "Sailors disliked its taste and threw it overboard.", "The concentrate was made from limes rather than lemons."]$q$::jsonb, 0, $q$["נכון. הפסקה השלישית כותבת שהתרכיז המבושל איבד את רוב כוחו המרפא — כלומר החימום הרס את התכונות המועילות.", "לא נכון. הפסקה אינה מזכירה סירוב של הצי לשלם עבור התרכיז.", "לא נכון. הפסקה אינה מזכירה את טעם התרכיז או השלכתו לים.", "לא נכון. ליים מוזכר רק בהקשר של הכינוי 'limeys', לא כסיבה לכישלון התרכיז."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["a boiled concentrate that destroyed most of its curative power"]$q$::jsonb, $q$shabbat batch H, passage=lind-scurvy, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the first paragraph is to —$q$, $q$["explain why Lind chose twelve sailors for his experiment.", "describe how serious scurvy was and how poorly it was understood.", "describe the Royal Navy's decision to issue lemon juice to every crew in 1795.", "explain the role of vitamin C in preventing disease."]$q$::jsonb, 1, $q$["לא נכון. הניסוי של לינד מתואר בפסקה השנייה, והפסקה הראשונה אינה מסבירה את בחירת המשתתפים.", "נכון. הפסקה הראשונה מתארת את התסמינים הקשים, את מספר ההרוגים ואת ההסברים השגויים של הרופאים — כלומר את חומרת המחלה ואת חוסר ההבנה שלה.", "לא נכון. זהו תוכן הפסקה השלישית — החלטת הצי ב-1795 — ולא הפסקה הראשונה.", "לא נכון. ויטמין C מוזכר רק במשפט האחרון של הקטע, ולא בפסקה הראשונה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=lind-scurvy, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the passage, what can be inferred about medical progress in the eighteenth century?$q$, $q$["Naval surgeons had no authority to conduct experiments at sea.", "Experiments were usually accepted by the authorities within a few years.", "A remedy could be proven to work long before anyone understood why.", "Doctors already knew about vitamins but could not produce them."]$q$::jsonb, 2, $q$["לא נכון. לינד עצמו היה מנתח ימי שערך ניסוי בים, ולכן ההיפך נכון.", "לא נכון. הקטע כותב שחלפו כמעט חמישים שנה עד שהצי אימץ את המסקנה, לא שנים אחדות.", "נכון. הניסוי הוכיח ב-1747 שפירות הדר מרפאים צפדינה, אך ההסבר האמיתי — מחסור בוויטמין C — התברר רק במאה העשרים.", "לא נכון. הקטע אומר שהסבר הוויטמין נקבע רק במאה העשרים, ולכן רופאי המאה השמונה עשרה לא ידעו עליו."]$q$::jsonb, $q$inference$q$, $q$text$q$, null, $q$shabbat batch H, passage=lind-scurvy, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the third paragraph, the word "grasped" is closest in meaning to —$q$, $q$["held tightly in the hand", "openly admitted", "carefully measured", "understood"]$q$::jsonb, 3, $q$["לא נכון. זהו הפירוש המילולי של המילה, אך כאן היא משמשת במובן מופשט — תפיסה שכלית.", "לא נכון. המילה אינה עוסקת בהודאה פומבית.", "לא נכון. המילה אינה עוסקת במדידה.", "נכון. 'grasped' כאן פירושו הבין — לינד מעולם לא הבין לגמרי מדוע הפרי עוזר."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["never fully grasped"]$q$::jsonb, $q$shabbat batch H, passage=lind-scurvy, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$The Radium Girls$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Radium Girls$q$, $q$In the years around the First World War, glowing watch dials became a popular novelty in the United States. The glow came from paint mixed with radium, a radioactive element discovered by Marie and Pierre Curie in 1898. Factories in New Jersey, Connecticut, and Illinois hired young women to paint the tiny numbers on the dials by hand. The work paid well by the standards of the time and was considered clean, skilled, and even glamorous.

To keep their brushes sharp, the workers were instructed to shape the bristles between their lips before each stroke. Supervisors assured them that the paint was completely harmless, and some women playfully painted their nails and teeth to glow in the dark. Yet the company's own chemists handled the same material behind lead screens and with protective tools. Every time a painter pointed her brush, she swallowed a small amount of radium, which the body stores in bone much like calcium.

Within a few years, the painters began to suffer mysterious illnesses. Their teeth fell out, their jaws crumbled, and several developed anemia and bone cancer. Company doctors initially blamed other causes, and the firms denied any link to radium. In 1927, a group of five New Jersey workers, led by Grace Fryer, sued their employer, and the case attracted national attention. Although the women were already gravely ill, they reached a settlement the following year.

The legal battle had consequences far beyond the dial-painting industry. It helped establish the principle that workers could sue employers for diseases caused by their jobs. Scientists later drew on the painters' medical records to set safety limits for radiation exposure. The story of the radium girls is now remembered as a turning point in the history of occupational health.$q$, $q$medicine / history$q$, 5, 290, true, $q$reading_shabbat_2026-09-05_H$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["How the Radium Girls Changed Workplace Safety", "Marie Curie's Discovery of Radium", "Why Glowing Watch Dials Became Popular", "Grace Fryer's Lawsuit Against Her Employer"]$q$::jsonb, 0, $q$["נכון. הקטע עוקב אחרי סיפורן של הצבעיות מתחילת העבודה ועד להשפעת המאבק המשפטי על בטיחות העובדים.", "לא נכון. תגלית הרדיום מוזכרת במשפט אחד בפסקה הראשונה כרקע בלבד.", "לא נכון. הפופולריות של השעונים הזוהרים היא הרקע בפסקה הראשונה, לא הנושא של הקטע.", "לא נכון. התביעה של גרייס פרייר היא אירוע אחד בפסקה השלישית, ולא הרעיון המרכזי של הקטע כולו."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch H, passage=radium-girls, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, all of the following are true EXCEPT —$q$, $q$["The painters were told to shape their brushes with their lips.", "The company's chemists worked with radium without any protection.", "Some women painted their nails and teeth with the paint.", "Radium is stored in the bones in a manner similar to calcium."]$q$::jsonb, 1, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — העובדות אכן הונחו לחדד את המכחול בשפתיים.", "נכון. זו הקביעה השגויה — הפסקה כותבת שהכימאים של החברה עבדו מאחורי מגני עופרת ועם כלי מגן, כלומר דווקא עם הגנה.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — חלק מהנשים אכן צבעו ציפורניים ושיניים.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — הגוף אכן אוגר רדיום בעצמות כמו סידן."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=radium-girls, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the third paragraph is to —$q$, $q$["describe the safety precautions that the company's own chemists used behind lead screens.", "explain the lasting legal principle that the case established.", "describe the painters' illnesses and their decision to take legal action.", "describe how radium was discovered and used in paint."]$q$::jsonb, 2, $q$["לא נכון. אמצעי ההגנה של הכימאים מוזכרים בפסקה השנייה, לא בשלישית.", "לא נכון. העיקרון המשפטי המתמשך מוסבר בפסקה האחרונה, לא בשלישית.", "נכון. הפסקה השלישית מתארת את המחלות המסתוריות של הצבעיות ואת התביעה שהגישו ב-1927.", "לא נכון. תגלית הרדיום והשימוש בו בצבע מתוארים בפסקה הראשונה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=radium-girls, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["explain why the lawsuit was settled rather than decided in court.", "describe the symptoms that the dial painters suffered.", "describe the popularity of glowing watches in the 1920s.", "show the broader impact of the case on workers' rights and safety."]$q$::jsonb, 3, $q$["לא נכון. הפשרה מוזכרת בסוף הפסקה השלישית, והקטע אינו מסביר מדוע נבחרה פשרה.", "לא נכון. התסמינים מתוארים בפסקה השלישית, לא באחרונה.", "לא נכון. הפופולריות של השעונים מתוארת בפסקה הראשונה.", "נכון. הפסקה האחרונה מראה כיצד המאבק המשפטי השפיע על זכות העובדים לתבוע ועל קביעת מגבלות בטיחות לקרינה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=radium-girls, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the sentence "the company's own chemists handled the same material behind lead screens and with protective tools" that —$q$, $q$["the company had good reason to know that the paint was dangerous.", "the chemists were exposed to more radium than the painters were.", "lead screens were required by law in every American factory at the time.", "the painters were also given protective equipment but chose not to use it."]$q$::jsonb, 0, $q$["נכון. אם הכימאים של החברה עצמה נזהרו מהחומר, ניתן להסיק שהחברה ידעה, או הייתה צריכה לדעת, שהצבע מסוכן — בניגוד להבטחות המפקחים.", "לא נכון. המשפט מתאר את ההגנה שקיבלו הכימאים, לא את כמות החשיפה שלהם; הצבעיות דווקא בלעו רדיום.", "לא נכון. הקטע אינו מזכיר חוק כלשהו שחייב מגני עופרת.", "לא נכון. הפסקה כותבת שלצבעיות נאמר שהצבע אינו מזיק, ואינה מזכירה ציוד מגן שניתן להן."]$q$::jsonb, $q$inference$q$, $q$anchor$q$, $q$["the company's own chemists handled the same material behind lead screens and with protective tools"]$q$::jsonb, $q$shabbat batch H, passage=radium-girls, q5$q$, 5, true);
  end if;
end $$;
do $$ declare v_pid uuid; begin

  if not exists (select 1 from reading_passages where title = $q$Jonas Salk and the Polio Vaccine$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Jonas Salk and the Polio Vaccine$q$, $q$In the early 1950s, polio was one of the most feared diseases in the United States. The virus struck mainly children, and in the worst cases it paralyzed the muscles needed for walking or even breathing. The epidemic of 1952 alone caused nearly 58,000 reported cases across the country. Parents kept their children away from swimming pools and crowded places every summer, when outbreaks were most common.

Jonas Salk, a researcher at the University of Pittsburgh, took an approach that many experts doubted. Rather than using a weakened living virus, he killed the virus with formaldehyde and injected the inactive material to trigger immunity. His work was funded largely by the March of Dimes, a charity that collected small donations from millions of ordinary Americans. In 1954, more than a million schoolchildren, known as Polio Pioneers, took part in one of the largest medical trials ever conducted. On April 12, 1955, the results were announced to the world: the vaccine was safe and effective.

The announcement was greeted with church bells and public celebrations. When a television interviewer asked Salk who owned the patent, he replied that there was no patent and asked whether anyone could patent the sun. Within a few years, an oral vaccine developed by Albert Sabin, which was cheaper and easier to give, largely replaced Salk's injections in many countries. Nevertheless, the two vaccines together drove polio out of the Americas by the 1990s. Salk spent his later years at the research institute in California that bears his name.$q$, $q$medicine / history$q$, 4, 248, true, $q$reading_shabbat_2026-09-05_H$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["The March of Dimes raised money from millions of ordinary Americans.", "Salk's vaccine, tested on a huge scale, turned polio from a feared disease into a preventable one.", "Albert Sabin's oral vaccine eventually replaced Salk's injections in many countries.", "The polio epidemic of 1952 caused nearly 58,000 cases in the United States."]$q$::jsonb, 1, $q$["לא נכון. זו קביעה נכונה מהפסקה השנייה, אך היא פרט על מימון המחקר ולא הרעיון המרכזי.", "נכון. הקטע מתאר את הפחד מפוליו, את החיסון של סאלק, את הניסוי הענק ואת התוצאה — הכחדת המחלה מיבשת אמריקה.", "לא נכון. זו קביעה נכונה מהפסקה השלישית, אך היא פרט משני בסוף הקטע.", "לא נכון. זו קביעה נכונה מהפסקה הראשונה, אך היא רק רקע לסיפור החיסון."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch H, passage=salk-polio, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, how did Salk's method differ from what many experts expected?$q$, $q$["He tested the vaccine only on adult volunteers rather than on schoolchildren.", "He relied on government money instead of private donations.", "He used a killed virus instead of a weakened live one.", "He gave the vaccine by mouth rather than by injection."]$q$::jsonb, 2, $q$["לא נכון. הפסקה מספרת שיותר ממיליון ילדי בית ספר השתתפו בניסוי.", "לא נכון. הפסקה כותבת שהמחקר מומן בעיקר בידי ארגון צדקה שאסף תרומות קטנות, לא בידי הממשלה.", "נכון. הפסקה אומרת שבמקום נגיף חי מוחלש, סאלק המית את הנגיף בפורמלדהיד והזריק את החומר הלא פעיל.", "לא נכון. החיסון של סאלק ניתן בהזרקה; החיסון דרך הפה היה של סייבין, לפי הפסקה השלישית."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=salk-polio, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, why were children kept away from "swimming pools and crowded places"?$q$, $q$["because the vaccine had not yet been tested there", "because the March of Dimes recommended it", "because paralyzed children could not swim safely", "because polio outbreaks were most common in summer"]$q$::jsonb, 3, $q$["לא נכון. הפסקה הראשונה אינה קושרת את ההרחקה לבדיקת החיסון.", "לא נכון. ארגון מארץ אוף דיימס מוזכר בפסקה השנייה כמממן, לא כמי שהמליץ להרחיק ילדים.", "לא נכון. הקטע אינו טוען שילדים משותקים לא יכלו לשחות.", "נכון. הפסקה הראשונה אומרת שההורים הרחיקו את ילדיהם ממקומות אלה בכל קיץ, כשההתפרצויות היו הנפוצות ביותר."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["swimming pools and crowded places every summer, when outbreaks were most common"]$q$::jsonb, $q$shabbat batch H, passage=salk-polio, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["describe the public reaction to the vaccine and its long-term results.", "explain how the vaccine was produced from killed virus.", "describe the fear that polio caused among American parents.", "explain why the March of Dimes funded Salk's research."]$q$::jsonb, 0, $q$["נכון. הפסקה האחרונה מתארת את החגיגות, את תשובתו של סאלק על הפטנט ואת היעלמות הפוליו מיבשת אמריקה.", "לא נכון. שיטת ייצור החיסון מוסברת בפסקה השנייה.", "לא נכון. הפחד של ההורים מתואר בפסקה הראשונה.", "לא נכון. המימון מוזכר בפסקה השנייה, והקטע אינו מסביר מדוע הארגון בחר לממן את סאלק."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=salk-polio, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the second paragraph, the word "trigger" is closest in meaning to —$q$, $q$["delay for a long time", "set off", "measure carefully and precisely", "completely prevent something"]$q$::jsonb, 1, $q$["לא נכון. המילה אינה עוסקת בעיכוב; החומר נועד להפעיל תגובה, לא לדחות אותה.", "נכון. 'trigger' פירושו להפעיל או לעורר — החומר הלא פעיל הוזרק כדי לעורר חסינות.", "לא נכון. המילה אינה עוסקת במדידה.", "לא נכון. המטרה הייתה לעורר חסינות, לא למנוע אותה."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["trigger immunity"]$q$::jsonb, $q$shabbat batch H, passage=salk-polio, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$Antibiotic Resistance$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Antibiotic Resistance$q$, $q$When Alexander Fleming accepted the Nobel Prize in 1945, he issued a warning that few people took seriously. Penicillin, he cautioned, could be rendered useless if patients took too little of it, because the bacteria that survived a weak dose would learn to withstand it. His prediction has proven remarkably accurate. Today, infections that were once trivial to treat are increasingly caused by organisms on which the standard drugs no longer have any effect.

The underlying mechanism is ordinary natural selection operating at extraordinary speed. Bacteria reproduce in minutes rather than years, and random mutations occasionally produce an individual that can survive a particular antibiotic. Each course of the drug then eliminates its competitors and leaves the resistant strain free to multiply. Moreover, bacteria can exchange small rings of DNA called plasmids, so a resistance gene can pass between unrelated species without waiting for inheritance. Widespread use of antibiotics in agriculture, where they are routinely added to animal feed, has intensified this selective pressure.

The problem is aggravated by economics as much as by biology. Developing a new antibiotic is expensive, yet the resulting drug is used sparingly and for short periods, so pharmaceutical companies see little prospect of profit. Consequently, hardly any genuinely new classes of antibiotics have reached the market in recent decades. Public health agencies now promote careful stewardship, which means prescribing antibiotics only when they are truly necessary and completing the full course. Whether such measures can outpace the evolution of the bacteria remains an open question.$q$, $q$medicine / biology$q$, 6, 250, true, $q$reading_shabbat_2026-09-05_H$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, all of the following are true EXCEPT —$q$, $q$["Random mutations can produce bacteria that survive a given antibiotic.", "Resistance genes can move between unrelated species through plasmids.", "Antibiotics used in agriculture are too weak to affect bacterial evolution.", "A course of antibiotics removes the competitors of resistant bacteria."]$q$::jsonb, 2, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — מוטציות אקראיות אכן יוצרות חיידקים עמידים.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — גנים לעמידות אכן עוברים בין מינים דרך פלסמידים.", "נכון. זו הקביעה השגויה — הפסקה אומרת שהשימוש בחקלאות דווקא הגביר את לחץ הברירה, ולא שהאנטיביוטיקה שם חלשה מכדי להשפיע.", "לא נכון. זו קביעה נכונה על פי הפסקה השנייה, ולכן אינה החריג המבוקש — כל מחזור טיפול מחסל את המתחרים ומשאיר את הזן העמיד."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=antibiotic-resist, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the third paragraph, why are pharmaceutical companies reluctant to develop new antibiotics?$q$, $q$["Regulators have banned the sale of new antibiotics in most countries.", "Bacteria evolve resistance before the drugs can be approved.", "Public health agencies refuse to recommend newly developed drugs.", "The drugs are used only briefly and sparingly, which limits the potential profits."]$q$::jsonb, 3, $q$["לא נכון. הפסקה אינה מזכירה איסור כלשהו של רגולטורים.", "לא נכון. הפסקה מדברת על התפתחות עמידות באופן כללי, לא על עמידות שמופיעה לפני אישור התרופה.", "לא נכון. הפסקה אומרת שסוכנויות הבריאות מקדמות שימוש זהיר, לא שהן מסרבות להמליץ על תרופות חדשות.", "נכון. הפסקה השלישית כותבת שהפיתוח יקר אך התרופה נמכרת במשורה ולתקופות קצרות, ולכן החברות רואות סיכוי קטן לרווח."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=antibiotic-resist, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the first paragraph is to —$q$, $q$["show that the crisis was foreseen decades ago.", "explain how bacteria exchange genetic material with one another.", "describe the economic obstacles to developing new antibiotic drugs.", "describe the circumstances under which Fleming first discovered penicillin."]$q$::jsonb, 0, $q$["נכון. הפסקה הראשונה פותחת באזהרה של פלמינג מ-1945 ומראה שתחזיתו התגשמה — כלומר המשבר נצפה מראש.", "לא נכון. חילופי החומר הגנטי (פלסמידים) מוסברים בפסקה השנייה.", "לא נכון. המכשולים הכלכליים מתוארים בפסקה השלישית.", "לא נכון. הפסקה מזכירה את קבלת פרס הנובל, אך אינה מתארת כיצד התגלה הפניצילין."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=antibiotic-resist, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the third paragraph that —$q$, $q$["stewardship programs have already reversed the spread of resistance.", "market forces alone are unlikely to solve the shortage of new antibiotics.", "the author believes bacteria will inevitably defeat every human countermeasure.", "completing a full course of antibiotics is no longer recommended by health agencies."]$q$::jsonb, 1, $q$["לא נכון. הפסקה מסיימת בשאלה פתוחה אם האמצעים יצליחו, ולכן אי אפשר להסיק שהם כבר הפכו את המגמה.", "נכון. הפסקה מסבירה שהחברות אינן רואות סיכוי לרווח ולכן כמעט לא פותחו תרופות חדשות — מכאן שהשוק לבדו אינו צפוי לפתור את המחסור.", "לא נכון. זו הגזמה — הכותב משאיר את השאלה פתוחה ואינו טוען שהחיידקים ינצחו בהכרח.", "לא נכון. הפסקה אומרת בדיוק ההפך — השלמת מחזור הטיפול המלא היא חלק מהשימוש הזהיר שהסוכנויות מקדמות."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=antibiotic-resist, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the sentence "His prediction has proven remarkably accurate," the word "His" refers to —$q$, $q$["a modern patient", "the members of the Nobel Prize committee", "Alexander Fleming", "any bacterium that survives"]$q$::jsonb, 2, $q$["לא נכון. המטופלים מוזכרים במשפט הקודם כמי שנוטלים מינון נמוך, לא כמי שחזו משהו.", "לא נכון. ועדת הפרס אינה מוזכרת כלל בקטע.", "נכון. 'His' מתייחס לאלכסנדר פלמינג, שהאזהרה שלו מ-1945 היא התחזית שהתבררה כמדויקת.", "לא נכון. חיידקים אינם חוזים דבר; המשפט עוסק באזהרה של אדם."]$q$::jsonb, $q$reference_word$q$, $q$anchor$q$, $q$["His prediction has proven remarkably accurate"]$q$::jsonb, $q$shabbat batch H, passage=antibiotic-resist, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$Laennec and the Invention of the Stethoscope$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Laennec and the Invention of the Stethoscope$q$, $q$Before 1816, a doctor who wanted to listen to a patient's heart had only one method: he pressed his ear directly against the patient's chest. This technique was awkward, and it often did not work well with overweight patients. Many doctors also felt that it was improper, especially when the patient was a woman. As a result, doctors often skipped the examination altogether and relied on guesswork.

The French physician Rene Laennec faced exactly this problem one day at the Necker Hospital in Paris. A young woman came to him with symptoms of heart disease, and he was too embarrassed to place his ear on her chest. Then he remembered a game he had seen children playing in a park: one child scratched a long wooden beam with a pin while another listened at the far end. The sound traveled clearly through the wood, so Laennec rolled a sheet of paper into a tight tube and placed one end on the woman's chest. To his surprise, he could hear her heartbeat more clearly than ever before.

Laennec soon replaced the paper with a hollow wooden tube about twenty-five centimeters long. He named it the stethoscope, from two Greek words meaning chest and examine. Over the next three years, he used the instrument to describe the sounds of the lungs and heart in healthy and sick patients. He published his findings in 1819, and doctors across Europe quickly adopted the device. Sadly, Laennec died of tuberculosis in 1826, a disease that his own invention had helped doctors to recognize. However, the stethoscope remains the most recognizable symbol of the medical profession to this day.$q$, $q$medicine / history$q$, 3, 270, true, $q$reading_shabbat_2026-09-05_H$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["Heart Disease in Nineteenth-Century Paris", "How Children's Games Improved Medicine", "The Life and Death of Rene Laennec", "A Rolled Sheet of Paper That Changed Medicine"]$q$::jsonb, 3, $q$["לא נכון. מחלת הלב של המטופלת היא רק הנסיבות של הסיפור, לא הנושא של הקטע.", "לא נכון. משחק הילדים היה ההשראה לרגע אחד, אך הקטע אינו עוסק במשחקים באופן כללי.", "לא נכון. הקטע מתמקד בהמצאה אחת, לא בסיפור חייו המלא של לאנק.", "נכון. הקטע כולו מספר כיצד גיליון נייר מגולגל הוביל להמצאת הסטטוסקופ ששינה את הרפואה."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch H, passage=stethoscope, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, why did many doctors avoid listening to the chest?$q$, $q$["They found the method awkward and sometimes improper.", "They believed the heart could not be heard through the chest.", "They preferred to use the newly invented stethoscope instead.", "They were afraid of catching tuberculosis from their patients."]$q$::jsonb, 0, $q$["נכון. הפסקה הראשונה כותבת שהשיטה הייתה מסורבלת, לא עבדה היטב עם מטופלים כבדים, ונחשבה לא הולמת — ולכן רופאים דילגו על הבדיקה.", "לא נכון. הפסקה אינה טוענת שהרופאים חשבו שאי אפשר לשמוע את הלב.", "לא נכון. הסטטוסקופ עדיין לא הומצא לפני 1816, לפי הפסקאות הבאות.", "לא נכון. שחפת מוזכרת רק בפסקה השלישית, בהקשר של מותו של לאנק."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=stethoscope, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["explain why Laennec died of tuberculosis in 1826.", "describe the moment that led Laennec to his invention.", "describe how doctors examined patients before 1816.", "explain the Greek origin of the word stethoscope."]$q$::jsonb, 1, $q$["לא נכון. מותו של לאנק מוזכר בפסקה השלישית, והקטע אינו מסביר מדוע חלה.", "נכון. הפסקה השנייה מתארת את המפגש עם המטופלת, את זיכרון משחק הילדים ואת הניסוי עם הנייר המגולגל — הרגע שהוביל להמצאה.", "לא נכון. זהו תוכן הפסקה הראשונה.", "לא נכון. מקור השם היווני מוסבר בפסקה השלישית."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=stethoscope, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the third paragraph that —$q$, $q$["Laennec's book was ignored by doctors outside France.", "the wooden tube produced worse results than the rolled paper.", "the stethoscope helped doctors identify diseases of the lungs.", "Laennec named the instrument after the young woman he had examined."]$q$::jsonb, 2, $q$["לא נכון. הפסקה כותבת שרופאים ברחבי אירופה אימצו את המכשיר במהירות.", "לא נכון. הפסקה אומרת שלאנק החליף את הנייר בצינור עץ, ואינה רומזת שהתוצאות היו גרועות יותר.", "נכון. הפסקה מספרת שלאנק תיאר את קולות הריאות בחולים, ושהמצאתו סייעה לרופאים לזהות שחפת — מחלת ריאות.", "לא נכון. הפסקה מסבירה שהשם מגיע משתי מילים יווניות, לא משמה של המטופלת."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=stethoscope, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the second paragraph, the word "embarrassed" most nearly means —$q$, $q$["physically exhausted after a long day", "very angry", "unable to hear properly", "ashamed"]$q$::jsonb, 3, $q$["לא נכון. המילה אינה עוסקת בעייפות גופנית.", "לא נכון. לאנק לא כעס; הוא חש אי נוחות.", "לא נכון. הבעיה לא הייתה בשמיעה אלא ברגשות של הרופא.", "נכון. 'embarrassed' פירושו נבוך או מתבייש — לאנק התבייש להצמיד את אוזנו לחזה של המטופלת."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["too embarrassed"]$q$::jsonb, $q$shabbat batch H, passage=stethoscope, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$Circadian Rhythms and Jet Lag$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Circadian Rhythms and Jet Lag$q$, $q$Nearly every living organism, from bacteria to humans, keeps an internal clock that runs on a cycle of roughly twenty-four hours. These circadian rhythms govern when we feel sleepy, when body temperature rises and falls, and when hormones are released into the blood. In humans, the master clock is a small cluster of cells in the hypothalamus called the suprachiasmatic nucleus. It receives signals directly from the eyes, so daylight resets the clock each morning and keeps it aligned with the outside world.

Left on its own, however, the human clock does not run at exactly twenty-four hours. Experiments in which volunteers lived in caves or sealed rooms without any time cues showed that the cycle tends to drift slightly longer. Ordinarily this small error is corrected by morning light, and nobody notices it. The scientists who identified the genes controlling the clock in fruit flies were awarded the Nobel Prize in 2017.

Jet lag occurs when rapid travel across several time zones separates the internal clock from the local day. A passenger flying from New York to Paris arrives to find breakfast being served while the body insists that it is still the middle of the night. Fatigue, poor concentration, and disturbed digestion follow until the clock gradually catches up. Because the clock naturally runs slow, most people find it easier to stay up later than to fall asleep earlier. Consequently, eastward journeys, which demand an earlier bedtime, usually produce worse jet lag than westward ones.

Although no cure exists, the timing of light exposure can speed recovery considerably. Travelers heading east are advised to seek bright morning light at their destination and to avoid it in the evening. Small doses of the hormone melatonin, taken at the right moment, may also help shift the clock. Similar strategies are used by night-shift workers, whose schedules conflict with their rhythms week after week.$q$, $q$science / biology$q$, 5, 312, true, $q$reading_shabbat_2026-09-05_H$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Which of the following is NOT mentioned in the first paragraph?$q$, $q$["the hormone melatonin", "the location of the master clock", "the length of the cycle", "the role of daylight"]$q$::jsonb, 0, $q$["נכון. מלטונין מוזכר רק בפסקה האחרונה; הפסקה הראשונה מדברת על הורמונים באופן כללי בלבד. למה לשים לב: השאלה מוגבלת לפסקה הראשונה.", "לא נכון. הפסקה הראשונה מציינת שהשעון הראשי נמצא בהיפותלמוס, ולכן פרט זה מוזכר.", "לא נכון. הפסקה הראשונה מציינת שהמחזור נמשך כעשרים וארבע שעות, ולכן פרט זה מוזכר.", "לא נכון. הפסקה הראשונה מסבירה שאור היום מאפס את השעון בכל בוקר, ולכן פרט זה מוזכר."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=jet-lag, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, why do "eastward journeys" usually cause worse jet lag?$q$, $q$["because flights to the east are usually longer and more tiring", "because they require going to sleep earlier, which the naturally slow clock resists", "because morning light is weaker in eastern countries", "because melatonin is less effective after eastward travel"]$q$::jsonb, 1, $q$["לא נכון. הקטע אינו מזכיר את אורך הטיסות או את העייפות מהן.", "נכון. הפסקה השלישית מסבירה שהשעון נוטה לפגר, ולכן קל יותר להישאר ערים מאוחר מאשר להירדם מוקדם — ונסיעה מזרחה דורשת בדיוק שעת שינה מוקדמת יותר.", "לא נכון. הקטע אינו משווה את עוצמת האור בין מדינות.", "לא נכון. הקטע אינו טוען שמלטונין פחות יעיל בכיוון מסוים."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["eastward journeys, which demand an earlier bedtime, usually produce worse jet lag than westward ones"]$q$::jsonb, $q$shabbat batch H, passage=jet-lag, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["explain the practical advice given to travelers heading east.", "describe how the suprachiasmatic nucleus receives light signals from the eyes each morning.", "show that the internal clock is slightly inaccurate on its own.", "describe the symptoms that follow a long flight across time zones."]$q$::jsonb, 2, $q$["לא נכון. העצות למטיילים מופיעות בפסקה האחרונה.", "לא נכון. קליטת האותות מהעיניים מתוארת בפסקה הראשונה.", "נכון. הפסקה השנייה מתארת ניסויים במערות ובחדרים אטומים שהראו שהשעון נוטה לסטות מעט כשאין לו רמזי זמן.", "לא נכון. תסמיני היעפת מתוארים בפסקה השלישית."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=jet-lag, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["explain why the clock drifts longer than twenty-four hours.", "describe the experiments conducted in caves and sealed rooms.", "explain the biological cause of jet lag.", "describe practical ways to reduce the effects of jet lag."]$q$::jsonb, 3, $q$["לא נכון. הסטייה של השעון מתוארת בפסקה השנייה, והקטע אינו מסביר מדוע היא קורית.", "לא נכון. הניסויים במערות מתוארים בפסקה השנייה.", "לא נכון. הסיבה הביולוגית ליעפת מוסברת בפסקה השלישית.", "נכון. הפסקה האחרונה מציעה דרכים מעשיות — תזמון חשיפה לאור ומלטונין — להאצת ההתאוששות מיעפת."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=jet-lag, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the passage, what can be inferred about a traveler flying westward from Paris to New York?$q$, $q$["The traveler would need to stay awake later, which the clock finds easier.", "The traveler would experience no jet lag at all.", "The traveler should avoid morning light entirely.", "The traveler would suffer far more severely than someone making the same journey eastward."]$q$::jsonb, 0, $q$["נכון. נסיעה מערבה דורשת להישאר ערים מאוחר יותר, והקטע מסביר שזה קל יותר לשעון הגוף מאשר להירדם מוקדם.", "לא נכון. הקטע אומר שנסיעות מערבה גורמות ליעפת קלה יותר, לא שאין יעפת כלל.", "לא נכון. העצה להימנע מאור בערב ניתנת למי שנוסע מזרחה; הקטע אינו ממליץ להימנע לחלוטין מאור בוקר.", "לא נכון. הקטע אומר את ההפך — נסיעות מזרחה בדרך כלל קשות יותר מנסיעות מערבה."]$q$::jsonb, $q$inference$q$, $q$text$q$, null, $q$shabbat batch H, passage=jet-lag, q5$q$, 5, true);
