  if not exists (select 1 from reading_passages where title = $q$The Hygiene Hypothesis$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Hygiene Hypothesis$q$, $q$Over the past century, allergic conditions such as asthma, hay fever, and eczema have become far more common in wealthy industrialized countries. Genetic change cannot explain a shift this rapid, so researchers have looked instead to the environment. In 1989, the British epidemiologist David Strachan noticed a curious pattern in the medical records of thousands of children. Those who grew up with several older siblings were considerably less likely to develop hay fever than those who did not.

Strachan proposed that infections caught from older brothers and sisters in early childhood somehow protected the developing immune system. In a smaller, cleaner family, he suggested, the immune system received too little practice and later overreacted to harmless substances such as pollen. The idea became known as the hygiene hypothesis, and it quickly captured public attention. Subsequent studies appeared to support it: children raised on traditional farms, surrounded by animals and soil, showed strikingly low rates of asthma.

Nevertheless, many immunologists now regard the original name as misleading. The infections that cause colds and flu do not appear to offer any protection, and improved hygiene has saved countless lives. According to a revised version, sometimes called the old friends hypothesis, what matters is early contact with the harmless microbes that humans coexisted with for most of their evolutionary history. These organisms, found in soil, water, and animals, seem to train the immune system to tolerate what it should ignore. Modern urban life, with its sterile surfaces and limited contact with nature, may deprive children of that education.

The debate has practical consequences, because it shapes advice to parents. Few scientists recommend abandoning handwashing or vaccines, yet many encourage outdoor play, contact with pets, and a varied diet. The hypothesis remains a hypothesis, and the mechanisms are far from settled. What is clear is that the immune system does not develop in isolation but in constant conversation with the microbial world.$q$, $q$medicine / biology$q$, 6, 317, true, $q$reading_shabbat_2026-09-05_H$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["Children with several older siblings are less likely to suffer from hay fever.", "The link between early microbial exposure and allergies is well supported but still being refined.", "Improved hygiene has saved countless lives and should never be abandoned.", "Children raised on traditional farms have strikingly low rates of asthma."]$q$::jsonb, 1, $q$["לא נכון. זו קביעה נכונה מהפסקה הראשונה, אך היא התצפית שממנה התחיל הרעיון ולא הרעיון המרכזי.", "נכון. הקטע מציג את ההשערה, את הראיות התומכות בה, את הגרסה המתוקנת שלה ואת העובדה שהמנגנונים עדיין לא הוכרעו.", "לא נכון. זו קביעה נכונה מהפסקה השלישית, אך היא הסתייגות אחת ולא הרעיון המרכזי של הקטע.", "לא נכון. זו קביעה נכונה מהפסקה השנייה, אך היא ראיה אחת בלבד לתמיכה בהשערה."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch H, passage=hygiene-hyp, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, how did Strachan explain the protective effect of siblings?$q$, $q$["Older siblings taught younger children to avoid pollen and other irritants.", "Larger families lived in rural areas with more exposure to farm animals.", "Early infections gave the immune system the practice it needed.", "Children in large families received more medical attention from their doctors."]$q$::jsonb, 2, $q$["לא נכון. הפסקה אינה מזכירה שאחים לימדו ילדים להימנע מאבקה.", "לא נכון. החוות מוזכרות במחקרים מאוחרים יותר, ולא כהסבר של סטרכן לאפקט האחים.", "נכון. הפסקה השנייה כותבת שסטרכן הציע שזיהומים שנתפסו מאחים גדולים העניקו למערכת החיסון את ה'אימון' שהיא זקוקה לו.", "לא נכון. הפסקה אינה מזכירה טיפול רפואי כלשהו."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=hygiene-hyp, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the third paragraph is to —$q$, $q$["describe the pattern Strachan found in children's medical records.", "explain why parents should encourage outdoor play and contact with pets.", "describe the low rates of asthma among children raised on farms.", "present a revised version of the hypothesis that corrects its original name."]$q$::jsonb, 3, $q$["לא נכון. התצפית של סטרכן מתוארת בפסקה הראשונה.", "לא נכון. העצות להורים מופיעות בפסקה האחרונה.", "לא נכון. הילדים בחוות מוזכרים בסוף הפסקה השנייה.", "נכון. הפסקה השלישית מסבירה מדוע השם המקורי מטעה ומציגה את השערת 'החברים הוותיקים' כגרסה מתוקנת."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=hygiene-hyp, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the last paragraph that —$q$, $q$["the author considers the scientific question still unresolved.", "most scientists now advise parents to stop washing their children's hands.", "the immune system develops entirely on its own, without outside influence.", "vaccines are believed to weaken the immune system."]$q$::jsonb, 0, $q$["נכון. הפסקה אומרת שההשערה נותרה השערה ושהמנגנונים 'רחוקים מלהיות מוכרעים' — כלומר השאלה עדיין פתוחה.", "לא נכון. הפסקה כותבת שמעטים המדענים שממליצים לוותר על שטיפת ידיים.", "לא נכון. הפסקה אומרת בדיוק ההפך — מערכת החיסון מתפתחת 'בשיחה מתמדת' עם עולם החיידקים.", "לא נכון. החיסונים מוזכרים כדבר שאין לוותר עליו, ולא כגורם מחליש."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch H, passage=hygiene-hyp, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the second paragraph, the word "overreacted" most nearly means —$q$, $q$["completely failed to notice", "responded too strongly", "gradually adapted", "became permanently immune"]$q$::jsonb, 1, $q$["לא נכון. המילה מתארת תגובה מוגזמת, לא היעדר תגובה.", "נכון. 'overreacted' פירושו הגיב בעוצמה רבה מדי — מערכת החיסון תקפה חומרים לא מזיקים כמו אבקה.", "לא נכון. הסתגלות הדרגתית היא ההפך מתגובת יתר.", "לא נכון. חסינות קבועה היא ההפך מהתגובה המוגזמת שהמילה מתארת."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["overreacted to harmless substances"]$q$::jsonb, $q$shabbat batch H, passage=hygiene-hyp, q5$q$, 5, true);
  end if;
end $$;
do $$ declare v_pid uuid; begin

  if not exists (select 1 from reading_passages where title = $q$The Voyager Golden Record$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Voyager Golden Record$q$, $q$In 1977, NASA launched two spacecraft, Voyager 1 and Voyager 2, to study the outer planets of the solar system. Each spacecraft carried a gold-plated copper disc known as the Golden Record, intended as a message to any intelligent beings who might one day find it. A committee led by the astronomer Carl Sagan selected the contents over a period of several months. The record contains greetings in dozens of languages, natural sounds such as wind and thunder, and a selection of music from many cultures. It also holds encoded images showing human anatomy, landscapes, and scenes of everyday life.

Designing a message for an unknown audience raised unusual problems. The committee could not assume that the finders would share any human language, alphabet, or musical tradition. Instead, the cover of the record was engraved with diagrams explaining how to play it and how to decode the images. One diagram uses the properties of the hydrogen atom as a basic unit of time, since hydrogen is the most common element in the universe. The team hoped that a scientifically advanced civilization would recognize these universal references even without any knowledge of Earth.

Realistically, the chance that the record will ever be found is extremely small. Space is vast, and the Voyagers will not pass close to another star for tens of thousands of years. Yet Sagan and his colleagues argued that the project mattered regardless of whether anyone ever heard it. The record forced its creators to decide what was most worth saying about humanity and to present it in a form free of national boundaries. In this sense, the Golden Record was as much a message to people on Earth as it was a message to the stars.$q$, $q$science / space$q$, 4, 286, true, $q$reading_shabbat_2026-09-05_I$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["The Golden Record was a carefully designed message to unknown finders whose deepest value may lie in what it says about humanity itself.", "The Voyager spacecraft were launched in 1977 in order to photograph and study the outer planets of the solar system.", "The hydrogen atom was chosen as a universal unit of time because it is the most common element in the universe.", "The Golden Record is unlikely to be found because the Voyagers will not approach another star for many thousands of years."]$q$::jsonb, 0, $q$["נכון. הקטע כולו מתאר את עיצוב התקליט כמסר לנמענים לא ידועים, ומסיים בקביעה שערכו האמיתי הוא במה שהוא אומר על האנושות.", "לא נכון. זו קביעה נכונה מהפסקה הראשונה, אך היא רק הרקע לשיגור ולא הרעיון המרכזי של הקטע.", "לא נכון. זהו פרט טכני אחד מהפסקה השנייה, ולא הרעיון המרכזי של הקטע כולו.", "לא נכון. זו קביעה נכונה מהפסקה השלישית, אך הקטע דווקא טוען שהפרויקט היה חשוב למרות סיכוי זה."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch I, passage=golden-record, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, all of the following are true EXCEPT —$q$, $q$["The two Voyager spacecraft were sent to investigate the outer planets of the solar system.", "The Golden Record was manufactured from solid gold to help it survive for a long time.", "A committee headed by Carl Sagan chose what the record would contain.", "The disc includes natural sounds and music alongside spoken greetings in many languages."]$q$::jsonb, 1, $q$["לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — החלליות אכן נשלחו לחקור את כוכבי הלכת החיצוניים.", "נכון. זו הקביעה השגויה — הפסקה כותבת שהתקליט הוא דיסק נחושת מצופה זהב, לא זהב טהור, ואינה מזכירה שיקולי עמידות.", "לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — ועדה בראשות קרל סייגן אכן בחרה את התכנים.", "לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — התקליט אכן כולל צלילי טבע, מוזיקה וברכות בשפות רבות."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Each spacecraft carried a gold-plated copper disc known as the Golden Record"]$q$::jsonb, $q$shabbat batch I, passage=golden-record, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["list the kinds of sounds, music, and images that were chosen for the record.", "argue that the record will almost certainly never be discovered by anyone.", "explain how the designers tried to make the record understandable to beings with no knowledge of Earth.", "describe the months of work that Carl Sagan's committee devoted to the project."]$q$::jsonb, 2, $q$["לא נכון. זהו תוכן הפסקה הראשונה — רשימת התכנים — ולא הפסקה השנייה.", "לא נכון. זהו תוכן הפסקה השלישית — הסיכוי הקטן שהתקליט יימצא — ולא הפסקה השנייה.", "נכון. הפסקה מתארת את הבעיה של קהל לא ידוע ואת הפתרון: תרשימים ומידות אוניברסליות כמו אטום המימן, שיאפשרו למוצאים להבין את התקליט.", "לא נכון. עבודת הוועדה מוזכרת בקצרה בפסקה הראשונה, והפסקה השנייה אינה עוסקת בה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch I, passage=golden-record, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the third paragraph, the word "vast" is closest in meaning to —$q$, $q$["completely empty of any objects or matter", "extremely cold and dark in every direction", "dangerous for spacecraft traveling at high speed", "enormous in size"]$q$::jsonb, 3, $q$["לא נכון. המילה מתארת גודל, לא ריקנות.", "לא נכון. המילה אינה עוסקת בטמפרטורה או בחושך.", "לא נכון. המילה אינה מתארת סכנה.", "נכון. 'vast' פירושו עצום בגודלו — ולכן החלליות לא יתקרבו לכוכב אחר במשך עשרות אלפי שנים."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["Space is vast"]$q$::jsonb, $q$shabbat batch I, passage=golden-record, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the third paragraph that —$q$, $q$["the creators regarded the act of making the record as worthwhile in itself.", "Sagan and his colleagues expected the record to be found within a few centuries.", "the record was designed mainly to promote the interests of a single nation.", "the project was eventually cancelled because its chances of success were so low."]$q$::jsonb, 0, $q$["נכון. הפסקה מציינת שסייגן ועמיתיו טענו שהפרויקט חשוב בלי קשר לשאלה אם מישהו ישמע אותו, ושהוא חייב את יוצריו להחליט מה ראוי לומר על האנושות.", "לא נכון. הפסקה כותבת שהסיכוי שהתקליט יימצא קטן ביותר ושהמסע לכוכב אחר יארך עשרות אלפי שנים.", "לא נכון. הפסקה מדגישה שהתקליט הוצג בצורה החופשית מגבולות לאומיים.", "לא נכון. הפסקה אינה מזכירה ביטול; התקליט שוגר עם החלליות."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch I, passage=golden-record, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$The Discovery of Neptune by Mathematics$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$The Discovery of Neptune by Mathematics$q$, $q$For most of human history, the known solar system ended at Saturn. That changed in 1781, when William Herschel discovered Uranus with a telescope, the first planet found in recorded history. Astronomers soon calculated the orbit that Uranus should follow according to Newton's law of gravitation. However, over the following decades, careful observations showed that the planet kept drifting slightly from its predicted path. Some scientists began to suspect that an unseen body beyond Uranus was pulling on it.

Two young mathematicians took up the problem independently. In England, John Couch Adams worked out where such a planet would have to be in order to produce the observed disturbances. In France, Urbain Le Verrier reached a similar solution and sent his prediction to the Berlin Observatory in 1846. On the very night the letter arrived, the astronomer Johann Galle pointed his telescope at the indicated region and found the new planet within one degree of Le Verrier's position. The discovery was hailed across Europe as a triumph of pure calculation.

The episode carried a lesson that went beyond the addition of one planet to the catalogue. Neptune had been located with pen and paper before anyone deliberately looked for it in the sky. This demonstrated that Newton's laws could not only describe known motions but also predict the existence of objects that had never been seen. A bitter dispute later arose between British and French scientists over who deserved the credit. Today, most historians recognize both Adams and Le Verrier, although Le Verrier's prediction was the one that actually guided the telescope.$q$, $q$science / astronomy$q$, 5, 260, true, $q$reading_shabbat_2026-09-05_I$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$An appropriate title for this text would be —$q$, $q$["William Herschel and the Telescope That Found Uranus", "A Planet Predicted on Paper Before It Was Seen", "The Long Rivalry Between British and French Astronomers", "How Johann Galle Became Famous in a Single Night"]$q$::jsonb, 1, $q$["לא נכון. גילוי אורנוס הוא רק הרקע בפסקה הראשונה, ולא נושא הקטע.", "נכון. הקטע כולו עוסק בכך שנפטון חושב מראש בעזרת מתמטיקה ורק אחר כך נצפה בטלסקופ.", "לא נכון. המחלוקת על הקרדיט מוזכרת רק בקצרה בפסקה השלישית.", "לא נכון. גאלה מוזכר במשפט אחד בלבד, והקטע אינו עוסק בפרסומו."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch I, passage=neptune, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, why did some scientists suspect the existence of an unseen body beyond Uranus?$q$, $q$["Herschel had reported seeing a faint object near Uranus through his telescope.", "Newton's law of gravitation stated that there must be an even number of planets.", "Uranus kept straying slightly from its predicted orbit.", "The orbit of Saturn had also begun to show unexplained irregularities."]$q$::jsonb, 2, $q$["לא נכון. הפסקה אינה מזכירה שהרשל ראה עצם נוסף.", "לא נכון. הפסקה אינה מייחסת לחוק ניוטון קביעה על מספר כוכבי הלכת.", "נכון. הפסקה כותבת שתצפיות הראו שאורנוס סטה מעט מהמסלול שחושב לו, ולכן חשדו בגוף בלתי נראה שמושך אותו.", "לא נכון. הפסקה מזכירה את שבתאי רק כגבול מערכת השמש הידועה, ולא סטיות במסלולו."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["the planet kept drifting slightly from its predicted path"]$q$::jsonb, $q$shabbat batch I, passage=neptune, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["explain why Uranus was drifting away from its expected path.", "argue that Adams deserved more credit than Le Verrier for the discovery.", "discuss the broader lesson that the discovery held for physics.", "describe how two mathematicians predicted the planet's position and how it was then confirmed."]$q$::jsonb, 3, $q$["לא נכון. זהו תוכן הפסקה הראשונה — הסטייה של אורנוס — ולא הפסקה השנייה.", "לא נכון. הפסקה אינה מכריעה בשאלת הקרדיט; המחלוקת מוזכרת רק בפסקה השלישית.", "לא נכון. זהו תוכן הפסקה השלישית — הלקח הרחב — ולא הפסקה השנייה.", "נכון. הפסקה מתארת את החישובים העצמאיים של אדמס ולה ורייה ואת האישור בטלסקופ של גאלה בברלין."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch I, passage=neptune, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, what happened "on the very night the letter arrived"?$q$, $q$["An astronomer in Berlin located the planet close to the predicted spot.", "Le Verrier traveled to Berlin to observe the planet himself.", "Adams published his own calculations in England for the first time.", "Scientists in Paris announced that the calculation had been mistaken."]$q$::jsonb, 0, $q$["נכון. הפסקה השנייה כותבת שבאותו לילה גאלה כיוון את הטלסקופ לאזור שצוין ומצא את כוכב הלכת במרחק מעלה אחת מהמיקום החזוי.", "לא נכון. לה ורייה שלח מכתב לברלין; הקטע אינו אומר שהוא נסע לשם.", "לא נכון. הקטע אינו קושר בין אותו לילה לפרסום של אדמס.", "לא נכון. הקטע אינו מזכיר הודעה כזו; החישוב התברר כנכון."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["On the very night the letter arrived, the astronomer Johann Galle pointed his telescope at the indicated region"]$q$::jsonb, $q$shabbat batch I, passage=neptune, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the passage, what can be inferred about the significance of Neptune's discovery?$q$, $q$["It proved that telescopes were no longer needed for discovering new planets.", "It strengthened confidence that Newton's laws could reveal things not yet observed.", "It showed that Herschel's original discovery of Uranus had been an error.", "It settled once and for all who deserved credit for the prediction."]$q$::jsonb, 1, $q$["לא נכון. הטלסקופ היה נחוץ כדי לאשר את התחזית; הקטע אינו טוען שהוא מיותר.", "נכון. הפסקה השלישית קובעת שהגילוי הוכיח שחוקי ניוטון יכולים לחזות קיומם של עצמים שמעולם לא נראו.", "לא נכון. הקטע אינו מטיל ספק בגילוי אורנוס.", "לא נכון. הפסקה השלישית מתארת מחלוקת מרה שנמשכה לאחר הגילוי."]$q$::jsonb, $q$inference$q$, $q$text$q$, null, $q$shabbat batch I, passage=neptune, q5$q$, 5, true);
