      values (v_pid, $q$What is the main idea of the passage?$q$, $q$["The Hubble Space Telescope cost far more than its planners had originally expected.", "Astronauts on the shuttle Endeavour carried out a series of difficult spacewalks in 1993.", "A faulty measuring device caused the telescope's mirror to be polished to the wrong shape.", "A tiny manufacturing flaw nearly ruined Hubble, but a clever repair turned it into a triumph."]$q$::jsonb, 3, $q$["לא נכון. העלות מוזכרת רק במשפט הפתיחה, ואינה הנושא.", "לא נכון. ההליכות בחלל הן פרט מהפסקה השלישית בלבד.", "לא נכון. זו הסיבה לפגם, המתוארת בפסקה השנייה, אך היא רק חלק מהסיפור ולא הרעיון המרכזי.", "נכון. הקטע מספר על הפגם הזעיר, על הסבר מקורו ועל התיקון שהפך את הטלסקופ למכשיר מדעי מצליח — וזה הרעיון המרכזי."]$q$::jsonb, $q$main_idea$q$, $q$text$q$, null, $q$shabbat batch I, passage=hubble-mirror, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, what caused the mirror to be made in the wrong shape?$q$, $q$["A testing device used during production had been put together wrongly.", "The mirror had been polished too quickly and without sufficient care.", "The mirror was damaged by vibration during the launch of the shuttle.", "Engineers had chosen a mirror design that was too large for the telescope."]$q$::jsonb, 0, $q$["נכון. הפסקה כותבת שמכשיר מדידה ששימש בייצור הורכב בצורה שגויה.", "לא נכון. הפסקה מדגישה שהמראה לוטשה בדיוק רב — הבעיה הייתה במפרט, לא בזהירות.", "לא נכון. הקטע אינו מזכיר נזק בשיגור.", "לא נכון. הקטע אינו מזכיר בעיה בגודל המראה."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["a measuring instrument used during manufacturing had been assembled incorrectly"]$q$::jsonb, $q$shabbat batch I, passage=hubble-mirror, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["explain why even a very small error in a mirror has a large effect on its images.", "describe the repair and Hubble's later achievements.", "describe the first disappointing pictures that Hubble sent back to Earth.", "criticize the engineers who failed to detect the problem before launch."]$q$::jsonb, 1, $q$["לא נכון. זהו תוכן הפסקה השנייה — ההסבר להשפעת סטייה זעירה — ולא הפסקה האחרונה.", "נכון. הפסקה מתארת את המראות המתקנות, את התיקון ב-1993 ואת ההישגים המדעיים שבאו אחריו.", "לא נכון. זהו תוכן הפסקה הראשונה — התמונות המטושטשות — ולא הפסקה האחרונה.", "לא נכון. הפסקה אינה מבקרת את המהנדסים; היא מציגה את התיקון כהצלחה הנדסית."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch I, passage=hubble-mirror, q3$q$, 3, true);
