  if not exists (select 1 from reading_passages where title = $q$Why the Tower of Pisa Leans$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Why the Tower of Pisa Leans$q$, $q$The bell tower of Pisa, in northern Italy, is one of the most famous buildings in the world, and it is famous mainly because of a mistake. Construction began in 1173, and within a few years, when only three floors were complete, the tower started to tilt. The cause was the ground beneath it. The builders had laid a shallow foundation on soft soil made of clay, sand, and mud, and the weight of the stone pressed unevenly into it. The southern side sank more than the northern side, and the tower began to lean.

Work stopped for almost a century, partly because Pisa was busy fighting wars with its neighbors. The long pause probably saved the building, since the soil had time to settle and harden under the weight. When construction resumed, the builders tried to correct the tilt by making the upper floors slightly taller on the leaning side. The result is that the tower is actually curved rather than straight. The structure was finally completed in the fourteenth century, still leaning.

Over the following centuries, the tilt slowly grew worse, and by 1990 the tower leaned about five and a half degrees from vertical. Engineers feared it might collapse, so the building was closed to visitors. Instead of pulling the tower upright, which could have damaged it, the team carefully removed small amounts of soil from beneath the higher northern side. This allowed the top of the tower to move back toward vertical by more than forty centimeters. It reopened in 2001, and today it is expected to remain stable for at least two hundred years.$q$, $q$engineering / history$q$, 3, 266, true, $q$reading_shabbat_2026-09-05_I$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, all of the following are true EXCEPT —$q$, $q$["The tower's foundation was shallow and rested on soft ground.", "The southern side of the tower sank more deeply than the northern side.", "Building work on the tower began in 1173.", "The tower started to lean only after all its floors had been finished."]$q$::jsonb, 3, $q$["לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — היסודות היו רדודים והקרקע רכה.", "לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — הצד הדרומי שקע יותר מהצפוני.", "לא נכון. זו קביעה נכונה על פי הפסקה הראשונה, ולכן אינה החריג המבוקש — הבנייה החלה ב-1173.", "נכון. זו הקביעה השגויה — הפסקה כותבת שהמגדל החל לנטות כשרק שלוש קומות הושלמו, לא לאחר סיום הבנייה."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["when only three floors were complete, the tower started to tilt"]$q$::jsonb, $q$shabbat batch I, passage=pisa, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["explain how a long interruption and later building choices shaped the tower.", "describe the soft soil that caused the tower to lean in the first place.", "describe the modern engineering work that made the tower safe again.", "explain why Pisa was fighting wars with its neighbors in the Middle Ages."]$q$::jsonb, 0, $q$["נכון. הפסקה מתארת את ההפסקה בת מאה השנה שכנראה הצילה את המבנה, ואת ניסיון הבנאים לתקן את הנטייה בקומות העליונות.", "לא נכון. זהו תוכן הפסקה הראשונה — הקרקע הרכה — ולא הפסקה השנייה.", "לא נכון. זהו תוכן הפסקה השלישית — העבודה ההנדסית המודרנית — ולא הפסקה השנייה.", "לא נכון. המלחמות מוזכרות רק כסיבה להפסקת העבודה, והפסקה אינה מסבירה אותן."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch I, passage=pisa, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the second paragraph, the word "resumed" most nearly means —$q$, $q$["was finally completed after many years", "started again after a pause", "was moved to a different location", "was stopped for a second time"]$q$::jsonb, 1, $q$["לא נכון. המילה מתארת חידוש, לא סיום; ההשלמה מוזכרת בנפרד בסוף הפסקה.", "נכון. 'resumed' פירושו התחדש לאחר הפסקה — הבנייה נמשכה אחרי כמעט מאה שנות עצירה.", "לא נכון. המילה אינה עוסקת במיקום.", "לא נכון. זהו ההפך — המילה מתארת חזרה לעבודה, לא עצירה נוספת."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["When construction resumed"]$q$::jsonb, $q$shabbat batch I, passage=pisa, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the third paragraph that —$q$, $q$["the engineers believed the tower could never be made safe.", "the soil beneath the southern side was removed to reduce the tilt.", "the engineers intended to reduce the lean rather than remove it entirely.", "visitors were allowed to climb the tower throughout the repair work."]$q$::jsonb, 2, $q$["לא נכון. הפסקה מסיימת בכך שהמגדל צפוי להישאר יציב מאתיים שנה לפחות.", "לא נכון. הפסקה כותבת שהאדמה הוסרה מתחת לצד הצפוני הגבוה יותר, לא הדרומי.", "נכון. הפסקה כותבת שהצוות נמנע מליישר את המגדל מחשש לנזק, ואפשר לו לחזור רק חלקית לכיוון האנך — כלומר הכוונה הייתה להקטין את הנטייה ולא לבטלה.", "לא נכון. הפסקה כותבת שהמגדל נסגר למבקרים ונפתח מחדש רק ב-2001."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch I, passage=pisa, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the passage, why was the tower "closed to visitors"?$q$, $q$["Because the city of Pisa wanted to sell tickets at a higher price after the repairs.", "Because the builders needed to add taller floors on the leaning side.", "Because the tower was being prepared for its official completion ceremony.", "Because experts worried that it could fall."]$q$::jsonb, 3, $q$["לא נכון. הקטע אינו מזכיר כרטיסים או מחירים.", "לא נכון. הגבהת הקומות מתוארת בפסקה השנייה, מאות שנים לפני הסגירה.", "לא נכון. המגדל הושלם במאה הארבע עשרה; הסגירה הייתה ב-1990.", "נכון. הפסקה השלישית כותבת שמהנדסים חששו שהמגדל עלול לקרוס, ולכן הוא נסגר."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["Engineers feared it might collapse, so the building was closed to visitors"]$q$::jsonb, $q$shabbat batch I, passage=pisa, q5$q$, 5, true);
