    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$It can be inferred from the second paragraph that —$q$, $q$["written calculation with Roman numerals was more cumbersome than with the Indian system.", "Brahmagupta succeeded in giving division by zero a clear and lasting definition.", "Indian mathematicians borrowed the concept of zero from the Babylonians.", "the place-value system was invented in Europe before it reached India."]$q$::jsonb, 0, $q$["נכון. הפסקה כותבת שהשיטה ההודית הפכה את החישוב הכתוב לפשוט בהרבה מהספרות הרומיות, ומכאן שהחישוב בספרות רומיות היה מסורבל יותר.", "לא נכון. הפסקה כותבת שברהמגופטה 'ניסה' להגדיר חלוקה באפס, ולא שהצליח.", "לא נכון. הפסקה אינה מזכירה קשר בין בבל להודו; הבבלים נדונו רק בפסקה הראשונה.", "לא נכון. הפסקה מציגה את שיטת המקום כחלק מההישג ההודי, ואינה טוענת שמקורה באירופה."]$q$::jsonb, $q$inference$q$, $q$paragraph$q$, null, $q$shabbat batch I, passage=zero, q5$q$, 5, true);
