  if not exists (select 1 from reading_passages where title = $q$Why Pluto Is No Longer a Planet$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Why Pluto Is No Longer a Planet$q$, $q$For seventy-six years, schoolchildren learned that the solar system had nine planets. The ninth, Pluto, was discovered in 1930 by Clyde Tombaugh, a young astronomer at the Lowell Observatory in Arizona. It was a distant, faint object, far smaller than any of the other planets, and its orbit was unusually tilted and elongated. Nevertheless, it was welcomed as a planet, and for decades nobody seriously questioned that status.

The doubts began in the 1990s, when astronomers started finding other icy bodies beyond Neptune. Pluto, it turned out, was not alone but was one member of a vast belt of similar objects. The decisive moment came in 2005 with the discovery of Eris, a body that appeared to be at least as large as Pluto. Astronomers faced a choice: either Eris and perhaps dozens of similar objects would have to become planets, or Pluto would have to be reclassified.

In August 2006, the International Astronomical Union adopted the first formal definition of a planet. Under the new rules, a planet must orbit the sun, be massive enough for gravity to pull it into a round shape, and have cleared its orbital neighborhood of other objects. Pluto satisfies the first two conditions but not the third, since it shares its region with countless other bodies. It was therefore placed in a new category called dwarf planets, along with Eris and the asteroid Ceres.

The decision provoked strong public reaction, and some scientists still argue that it was a mistake. Yet the change reflects how science works: categories are revised when new evidence no longer fits them. Pluto did not change in 2006; rather, our understanding of the region in which it lives did. Whether it is called a planet or not, the small world remains as fascinating as ever.$q$, $q$science / astronomy$q$, 4, 293, true, $q$reading_shabbat_2026-09-05_I$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the third paragraph, all of the following are true EXCEPT —$q$, $q$["The definition adopted in 2006 was the first formal one for a planet.", "Pluto fails to meet the definition because it is not round enough.", "A planet must have cleared its orbital neighborhood of other objects.", "Ceres and Eris were placed in the same category as Pluto."]$q$::jsonb, 1, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — זו הייתה ההגדרה הפורמלית הראשונה.", "נכון. זו הקביעה השגויה — הפסקה כותבת שפלוטו עומד בשני התנאים הראשונים, כולל הצורה העגולה, ונכשל רק בתנאי השלישי.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — פינוי הסביבה המסלולית הוא התנאי השלישי.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש — קרס ואריס סווגו יחד עם פלוטו ככוכבי לכת ננסיים."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Pluto satisfies the first two conditions but not the third"]$q$::jsonb, $q$shabbat batch I, passage=pluto, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["describe the discovery of Pluto at the Lowell Observatory in 1930.", "present the three conditions that a body must meet to be called a planet.", "explain how new discoveries beyond Neptune forced astronomers to reconsider Pluto's status.", "argue that the decision to reclassify Pluto was a scientific mistake."]$q$::jsonb, 2, $q$["לא נכון. זהו תוכן הפסקה הראשונה — גילוי פלוטו — ולא הפסקה השנייה.", "לא נכון. זהו תוכן הפסקה השלישית — שלושת התנאים — ולא הפסקה השנייה.", "נכון. הפסקה מתארת את גילוי החגורה של גופים קפואים ואת גילוי אריס, שהעמידו את האסטרונומים בפני הכרעה על מעמדו של פלוטו.", "לא נכון. הפסקה אינה טוענת שההחלטה הייתה טעות; הדעה הזו מוזכרת רק בפסקה הרביעית כעמדת חלק מהמדענים."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch I, passage=pluto, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the last paragraph is to —$q$, $q$["list the objects that were added to the category of dwarf planets.", "describe the unusual orbit and small size of Pluto.", "explain why the discovery of Eris was so important.", "present the reclassification as a natural part of how science revises its categories."]$q$::jsonb, 3, $q$["לא נכון. הגופים בקטגוריה החדשה מוזכרים בפסקה השלישית.", "לא נכון. המסלול והגודל של פלוטו מתוארים בפסקה הראשונה.", "לא נכון. חשיבות גילוי אריס מוסברת בפסקה השנייה.", "נכון. הפסקה מציגה את ההחלטה, למרות ההתנגדות, כדוגמה לאופן שבו המדע מעדכן קטגוריות לאור ראיות חדשות."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch I, passage=pluto, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the statement that "Pluto did not change in 2006," what can be inferred about the author's view?$q$, $q$["The reclassification says more about scientific knowledge than about Pluto itself.", "The decision of the International Astronomical Union should be reversed.", "Pluto's orbit became less tilted and elongated after the decision.", "Astronomers had known about the belt beyond Neptune since 1930."]$q$::jsonb, 0, $q$["נכון. המשפט ממשיך ואומר שמה שהשתנה הוא ההבנה שלנו לגבי האזור שבו פלוטו נמצא — כלומר השינוי הוא בידע המדעי, לא בגוף עצמו.", "לא נכון. המחבר מציג את ההחלטה כחלק טבעי מהמדע ואינו קורא לבטלה.", "לא נכון. המשפט אומר בדיוק את ההפך — פלוטו עצמו לא השתנה.", "לא נכון. הפסקה השנייה כותבת שהגופים מעבר לנפטון התגלו רק בשנות התשעים."]$q$::jsonb, $q$inference$q$, $q$anchor$q$, $q$["Pluto did not change in 2006; rather, our understanding of the region in which it lives did"]$q$::jsonb, $q$shabbat batch I, passage=pluto, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, which of the following was true of Pluto at the time of its discovery?$q$, $q$["It was immediately recognized as part of a belt of similar objects.", "It was accepted as a planet despite being unusually small and having an odd orbit.", "It was found by a team of astronomers working in several countries.", "It was thought to be larger than several of the other known planets."]$q$::jsonb, 1, $q$["לא נכון. החגורה של גופים דומים התגלתה רק בשנות התשעים, לפי הפסקה השנייה.", "נכון. הפסקה כותבת שפלוטו היה קטן בהרבה מכוכבי הלכת האחרים ובעל מסלול מוטה ומוארך, ובכל זאת התקבל ככוכב לכת.", "לא נכון. הפסקה מייחסת את הגילוי לאסטרונום צעיר אחד, קלייד טומבו, במצפה לואל באריזונה.", "לא נכון. הפסקה כותבת שהוא היה קטן בהרבה מכל כוכבי הלכת האחרים."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Nevertheless, it was welcomed as a planet, and for decades nobody seriously questioned that status"]$q$::jsonb, $q$shabbat batch I, passage=pluto, q5$q$, 5, true);
  end if;
